export interface GitHubRepo {
  name: string;
  stargazers_count: number;
  [key: string]: unknown;
}

const GITHUB_API_BASE = "https://api.github.com";

function parseNextLink(linkHeader: string | null): string | null {
  if (!linkHeader) return null;
  for (const part of linkHeader.split(",")) {
    const match = part.match(/<([^>]+)>;\s*rel="([^"]+)"/);
    if (match && match[2] === "next") {
      return match[1];
    }
  }
  return null;
}

export async function fetchAllUserRepos(username: string): Promise<GitHubRepo[]> {
  const repos: GitHubRepo[] = [];
  let url: string | null = `${GITHUB_API_BASE}/users/${encodeURIComponent(username)}/repos?per_page=100`;

  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
  };
  const token = process.env.GITHUB_TOKEN;
  if (token) {
    headers.Authorization = `Bearer ${token}`;
  }

  while (url) {
    const response: Response = await fetch(url, { headers });
    if (!response.ok) {
      throw new Error(`GitHub API request failed: ${response.status} ${response.statusText}`);
    }
    const page = (await response.json()) as GitHubRepo[];
    repos.push(...page);
    url = parseNextLink(response.headers.get("Link"));
  }

  return repos;
}

export async function fetchTopStarredRepos(username: string, count = 5): Promise<GitHubRepo[]> {
  const repos = await fetchAllUserRepos(username);
  return repos
    .slice()
    .sort((a, b) => b.stargazers_count - a.stargazers_count)
    .slice(0, count);
}

import { fetchTopStarredRepos } from "./github.js";

async function main() {
  const username = process.argv[2];
  if (!username) {
    console.error("Usage: cli <github-username>");
    process.exitCode = 1;
    return;
  }

  const topRepos = await fetchTopStarredRepos(username);
  for (const repo of topRepos) {
    console.log(`${repo.name}: ${repo.stargazers_count}`);
  }
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
});

