export interface RetryOptions {
  /** Maximum number of attempts, including the first one. Defaults to 3. */
  attempts?: number;
  /** Base delay in milliseconds for the first retry. Defaults to 200. */
  baseDelayMs?: number;
  /** Maximum delay in milliseconds between retries. Defaults to 5000. */
  maxDelayMs?: number;
  /** Randomization factor in [0, 1] applied to the computed delay. Defaults to 0.5. */
  jitter?: number;
  /** Called before each retry with the error and the attempt number that failed (1-indexed). */
  onRetry?: (error: unknown, attempt: number) => void;
}

const DEFAULT_OPTIONS: Required<Omit<RetryOptions, "onRetry">> = {
  attempts: 3,
  baseDelayMs: 200,
  maxDelayMs: 5000,
  jitter: 0.5,
};

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function computeDelay(attempt: number, options: Required<Omit<RetryOptions, "onRetry">>): number {
  const exponential = options.baseDelayMs * 2 ** (attempt - 1);
  const capped = Math.min(exponential, options.maxDelayMs);
  const jitterRange = capped * options.jitter;
  const jitterOffset = (Math.random() * 2 - 1) * jitterRange;
  return Math.max(0, Math.round(capped + jitterOffset));
}

/**
 * Retries an async function with exponential backoff and jitter.
 * Rethrows the last error if all attempts fail.
 */
export async function retry<T>(fn: () => Promise<T>, options: RetryOptions = {}): Promise<T> {
  const resolved = { ...DEFAULT_OPTIONS, ...options };
  let lastError: unknown;

  for (let attempt = 1; attempt <= resolved.attempts; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      if (attempt === resolved.attempts) {
        break;
      }
      options.onRetry?.(error, attempt);
      await sleep(computeDelay(attempt, resolved));
    }
  }

  throw lastError;
}

import { retry } from "./retry.js";

const BATCH_SIZE = 50;

export interface SyncResult {
  totalBatches: number;
  succeededBatches: number;
  failedBatches: FailedBatch[];
}

export interface FailedBatch {
  batchIndex: number;
  recordCount: number;
  error: unknown;
}

function chunk<T>(items: T[], size: number): T[][] {
  const batches: T[][] = [];
  for (let i = 0; i < items.length; i += size) {
    batches.push(items.slice(i, i + size));
  }
  return batches;
}

function getEndpointConfig(): { url: string; token: string } {
  const url = process.env.SYNC_ENDPOINT_URL;
  const token = process.env.SYNC_AUTH_TOKEN;

  if (!url) {
    throw new Error("Missing required environment variable: SYNC_ENDPOINT_URL");
  }
  if (!token) {
    throw new Error("Missing required environment variable: SYNC_AUTH_TOKEN");
  }

  return { url, token };
}

async function uploadBatch(url: string, token: string, records: unknown[]): Promise<void> {
  const response = await fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({ records }),
  });

  if (!response.ok) {
    throw new Error(`Upload failed with status ${response.status}: ${response.statusText}`);
  }
}

/**
 * Uploads records to the configured HTTP endpoint in batches of 50, retrying
 * each batch with exponential backoff. Returns a summary including any
 * batches that failed after exhausting retries.
 */
export async function syncRecords(records: unknown[]): Promise<SyncResult> {
  const { url, token } = getEndpointConfig();
  const batches = chunk(records, BATCH_SIZE);
  const failedBatches: FailedBatch[] = [];
  let succeededBatches = 0;

  for (let i = 0; i < batches.length; i++) {
    const batch = batches[i];
    try {
      await retry(() => uploadBatch(url, token, batch), {
        attempts: 5,
        baseDelayMs: 300,
        maxDelayMs: 10_000,
      });
      succeededBatches++;
    } catch (error) {
      failedBatches.push({ batchIndex: i, recordCount: batch.length, error });
    }
  }

  return { totalBatches: batches.length, succeededBatches, failedBatches };
}

function reportResult(result: SyncResult): void {
  console.log(
    `Sync complete: ${result.succeededBatches}/${result.totalBatches} batches succeeded.`,
  );

  if (result.failedBatches.length > 0) {
    console.error(`${result.failedBatches.length} batch(es) failed:`);
    for (const failure of result.failedBatches) {
      const message = failure.error instanceof Error ? failure.error.message : String(failure.error);
      console.error(`  - batch ${failure.batchIndex} (${failure.recordCount} records): ${message}`);
    }
  }
}

export async function main(records: unknown[]): Promise<void> {
  const result = await syncRecords(records);
  reportResult(result);
  if (result.failedBatches.length > 0) {
    process.exitCode = 1;
  }
}

export interface RetryOptions {
  /** Maximum number of attempts, including the first call. */
  attempts?: number;
  /** Base delay in milliseconds used for the exponential backoff. */
  baseDelayMs?: number;
  /** Upper bound on the delay between attempts, in milliseconds. */
  maxDelayMs?: number;
  /** Adds random jitter (0 to 1) as a fraction of the computed delay. */
  jitter?: number;
  /** Called after a failed attempt, before waiting to retry. */
  onRetry?: (error: unknown, attempt: number) => void;
}

const DEFAULT_OPTIONS: Required<Omit<RetryOptions, "onRetry">> = {
  attempts: 3,
  baseDelayMs: 200,
  maxDelayMs: 5000,
  jitter: 0.1,
};

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function computeDelay(attempt: number, baseDelayMs: number, maxDelayMs: number, jitter: number): number {
  const exponential = baseDelayMs * 2 ** (attempt - 1);
  const capped = Math.min(exponential, maxDelayMs);
  const jitterAmount = capped * jitter * Math.random();
  return capped + jitterAmount;
}

/**
 * Runs an async function, retrying with exponential backoff on failure.
 * Throws the last error if all attempts are exhausted.
 */
export async function retry<T>(fn: () => Promise<T>, options: RetryOptions = {}): Promise<T> {
  const { attempts, baseDelayMs, maxDelayMs, jitter } = { ...DEFAULT_OPTIONS, ...options };
  const onRetry = options.onRetry;

  let lastError: unknown;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      if (attempt === attempts) {
        break;
      }
      onRetry?.(error, attempt);
      await sleep(computeDelay(attempt, baseDelayMs, maxDelayMs, jitter));
    }
  }
  throw lastError;
}

