async function uploadBatch(endpointUrl: string, authToken: string, batch: unknown[]): Promise<void> {
  const response = await fetch(endpointUrl, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${authToken}`,
    },
    body: JSON.stringify({ records: batch }),
  });

  if (!response.ok) {
    throw new Error(`Upload failed with status ${response.status}: ${response.statusText}`);
  }
}

/**
 * Uploads records to the configured HTTP endpoint in batches, retrying each
 * batch with exponential backoff. Returns a summary including any batches
 * that failed after all retries were exhausted.
 */
export async function syncRecords(records: unknown[]): Promise<SyncResult> {
  const endpointUrl = getEndpointUrl();
  const authToken = getAuthToken();
  const batches = chunk(records, BATCH_SIZE);
  const failedBatches: FailedBatch[] = [];

