    } catch (error) {
      failedBatches.push({ batchIndex: i, records: batch, error });
    }
  }

  const result: SyncResult = { totalBatches: batches.length, failedBatches };
  reportResult(result);
  return result;
}

function reportResult(result: SyncResult): void {
  if (result.failedBatches.length === 0) {
    console.log(`Sync complete: all ${result.totalBatches} batch(es) uploaded successfully.`);
    return;
  }

  console.error(
    `Sync finished with ${result.failedBatches.length} of ${result.totalBatches} batch(es) failed:`,
  );
  for (const failure of result.failedBatches) {
    console.error(
      `  - Batch ${failure.batchIndex} (${failure.records.length} records): ${
        failure.error instanceof Error ? failure.error.message : String(failure.error)
      }`,
    );
  }
}

import { TokenBucketRateLimiter, RateLimiterOptions } from "./rateLimiter.js";

export interface MinimalSocket {
  remoteAddress?: string;
}

export interface MinimalRequest {
  ip?: string;
  socket?: MinimalSocket;
  headers: Record<string, string | string[] | undefined>;
}

export interface MinimalResponse {
  statusCode: number;
  setHeader(name: string, value: string | number): void;
  end(chunk?: string): void;
}

export type NextFunction = (err?: unknown) => void;

export type RateLimitMiddleware = (
  req: MinimalRequest,
  res: MinimalResponse,
  next: NextFunction
) => void;

function resolveClientIp(req: MinimalRequest): string {
  if (req.ip) return req.ip;
  const forwarded = req.headers["x-forwarded-for"];
  const forwardedIp = Array.isArray(forwarded) ? forwarded[0] : forwarded;
  if (forwardedIp) return forwardedIp.split(",")[0].trim();
  return req.socket?.remoteAddress ?? "unknown";
}

export function createRateLimitMiddleware(options: RateLimiterOptions): RateLimitMiddleware {
  const limiter = new TokenBucketRateLimiter(options);
  limiter.startCleanup();

  return (req, res, next) => {
    const key = resolveClientIp(req);
    const result = limiter.consume(key);

    if (!result.allowed) {
      const retryAfterSeconds = Math.max(1, Math.ceil(result.retryAfterMs / 1000));
      res.statusCode = 429;
      res.setHeader("Retry-After", retryAfterSeconds);
      res.end("Too Many Requests");
      return;
    }

    next();
  };
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

export interface RateLimiterOptions {
  /** Maximum number of tokens a bucket can hold. */
  capacity: number;
  /** Tokens added per millisecond. */
  refillRatePerMs: number;
  /** How long a bucket may sit idle before it's considered stale and evicted, in ms. */
  staleAfterMs?: number;
  /** How often to sweep for stale buckets, in ms. */
  cleanupIntervalMs?: number;
  now?: () => number;
}

export interface ConsumeResult {
  allowed: boolean;
  /** Tokens remaining in the bucket after this attempt. */
  remaining: number;
  /** Milliseconds until a token will next be available (0 if allowed). */
  retryAfterMs: number;
}

export class TokenBucketRateLimiter {
  private readonly buckets = new Map<string, Bucket>();
  private readonly capacity: number;
  private readonly refillRatePerMs: number;
  private readonly staleAfterMs: number;
  private readonly now: () => number;
  private readonly cleanupIntervalMs: number;
  private cleanupTimer: ReturnType<typeof setInterval> | null = null;

  constructor(options: RateLimiterOptions) {
    if (options.capacity <= 0) {
      throw new Error("capacity must be positive");
    }
    if (options.refillRatePerMs <= 0) {
      throw new Error("refillRatePerMs must be positive");
    }
    this.capacity = options.capacity;
    this.refillRatePerMs = options.refillRatePerMs;
    this.staleAfterMs = options.staleAfterMs ?? 10 * 60 * 1000;
    this.cleanupIntervalMs = options.cleanupIntervalMs ?? 60 * 1000;
    this.now = options.now ?? Date.now;
  }

  /** Starts a periodic sweep that evicts buckets idle longer than staleAfterMs. */
  startCleanup(): void {
    if (this.cleanupTimer) return;
    this.cleanupTimer = setInterval(() => this.cleanupStaleBuckets(), this.cleanupIntervalMs);
  }

  stopCleanup(): void {
    if (this.cleanupTimer) {
      clearInterval(this.cleanupTimer);
      this.cleanupTimer = null;
    }
  }

  cleanupStaleBuckets(): void {
    const now = this.now();
    for (const [key, bucket] of this.buckets) {
      if (now - bucket.lastRefill >= this.staleAfterMs) {
        this.buckets.delete(key);
      }
    }
  }

  private getBucket(key: string): Bucket {
    const now = this.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.capacity, lastRefill: now };
      this.buckets.set(key, bucket);
      return bucket;
    }
    const elapsed = now - bucket.lastRefill;
    if (elapsed > 0) {
      bucket.tokens = Math.min(this.capacity, bucket.tokens + elapsed * this.refillRatePerMs);
      bucket.lastRefill = now;
    }
    return bucket;
  }

  /** Attempts to consume `cost` tokens (default 1) from the bucket for `key`. */
  consume(key: string, cost = 1): ConsumeResult {
    const bucket = this.getBucket(key);
    if (bucket.tokens >= cost) {
      bucket.tokens -= cost;
      return { allowed: true, remaining: bucket.tokens, retryAfterMs: 0 };
    }
    const deficit = cost - bucket.tokens;
    const retryAfterMs = Math.ceil(deficit / this.refillRatePerMs);
    return { allowed: false, remaining: bucket.tokens, retryAfterMs };
  }

  reset(key: string): void {
    this.buckets.delete(key);
  }

  size(): number {
    return this.buckets.size;
  }
}

export interface RetryOptions {
  /** Maximum number of attempts, including the first one. */
  attempts?: number;
  /** Base delay in milliseconds, doubled after each failed attempt. */
  baseDelayMs?: number;
  /** Upper bound on the computed delay, in milliseconds. */
  maxDelayMs?: number;
  /** Randomization factor in [0, 1] applied to the delay to avoid thundering herds. */
  jitter?: number;
  /** Called after each failed attempt, before waiting to retry. */
  onRetry?: (error: unknown, attempt: number, delayMs: number) => void;
}

const DEFAULT_OPTIONS: Required<Omit<RetryOptions, "onRetry">> = {
  attempts: 3,
  baseDelayMs: 200,
  maxDelayMs: 10_000,
  jitter: 0.1,
};

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function computeDelay(attempt: number, options: Required<Omit<RetryOptions, "onRetry">>): number {
  const exponential = options.baseDelayMs * 2 ** (attempt - 1);
  const capped = Math.min(exponential, options.maxDelayMs);
  const jitterRange = capped * options.jitter;
  const jitterOffset = (Math.random() * 2 - 1) * jitterRange;
  return Math.max(0, Math.round(capped + jitterOffset));
}

/**
 * Runs `fn`, retrying with exponential backoff (plus jitter) on failure.
 * Throws the last encountered error once all attempts are exhausted.
 */
export async function retryWithBackoff<T>(fn: () => Promise<T>, options: RetryOptions = {}): Promise<T> {
  const merged = { ...DEFAULT_OPTIONS, ...options };

  let lastError: unknown;
  for (let attempt = 1; attempt <= merged.attempts; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      if (attempt === merged.attempts) {
        break;
      }
      const delayMs = computeDelay(attempt, merged);
      options.onRetry?.(error, attempt, delayMs);
      await sleep(delayMs);
    }
  }

  throw lastError;
}

import { retryWithBackoff } from "./retry.js";

const BATCH_SIZE = 50;

export interface SyncResult {
  totalBatches: number;
  failedBatches: FailedBatch[];
}

export interface FailedBatch {
  batchIndex: number;
  recordCount: number;
  error: unknown;
}

function chunk<T>(items: T[], size: number): T[][] {
  const chunks: T[][] = [];
  for (let i = 0; i < items.length; i += size) {
    chunks.push(items.slice(i, i + size));
  }
  return chunks;
}

function getEndpointUrl(): string {
  const url = process.env.SYNC_ENDPOINT_URL;
  if (!url) {
    throw new Error("Missing required environment variable: SYNC_ENDPOINT_URL");
  }
  return url;
}

function getAuthToken(): string {
  const token = process.env.SYNC_AUTH_TOKEN;
  if (!token) {
    throw new Error("Missing required environment variable: SYNC_AUTH_TOKEN");
  }
  return token;
}

async function uploadBatch(endpointUrl: string, authToken: string, batch: unknown[]): Promise<void> {
  const response = await fetch(endpointUrl, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${authToken}`,
    },
    body: JSON.stringify({ records: batch }),
  });

  if (!response.ok) {
    throw new Error(`Upload failed with status ${response.status}: ${response.statusText}`);
  }
}

/**
 * Uploads `records` to the configured HTTP endpoint in batches of 50,
 * retrying each batch with exponential backoff. Batches that still fail
 * after all retries are collected and reported at the end rather than
 * aborting the whole sync.
 */
export async function syncRecords(records: unknown[]): Promise<SyncResult> {
  const endpointUrl = getEndpointUrl();
  const authToken = getAuthToken();
  const batches = chunk(records, BATCH_SIZE);
  const failedBatches: FailedBatch[] = [];

  for (let batchIndex = 0; batchIndex < batches.length; batchIndex++) {
    const batch = batches[batchIndex];
    try {
      await retryWithBackoff(() => uploadBatch(endpointUrl, authToken, batch), {
        attempts: 4,
        baseDelayMs: 500,
        maxDelayMs: 15_000,
        jitter: 0.2,
      });
    } catch (error) {
      failedBatches.push({ batchIndex, recordCount: batch.length, error });
    }
  }

  reportFailedBatches(failedBatches);

  return { totalBatches: batches.length, failedBatches };
}

function reportFailedBatches(failedBatches: FailedBatch[]): void {
  if (failedBatches.length === 0) {
    return;
  }

  console.error(`${failedBatches.length} batch(es) failed to upload:`);
  for (const failure of failedBatches) {
    console.error(
      `  Batch ${failure.batchIndex} (${failure.recordCount} records): ${
        failure.error instanceof Error ? failure.error.message : String(failure.error)
      }`,
    );
  }
}

import { RateLimiter, RateLimiterOptions } from "./rateLimiter.js";

/** Minimal subset of Express's Request type needed to identify a client. */
export interface MinimalRequest {
  ip?: string;
  socket?: { remoteAddress?: string };
  headers: Record<string, string | string[] | undefined>;
}

/** Minimal subset of Express's Response type needed to send a 429. */
export interface MinimalResponse {
  status(code: number): this;
  setHeader(name: string, value: string): this;
  end(chunk?: string): void;
}

export type NextFunction = (err?: unknown) => void;

export interface RateLimitMiddlewareOptions extends RateLimiterOptions {
  /** Message body sent when a request is rejected (default: "Too Many Requests"). */
  message?: string;
}

function firstHeaderValue(value: string | string[] | undefined): string | undefined {
  return Array.isArray(value) ? value[0] : value;
}

function resolveClientIp(req: MinimalRequest): string {
  const forwarded = firstHeaderValue(req.headers["x-forwarded-for"]);
  if (forwarded) {
    return forwarded.split(",")[0].trim();
  }
  return req.ip ?? req.socket?.remoteAddress ?? "unknown";
}

/**
 * Creates an Express-compatible rate-limiting middleware backed by a
 * per-client-IP token bucket.
 */
export function createRateLimitMiddleware(
  options: RateLimitMiddlewareOptions
): (req: MinimalRequest, res: MinimalResponse, next: NextFunction) => void {
  const limiter = new RateLimiter(options);
  const message = options.message ?? "Too Many Requests";

  return (req: MinimalRequest, res: MinimalResponse, next: NextFunction): void => {
    const key = resolveClientIp(req);
    const result = limiter.consume(key);

    if (!result.allowed) {
      res
        .status(429)
        .setHeader("Retry-After", String(result.retryAfterSeconds))
        .end(message);
      return;
    }

    next();
  };
}

export interface RateLimiterOptions {
  /** Maximum number of tokens a bucket can hold. */
  capacity: number;
  /** Tokens replenished per second. */
  refillPerSecond: number;
  /** Discard a key's bucket after it has been idle this many ms (default: 10 minutes). */
  staleAfterMs?: number;
  /** How often to sweep for stale buckets, in ms (default: 1 minute). */
  sweepIntervalMs?: number;
  /** Clock override, mainly for testing. */
  now?: () => number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

export interface ConsumeResult {
  allowed: boolean;
  /** Tokens remaining in the bucket after this attempt. */
  remaining: number;
  /** Seconds to wait before the next token is available (0 if allowed). */
  retryAfterSeconds: number;
}

const DEFAULT_STALE_AFTER_MS = 10 * 60 * 1000;
const DEFAULT_SWEEP_INTERVAL_MS = 60 * 1000;

export class RateLimiter {
  private readonly buckets = new Map<string, Bucket>();
  private readonly capacity: number;
  private readonly refillPerSecond: number;
  private readonly staleAfterMs: number;
  private readonly sweepIntervalMs: number;
  private readonly now: () => number;
  private lastSweep: number;

  constructor(options: RateLimiterOptions) {
    if (options.capacity <= 0) {
      throw new Error("capacity must be > 0");
    }
    if (options.refillPerSecond <= 0) {
      throw new Error("refillPerSecond must be > 0");
    }
    this.capacity = options.capacity;
    this.refillPerSecond = options.refillPerSecond;
    this.staleAfterMs = options.staleAfterMs ?? DEFAULT_STALE_AFTER_MS;
    this.sweepIntervalMs = options.sweepIntervalMs ?? DEFAULT_SWEEP_INTERVAL_MS;
    this.now = options.now ?? Date.now;
    this.lastSweep = this.now();
  }

  /** Attempt to consume `cost` tokens (default 1) for the given key. */
  consume(key: string, cost = 1): ConsumeResult {
    const now = this.now();
    this.maybeSweep(now);

    const bucket = this.getOrCreateBucket(key, now);
    this.refill(bucket, now);

    if (bucket.tokens >= cost) {
      bucket.tokens -= cost;
      return { allowed: true, remaining: bucket.tokens, retryAfterSeconds: 0 };
    }

    const deficit = cost - bucket.tokens;
    const retryAfterSeconds = Math.ceil(deficit / this.refillPerSecond);
    return { allowed: false, remaining: bucket.tokens, retryAfterSeconds };
  }

  /** Number of buckets currently tracked (for diagnostics/tests). */
  get size(): number {
    return this.buckets.size;
  }

  private getOrCreateBucket(key: string, now: number): Bucket {
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.capacity, lastRefill: now };
      this.buckets.set(key, bucket);
    }
    return bucket;
  }

  private refill(bucket: Bucket, now: number): void {
    const elapsedSeconds = Math.max(0, now - bucket.lastRefill) / 1000;
    if (elapsedSeconds <= 0) {
      return;
    }
    bucket.tokens = Math.min(this.capacity, bucket.tokens + elapsedSeconds * this.refillPerSecond);
    bucket.lastRefill = now;
  }

  private maybeSweep(now: number): void {
    if (now - this.lastSweep < this.sweepIntervalMs) {
      return;
    }
    this.lastSweep = now;
    for (const [key, bucket] of this.buckets) {
      if (now - bucket.lastRefill >= this.staleAfterMs) {
        this.buckets.delete(key);
      }
    }
  }
}

import { TokenBucketRateLimiter, type RateLimiterOptions } from "./rateLimiter.js";

/** Minimal subset of an Express-style request needed to identify the client. */
export interface MinimalRequest {
  ip?: string;
  socket?: { remoteAddress?: string };
  headers: Record<string, string | string[] | undefined>;
}

/** Minimal subset of an Express-style response needed to reject a request. */
export interface MinimalResponse {
  status(code: number): this;
  setHeader(name: string, value: string): this;
  end(chunk?: string): void;
}

export type NextFunction = () => void;

export type RateLimitMiddleware = (
  req: MinimalRequest,
  res: MinimalResponse,
  next: NextFunction,
) => void;

function firstHeaderValue(value: string | string[] | undefined): string | undefined {
  return Array.isArray(value) ? value[0] : value;
}

/** Extracts the client IP, preferring X-Forwarded-For's first entry behind a proxy. */
function clientIp(req: MinimalRequest): string {
  const forwardedFor = firstHeaderValue(req.headers["x-forwarded-for"]);
  if (forwardedFor) {
    const [firstIp] = forwardedFor.split(",");
    return (firstIp ?? forwardedFor).trim();
  }
  return req.ip ?? req.socket?.remoteAddress ?? "unknown";
}

/**
 * Builds an Express-style middleware that rate-limits requests per client IP
 * using a token bucket, responding 429 with Retry-After when exhausted.
 */
export function createRateLimitMiddleware(
  options: RateLimiterOptions,
): RateLimitMiddleware {
  const limiter = new TokenBucketRateLimiter(options);

  return (req, res, next) => {
    const key = clientIp(req);
    const result = limiter.consume(key);

    if (result.allowed) {
      next();
      return;
    }

    res
      .status(429)
      .setHeader("Retry-After", String(result.retryAfterSec))
      .end("Too Many Requests");
  };
}

export interface RateLimiterOptions {
  /** Maximum number of tokens a bucket can hold. */
  capacity: number;
  /** Tokens added per second. */
  refillRatePerSec: number;
  /** How long a key's bucket may sit idle before it's evicted, in ms. Defaults to 10x the time to fully refill. */
  staleAfterMs?: number;
  /** Clock injection for testing. */
  now?: () => number;
}

export interface ConsumeResult {
  allowed: boolean;
  /** Tokens remaining in the bucket after this attempt. */
  remaining: number;
  /** Seconds to wait before the next token is available (0 if allowed). */
  retryAfterSec: number;
}

interface Bucket {
  tokens: number;
  lastRefillMs: number;
}

export class TokenBucketRateLimiter {
  private readonly capacity: number;
  private readonly refillRatePerSec: number;
  private readonly staleAfterMs: number;
  private readonly now: () => number;
  private readonly buckets = new Map<string, Bucket>();

  constructor(options: RateLimiterOptions) {
    if (options.capacity <= 0) {
      throw new Error("capacity must be positive");
    }
    if (options.refillRatePerSec <= 0) {
      throw new Error("refillRatePerSec must be positive");
    }
    this.capacity = options.capacity;
    this.refillRatePerSec = options.refillRatePerSec;
    this.now = options.now ?? Date.now;
    this.staleAfterMs =
      options.staleAfterMs ?? (this.capacity / this.refillRatePerSec) * 1000 * 10;
  }

  /** Number of tracked buckets. Exposed for tests/observability. */
  get size(): number {
    return this.buckets.size;
  }

  private refill(bucket: Bucket, nowMs: number): void {
    const elapsedSec = Math.max(0, nowMs - bucket.lastRefillMs) / 1000;
    if (elapsedSec <= 0) {
      return;
    }
    bucket.tokens = Math.min(
      this.capacity,
      bucket.tokens + elapsedSec * this.refillRatePerSec,
    );
    bucket.lastRefillMs = nowMs;
  }

  /**
   * Attempts to consume `cost` tokens for `key`. Also opportunistically
   * sweeps stale buckets so memory doesn't grow unbounded with churny keys.
   */
  consume(key: string, cost = 1): ConsumeResult {
    const nowMs = this.now();
    this.evictStale(nowMs);

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.capacity, lastRefillMs: nowMs };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, nowMs);
    }

    if (bucket.tokens >= cost) {
      bucket.tokens -= cost;
      return { allowed: true, remaining: bucket.tokens, retryAfterSec: 0 };
    }

    const missing = cost - bucket.tokens;
    const retryAfterSec = Math.ceil(missing / this.refillRatePerSec);
    return { allowed: false, remaining: bucket.tokens, retryAfterSec };
  }

  private evictStale(nowMs: number): void {
    for (const [key, bucket] of this.buckets) {
      if (nowMs - bucket.lastRefillMs > this.staleAfterMs) {
        this.buckets.delete(key);
      }
    }
  }
}

const SALES_TAX_RATE = 0.0825;
const LARGE_TRANSACTION_THRESHOLD = 10_000;
const RETAIL_CATEGORY = "retail";

export interface Transaction {
  date: string;
  description: string;
  category: string;
  amount: number;
}

export interface FlaggedTransaction extends Transaction {
  taxedAmount: number;
}

export interface MonthlyReport {
  /** Totals keyed as `${year}-${month}` (month zero-padded, e.g. "2024-01") -> category -> total */
  totals: Map<string, Map<string, number>>;
  flagged: FlaggedTransaction[];
}

function parseCsv(input: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let inQuotes = false;

  for (let i = 0; i < input.length; i++) {
    const char = input[i];

    if (inQuotes) {
      if (char === '"') {
        if (input[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += char;
      }
      continue;
    }

    if (char === '"') {
      inQuotes = true;
    } else if (char === ",") {
      row.push(field);
      field = "";
    } else if (char === "\n" || char === "\r") {
      if (char === "\r" && input[i + 1] === "\n") i++;
      row.push(field);
      rows.push(row);
      row = [];
      field = "";
    } else {
      field += char;
    }
  }

  if (field.length > 0 || row.length > 0) {
    row.push(field);
    rows.push(row);
  }

  return rows.filter((r) => !(r.length === 1 && r[0].trim() === ""));
}

function monthKey(dateStr: string): string {
  const date = new Date(dateStr);
  if (Number.isNaN(date.getTime())) {
    throw new Error(`Invalid date: ${dateStr}`);
  }
  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  return `${year}-${month}`;
}

function applyTax(transaction: Transaction): number {
  if (transaction.category.toLowerCase() === RETAIL_CATEGORY) {
    return transaction.amount * (1 + SALES_TAX_RATE);
  }
  return transaction.amount;
}

export function parseTransactions(csv: string): Transaction[] {
  const rows = parseCsv(csv.trim());
  if (rows.length === 0) return [];

  const [header, ...dataRows] = rows;
  const isHeader =
    header.length >= 4 &&
    header[0]?.trim().toLowerCase() === "date" &&
    header[1]?.trim().toLowerCase() === "description" &&
    header[2]?.trim().toLowerCase() === "category" &&
    header[3]?.trim().toLowerCase() === "amount";

  const records = isHeader ? dataRows : rows;

  return records
    .filter((r) => r.some((cell) => cell.trim() !== ""))
    .map(([date, description, category, amount]) => {
      const parsedAmount = Number(amount);
      if (Number.isNaN(parsedAmount)) {
        throw new Error(`Invalid amount: ${amount}`);
      }
      return {
        date: date ?? "",
        description: description ?? "",
        category: category ?? "",
        amount: parsedAmount,
      };
    });
}

export function buildMonthlyReport(csv: string): MonthlyReport {
  const transactions = parseTransactions(csv);
  const totals = new Map<string, Map<string, number>>();
  const flagged: FlaggedTransaction[] = [];

  for (const transaction of transactions) {
    const taxedAmount = applyTax(transaction);
    const key = monthKey(transaction.date);

    let categoryTotals = totals.get(key);
    if (!categoryTotals) {
      categoryTotals = new Map<string, number>();
      totals.set(key, categoryTotals);
    }
    categoryTotals.set(
      transaction.category,
      (categoryTotals.get(transaction.category) ?? 0) + taxedAmount,
    );

    if (taxedAmount > LARGE_TRANSACTION_THRESHOLD) {
      flagged.push({ ...transaction, taxedAmount });
    }
  }

  return { totals, flagged };
}

function formatCurrency(amount: number): string {
  return amount.toLocaleString("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
}

export function formatReport(report: MonthlyReport): string {
  const lines: string[] = [];
  const months = [...report.totals.keys()].sort();

  for (const month of months) {
    lines.push(`Month: ${month}`);
    const categoryTotals = report.totals.get(month)!;
    const categories = [...categoryTotals.keys()].sort();
    const rows = categories.map((category) => [
      category,
      formatCurrency(categoryTotals.get(category)!),
    ]);

    const categoryWidth = Math.max(8, ...rows.map(([c]) => c.length));
    const amountWidth = Math.max(6, ...rows.map(([, a]) => a.length));

    lines.push(`  ${"Category".padEnd(categoryWidth)}  ${"Total".padStart(amountWidth)}`);
    for (const [category, total] of rows) {
      lines.push(`  ${category.padEnd(categoryWidth)}  ${total.padStart(amountWidth)}`);
    }
    lines.push("");
  }

  if (report.flagged.length > 0) {
    lines.push("Flagged transactions (over $10,000):");
    for (const t of report.flagged) {
      lines.push(
        `  ${t.date}  ${t.description}  ${t.category}  ${formatCurrency(t.taxedAmount)}`,
      );
    }
    lines.push("");
  }

  return lines.join("\n").trimEnd() + "\n";
}

export function generateReport(csv: string): string {
  return formatReport(buildMonthlyReport(csv));
}

interface Entry<V> {
  value: V;
  expiresAt: number | null;
}

export interface LruCacheOptions {
  maxSize: number;
  ttlMs?: number;
}

export class LruCache<K, V> {
  private readonly maxSize: number;
  private readonly defaultTtlMs: number | null;
  private readonly map = new Map<K, Entry<V>>();

  constructor(options: LruCacheOptions) {
    if (options.maxSize <= 0) {
      throw new Error("maxSize must be greater than 0");
    }
    this.maxSize = options.maxSize;
    this.defaultTtlMs = options.ttlMs ?? null;
  }

  get(key: K): V | undefined {
    const entry = this.map.get(key);
    if (!entry) {
      return undefined;
    }
    if (entry.expiresAt !== null && entry.expiresAt <= Date.now()) {
      this.map.delete(key);
      return undefined;
    }
    // Refresh recency by reinserting.
    this.map.delete(key);
    this.map.set(key, entry);
    return entry.value;
  }

  has(key: K): boolean {
    return this.get(key) !== undefined;
  }

  set(key: K, value: V, ttlMs?: number): void {
    this.map.delete(key);
    const effectiveTtl = ttlMs ?? this.defaultTtlMs;
    const expiresAt = effectiveTtl !== null ? Date.now() + effectiveTtl : null;
    this.map.set(key, { value, expiresAt });
    while (this.map.size > this.maxSize) {
      const oldestKey = this.map.keys().next().value as K;
      this.map.delete(oldestKey);
    }
  }

  delete(key: K): boolean {
    return this.map.delete(key);
  }

  clear(): void {
    this.map.clear();
  }

  get size(): number {
    return this.map.size;
  }
}

import { LruCache } from "./cache.js";

export interface UserServiceOptions {
  maxSize?: number;
  ttlMs?: number;
}

export class UserService<TUser> {
  private readonly cache: LruCache<string, TUser>;
  private readonly inFlight = new Map<string, Promise<TUser>>();

  constructor(
    private readonly fetchUser: (id: string) => Promise<TUser>,
    options: UserServiceOptions = {},
  ) {
    this.cache = new LruCache<string, TUser>({
      maxSize: options.maxSize ?? 500,
      ttlMs: options.ttlMs ?? 60_000,
    });
  }

  async getUser(id: string): Promise<TUser> {
    const cached = this.cache.get(id);
    if (cached !== undefined) {
      return cached;
    }

    const pending = this.inFlight.get(id);
    if (pending) {
      return pending;
    }

    const promise = this.fetchUser(id)
      .then((user) => {
        this.cache.set(id, user);
        return user;
      })
      .finally(() => {
        this.inFlight.delete(id);
      });

    this.inFlight.set(id, promise);
    return promise;
  }

  invalidate(id: string): void {
    this.cache.delete(id);
  }

  prefetch(ids: string[]): void {
    for (const id of ids) {
      if (this.cache.has(id) || this.inFlight.has(id)) {
        continue;
      }
      void this.getUser(id).catch(() => {
        // Swallow errors for background prefetches; callers using getUser
        // for the same id will still observe a fresh rejected attempt.
      });
    }
  }
}

const RETAIL_TAX_RATE = 0.0825;
const REVIEW_THRESHOLD = 10000;

export interface Transaction {
  date: string;
  monthKey: string;
  description: string;
  category: string;
  amount: number;
  flagged: boolean;
}

export interface MonthlyCategoryTotal {
  monthKey: string;
  category: string;
  total: number;
}

export interface TransactionReport {
  monthlyTotals: MonthlyCategoryTotal[];
  flagged: Transaction[];
}

function parseCsvRows(input: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let inQuotes = false;

  for (let i = 0; i < input.length; i++) {
    const char = input[i];

    if (inQuotes) {
      if (char === '"') {
        if (input[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += char;
      }
      continue;
    }

    if (char === '"') {
      inQuotes = true;
    } else if (char === ",") {
      row.push(field);
      field = "";
    } else if (char === "\r") {
      // skip, \n handles the line break
    } else if (char === "\n") {
      row.push(field);
      rows.push(row);
      row = [];
      field = "";
    } else {
      field += char;
    }
  }

  if (field.length > 0 || row.length > 0) {
    row.push(field);
    rows.push(row);
  }

  return rows.filter((r) => r.some((cell) => cell.trim().length > 0));
}

function getMonthKey(dateStr: string): string {
  const isoMatch = /^(\d{4})-(\d{2})/.exec(dateStr.trim());
  if (isoMatch) {
    return `${isoMatch[1]}-${isoMatch[2]}`;
  }

  const parsed = new Date(dateStr);
  if (Number.isNaN(parsed.getTime())) {
    throw new Error(`Unrecognized date: ${dateStr}`);
  }
  const year = parsed.getUTCFullYear();
  const month = String(parsed.getUTCMonth() + 1).padStart(2, "0");
  return `${year}-${month}`;
}

function parseAmount(raw: string): number {
  const cleaned = raw.trim().replace(/[$,]/g, "");
  const value = Number.parseFloat(cleaned);
  if (Number.isNaN(value)) {
    throw new Error(`Unrecognized amount: ${raw}`);
  }
  return value;
}

function roundToCents(value: number): number {
  return Math.round(value * 100) / 100;
}

export function parseTransactions(csv: string): Transaction[] {
  const rows = parseCsvRows(csv);
  if (rows.length === 0) {
    return [];
  }

  const firstCell = rows[0][0]?.trim().toLowerCase();
  const dataRows = firstCell === "date" ? rows.slice(1) : rows;

  return dataRows.map((row) => {
    const [date, description, category, rawAmount] = row;
    if (date === undefined || description === undefined || category === undefined || rawAmount === undefined) {
      throw new Error(`Malformed transaction row: ${row.join(",")}`);
    }

    const baseAmount = parseAmount(rawAmount);
    const isRetail = category.trim().toLowerCase() === "retail";
    const amount = roundToCents(isRetail ? baseAmount * (1 + RETAIL_TAX_RATE) : baseAmount);

    return {
      date: date.trim(),
      monthKey: getMonthKey(date),
      description: description.trim(),
      category: category.trim(),
      amount,
      flagged: amount > REVIEW_THRESHOLD,
    };
  });
}

export function buildReport(csv: string): TransactionReport {
  const transactions = parseTransactions(csv);
  const totals = new Map<string, MonthlyCategoryTotal>();

  for (const tx of transactions) {
    const key = `${tx.monthKey}|${tx.category}`;
    const existing = totals.get(key);
    if (existing) {
      existing.total = roundToCents(existing.total + tx.amount);
    } else {
      totals.set(key, { monthKey: tx.monthKey, category: tx.category, total: tx.amount });
    }
  }

  const monthlyTotals = Array.from(totals.values()).sort((a, b) =>
    a.monthKey === b.monthKey ? a.category.localeCompare(b.category) : a.monthKey.localeCompare(b.monthKey),
  );

  const flagged = transactions.filter((tx) => tx.flagged);

  return { monthlyTotals, flagged };
}

function formatCurrency(amount: number): string {
  return amount.toFixed(2);
}

function padColumns(rows: string[][]): string[] {
  const columnCount = rows.reduce((max, row) => Math.max(max, row.length), 0);
  const widths = Array.from({ length: columnCount }, (_, col) =>
    rows.reduce((max, row) => Math.max(max, (row[col] ?? "").length), 0),
  );

  return rows.map((row) => row.map((cell, col) => cell.padEnd(widths[col])).join("  ").trimEnd());
}

export function formatReport(report: TransactionReport): string {
  const lines: string[] = [];

  lines.push("MONTHLY TOTALS BY CATEGORY");
  lines.push("===========================");
  if (report.monthlyTotals.length === 0) {
    lines.push("(no transactions)");
  } else {
    const header = ["Month", "Category", "Total"];
    const dataRows = report.monthlyTotals.map((entry) => [
      entry.monthKey,
      entry.category,
      formatCurrency(entry.total),
    ]);
    lines.push(...padColumns([header, ...dataRows]));
  }

  lines.push("");
  lines.push("FLAGGED FOR REVIEW (single transaction over $10,000)");
  lines.push("======================================================");
  if (report.flagged.length === 0) {
    lines.push("(none)");
  } else {
    const header = ["Date", "Description", "Category", "Amount"];
    const dataRows = report.flagged.map((tx) => [tx.date, tx.description, tx.category, formatCurrency(tx.amount)]);
    lines.push(...padColumns([header, ...dataRows]));
  }

  return lines.join("\n");
}

export function generateReport(csv: string): string {
  return formatReport(buildReport(csv));
}

interface Entry<V> {
  value: V;
  expiresAt: number | null;
}

export interface LRUCacheOptions {
  maxSize: number;
  ttlMs?: number;
}

export class LRUCache<K, V> {
  private readonly maxSize: number;
  private readonly defaultTtlMs: number | undefined;
  private readonly map = new Map<K, Entry<V>>();

  constructor(options: LRUCacheOptions) {
    if (options.maxSize <= 0) {
      throw new Error("maxSize must be greater than 0");
    }
    this.maxSize = options.maxSize;
    this.defaultTtlMs = options.ttlMs;
  }

  get size(): number {
    return this.map.size;
  }

  get(key: K): V | undefined {
    const entry = this.map.get(key);
    if (!entry) return undefined;

    if (entry.expiresAt !== null && entry.expiresAt <= Date.now()) {
      this.map.delete(key);
      return undefined;
    }

    // refresh recency
    this.map.delete(key);
    this.map.set(key, entry);
    return entry.value;
  }

  has(key: K): boolean {
    return this.get(key) !== undefined;
  }

  set(key: K, value: V, ttlMs?: number): void {
    const effectiveTtl = ttlMs ?? this.defaultTtlMs;
    const expiresAt = effectiveTtl !== undefined ? Date.now() + effectiveTtl : null;

    if (this.map.has(key)) {
      this.map.delete(key);
    } else if (this.map.size >= this.maxSize) {
      const oldestKey = this.map.keys().next().value as K;
      this.map.delete(oldestKey);
    }

    this.map.set(key, { value, expiresAt });
  }

  delete(key: K): boolean {
    return this.map.delete(key);
  }

  clear(): void {
    this.map.clear();
  }
}

import { LRUCache } from "./cache.js";

const DEFAULT_MAX_SIZE = 500;
const DEFAULT_TTL_MS = 5 * 60 * 1000;

export interface UserServiceOptions {
  maxSize?: number;
  ttlMs?: number;
}

export class UserService<User> {
  private readonly cache: LRUCache<string, User>;
  private readonly inFlight = new Map<string, Promise<User>>();

  constructor(
    private readonly fetchUser: (id: string) => Promise<User>,
    options: UserServiceOptions = {},
  ) {
    this.cache = new LRUCache<string, User>({
      maxSize: options.maxSize ?? DEFAULT_MAX_SIZE,
      ttlMs: options.ttlMs ?? DEFAULT_TTL_MS,
    });
  }

  async getUser(id: string): Promise<User> {
    const cached = this.cache.get(id);
    if (cached !== undefined) {
      return cached;
    }

    const pending = this.inFlight.get(id);
    if (pending) {
      return pending;
    }

    const promise = this.fetchUser(id)
      .then((user) => {
        this.cache.set(id, user);
        return user;
      })
      .finally(() => {
        this.inFlight.delete(id);
      });

    this.inFlight.set(id, promise);
    return promise;
  }

  invalidate(id: string): void {
    this.cache.delete(id);
  }

  prefetch(ids: string[]): void {
    for (const id of ids) {
      // Fire-and-forget: a failed prefetch just means the cache stays cold,
      // and the real error will surface when a caller awaits getUser(id).
      this.getUser(id).catch((error: unknown) => {
        console.error(`prefetch failed for user ${id}`, error);
      });
    }
  }
}

interface Entry<V> {
  value: V;
  expiresAt: number;
}

export interface LruCacheOptions {
  maxSize: number;
  ttlMs: number;
}

export class LruCache<K, V> {
  private readonly maxSize: number;
  private readonly ttlMs: number;
  private readonly entries = new Map<K, Entry<V>>();

  constructor(options: LruCacheOptions) {
    if (options.maxSize <= 0) {
      throw new RangeError("maxSize must be greater than 0");
    }
    this.maxSize = options.maxSize;
    this.ttlMs = options.ttlMs;
  }

  get size(): number {
    return this.entries.size;
  }

  get(key: K): V | undefined {
    const entry = this.entries.get(key);
    if (!entry) {
      return undefined;
    }
    if (Date.now() >= entry.expiresAt) {
      this.entries.delete(key);
      return undefined;
    }
    // Refresh recency by re-inserting at the end of iteration order.
    this.entries.delete(key);
    this.entries.set(key, entry);
    return entry.value;
  }

  has(key: K): boolean {
    return this.get(key) !== undefined;
  }

  set(key: K, value: V): void {
    this.entries.delete(key);
    this.entries.set(key, { value, expiresAt: Date.now() + this.ttlMs });
    if (this.entries.size > this.maxSize) {
      const oldestKey = this.entries.keys().next().value as K;
      this.entries.delete(oldestKey);
    }
  }

  delete(key: K): boolean {
    return this.entries.delete(key);
  }

  clear(): void {
    this.entries.clear();
  }
}

import { LruCache, LruCacheOptions } from "./cache.js";

export type FetchUser<Id, User> = (id: Id) => Promise<User>;

export class UserService<Id, User> {
  private readonly fetchUser: FetchUser<Id, User>;
  private readonly cache: LruCache<Id, User>;
  private readonly pending = new Map<Id, Promise<User>>();
  private readonly generations = new Map<Id, number>();
  private readonly onPrefetchError: (id: Id, error: unknown) => void;

  constructor(
    fetchUser: FetchUser<Id, User>,
    cacheOptions: LruCacheOptions,
    onPrefetchError: (id: Id, error: unknown) => void = () => {},
  ) {
    this.fetchUser = fetchUser;
    this.cache = new LruCache<Id, User>(cacheOptions);
    this.onPrefetchError = onPrefetchError;
  }

  getUser(id: Id): Promise<User> {
    const cached = this.cache.get(id);
    if (cached !== undefined) {
      return Promise.resolve(cached);
    }

    const pending = this.pending.get(id);
    if (pending) {
      return pending;
    }

    const generation = this.generations.get(id) ?? 0;
    const promise = this.fetchUser(id).then(
      (user) => {
        this.pending.delete(id);
        if ((this.generations.get(id) ?? 0) === generation) {
          this.cache.set(id, user);
        }
        return user;
      },
      (error: unknown) => {
        this.pending.delete(id);
        throw error;
      },
    );

    this.pending.set(id, promise);
    return promise;
  }

  invalidate(id: Id): void {
    this.cache.delete(id);
    this.pending.delete(id);
    this.generations.set(id, (this.generations.get(id) ?? 0) + 1);
  }

  prefetch(ids: Iterable<Id>): void {
    for (const id of ids) {
      void this.getUser(id).catch((error: unknown) => {
        this.onPrefetchError(id, error);
      });
    }
  }
}

export interface WsMessage {
  type: string;
  [key: string]: unknown;
}

export type MessageHandler<T extends WsMessage = WsMessage> = (message: T) => void;

export interface WsClientOptions {
  url: string;
  protocols?: string | string[];
  /** Interval between heartbeat messages, in ms. */
  heartbeatIntervalMs?: number;
  /** Message sent as a heartbeat while the connection is open. */
  heartbeatMessage?: WsMessage;
  minReconnectDelayMs?: number;
  maxReconnectDelayMs?: number;
  reconnectBackoffFactor?: number;
}

const DEFAULT_HEARTBEAT_INTERVAL_MS = 30_000;
const DEFAULT_MIN_RECONNECT_DELAY_MS = 1_000;
const DEFAULT_MAX_RECONNECT_DELAY_MS = 30_000;
const DEFAULT_RECONNECT_BACKOFF_FACTOR = 2;

function isWsMessage(value: unknown): value is WsMessage {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as { type?: unknown }).type === "string"
  );
}

export class WsClient {
  private readonly url: string;
  private readonly protocols?: string | string[];
  private readonly heartbeatIntervalMs: number;
  private readonly heartbeatMessage: WsMessage;
  private readonly minReconnectDelayMs: number;
  private readonly maxReconnectDelayMs: number;
  private readonly reconnectBackoffFactor: number;

  private ws: WebSocket | null = null;
  private readonly handlers = new Map<string, Set<MessageHandler>>();
  private outgoingQueue: WsMessage[] = [];
  private heartbeatTimer: ReturnType<typeof setInterval> | null = null;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private reconnectAttempts = 0;
  private closedByUser = false;

  constructor(options: WsClientOptions) {
    this.url = options.url;
    this.protocols = options.protocols;
    this.heartbeatIntervalMs = options.heartbeatIntervalMs ?? DEFAULT_HEARTBEAT_INTERVAL_MS;
    this.heartbeatMessage = options.heartbeatMessage ?? { type: "ping" };
    this.minReconnectDelayMs = options.minReconnectDelayMs ?? DEFAULT_MIN_RECONNECT_DELAY_MS;
    this.maxReconnectDelayMs = options.maxReconnectDelayMs ?? DEFAULT_MAX_RECONNECT_DELAY_MS;
    this.reconnectBackoffFactor =
      options.reconnectBackoffFactor ?? DEFAULT_RECONNECT_BACKOFF_FACTOR;
  }

  connect(): void {
    this.closedByUser = false;
    this.openSocket();
  }

  close(): void {
    this.closedByUser = true;
    this.clearReconnectTimer();
    this.stopHeartbeat();
    this.ws?.close();
    this.ws = null;
  }

  /** Registers a handler for messages whose `type` field matches. Returns an unsubscribe function. */
  on<T extends WsMessage = WsMessage>(type: string, handler: MessageHandler<T>): () => void {
    let set = this.handlers.get(type);
    if (!set) {
      set = new Set();
      this.handlers.set(type, set);
    }
    set.add(handler as MessageHandler);
    return () => this.off(type, handler as MessageHandler);
  }

  off(type: string, handler: MessageHandler): void {
    this.handlers.get(type)?.delete(handler);
  }

  /** Sends a message, queueing it if the socket isn't currently open. */
  send(message: WsMessage): void {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(message));
    } else {
      this.outgoingQueue.push(message);
    }
  }

  private openSocket(): void {
    const ws = new WebSocket(this.url, this.protocols);
    this.ws = ws;

    ws.addEventListener("open", () => {
      this.reconnectAttempts = 0;
      this.flushQueue();
      this.startHeartbeat();
    });

    ws.addEventListener("message", (event: MessageEvent) => {
      this.handleMessage(event.data);
    });

    ws.addEventListener("close", () => {
      this.stopHeartbeat();
      if (this.ws === ws) {
        this.ws = null;
      }
      if (!this.closedByUser) {
        this.scheduleReconnect();
      }
    });

    ws.addEventListener("error", () => {
      ws.close();
    });
  }

  private handleMessage(data: unknown): void {
    if (typeof data !== "string") {
      return;
    }
    let parsed: unknown;
    try {
      parsed = JSON.parse(data);
    } catch {
      return;
    }
    if (!isWsMessage(parsed)) {
      return;
    }
    const set = this.handlers.get(parsed.type);
    if (!set) {
      return;
    }
    for (const handler of set) {
      handler(parsed);
    }
  }

  private flushQueue(): void {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) {
      return;
    }
    const queue = this.outgoingQueue;
    this.outgoingQueue = [];
    for (const message of queue) {
      this.ws.send(JSON.stringify(message));
    }
  }

  private startHeartbeat(): void {
    this.stopHeartbeat();
    this.heartbeatTimer = setInterval(() => {
      this.send(this.heartbeatMessage);
    }, this.heartbeatIntervalMs);
  }

  private stopHeartbeat(): void {
    if (this.heartbeatTimer !== null) {
      clearInterval(this.heartbeatTimer);
      this.heartbeatTimer = null;
    }
  }

  private scheduleReconnect(): void {
    this.clearReconnectTimer();
    const delay = Math.min(
      this.minReconnectDelayMs * this.reconnectBackoffFactor ** this.reconnectAttempts,
      this.maxReconnectDelayMs,
    );
    this.reconnectAttempts += 1;
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null;
      this.openSocket();
    }, delay);
  }

  private clearReconnectTimer(): void {
    if (this.reconnectTimer !== null) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
  }
}

export interface WsMessage {
  type: string;
  [key: string]: unknown;
}

export type MessageHandler<M extends WsMessage = WsMessage> = (message: M) => void;

export interface WsClientOptions {
  /** Interval in ms between heartbeat pings. Default 30000. */
  heartbeatIntervalMs?: number;
  /** Base delay in ms for reconnect backoff. Default 1000. */
  reconnectBaseDelayMs?: number;
  /** Maximum delay in ms for reconnect backoff. Default 30000. */
  reconnectMaxDelayMs?: number;
  /** Payload sent as a heartbeat. Default { type: "ping" }. */
  heartbeatPayload?: WsMessage;
  /** WebSocket subprotocols to negotiate. */
  protocols?: string | string[];
}

const DEFAULT_HEARTBEAT_INTERVAL_MS = 30000;
const DEFAULT_RECONNECT_BASE_DELAY_MS = 1000;
const DEFAULT_RECONNECT_MAX_DELAY_MS = 30000;
const DEFAULT_HEARTBEAT_PAYLOAD: WsMessage = { type: "ping" };

export class WsClient {
  private readonly url: string;
  private readonly heartbeatIntervalMs: number;
  private readonly reconnectBaseDelayMs: number;
  private readonly reconnectMaxDelayMs: number;
  private readonly heartbeatPayload: WsMessage;
  private readonly protocols: string | string[] | undefined;

  private ws: WebSocket | null = null;
  private handlers = new Map<string, Set<MessageHandler>>();
  private outgoingQueue: string[] = [];
  private heartbeatTimer: ReturnType<typeof setInterval> | null = null;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private reconnectAttempts = 0;
  private closedByUser = false;

  constructor(url: string, options: WsClientOptions = {}) {
    this.url = url;
    this.heartbeatIntervalMs = options.heartbeatIntervalMs ?? DEFAULT_HEARTBEAT_INTERVAL_MS;
    this.reconnectBaseDelayMs = options.reconnectBaseDelayMs ?? DEFAULT_RECONNECT_BASE_DELAY_MS;
    this.reconnectMaxDelayMs = options.reconnectMaxDelayMs ?? DEFAULT_RECONNECT_MAX_DELAY_MS;
    this.heartbeatPayload = options.heartbeatPayload ?? DEFAULT_HEARTBEAT_PAYLOAD;
    this.protocols = options.protocols;
  }

  connect(): void {
    this.closedByUser = false;
    this.openSocket();
  }

  close(): void {
    this.closedByUser = true;
    this.clearReconnectTimer();
    this.clearHeartbeatTimer();
    this.ws?.close();
    this.ws = null;
  }

  on<M extends WsMessage = WsMessage>(type: string, handler: MessageHandler<M>): () => void {
    let set = this.handlers.get(type);
    if (!set) {
      set = new Set();
      this.handlers.set(type, set);
    }
    set.add(handler as MessageHandler);
    return () => this.off(type, handler);
  }

  off<M extends WsMessage = WsMessage>(type: string, handler: MessageHandler<M>): void {
    this.handlers.get(type)?.delete(handler as MessageHandler);
  }

  send(message: WsMessage): void {
    const payload = JSON.stringify(message);
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(payload);
    } else {
      this.outgoingQueue.push(payload);
    }
  }

  private openSocket(): void {
    const ws = new WebSocket(this.url, this.protocols);
    this.ws = ws;

    ws.addEventListener("open", () => {
      this.reconnectAttempts = 0;
      this.flushQueue();
      this.startHeartbeat();
    });

    ws.addEventListener("message", (event: MessageEvent) => {
      this.handleMessage(event.data);
    });

    ws.addEventListener("close", () => {
      this.clearHeartbeatTimer();
      if (!this.closedByUser) {
        this.scheduleReconnect();
      }
    });

    ws.addEventListener("error", () => {
      ws.close();
    });
  }

  private handleMessage(data: unknown): void {
    if (typeof data !== "string") {
      return;
    }
    let parsed: unknown;
    try {
      parsed = JSON.parse(data);
    } catch {
      return;
    }
    if (
      typeof parsed !== "object" ||
      parsed === null ||
      typeof (parsed as Record<string, unknown>).type !== "string"
    ) {
      return;
    }
    const message = parsed as WsMessage;
    const set = this.handlers.get(message.type);
    if (set) {
      for (const handler of set) {
        handler(message);
      }
    }
  }

  private flushQueue(): void {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) {
      return;
    }
    const queue = this.outgoingQueue;
    this.outgoingQueue = [];
    for (const payload of queue) {
      this.ws.send(payload);
    }
  }

  private startHeartbeat(): void {
    this.clearHeartbeatTimer();
    this.heartbeatTimer = setInterval(() => {
      this.send(this.heartbeatPayload);
    }, this.heartbeatIntervalMs);
  }

  private clearHeartbeatTimer(): void {
    if (this.heartbeatTimer !== null) {
      clearInterval(this.heartbeatTimer);
      this.heartbeatTimer = null;
    }
  }

  private scheduleReconnect(): void {
    this.clearReconnectTimer();
    const delay = Math.min(
      this.reconnectBaseDelayMs * 2 ** this.reconnectAttempts,
      this.reconnectMaxDelayMs,
    );
    this.reconnectAttempts += 1;
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null;
      this.openSocket();
    }, delay);
  }

  private clearReconnectTimer(): void {
    if (this.reconnectTimer !== null) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
  }
}

import Foundation

/// Current weather conditions for a city, in metric units.
public struct CurrentWeather: Codable, Equatable {
    public let temperatureCelsius: Double
    public let condition: String
    public let windSpeedKph: Double
}

public enum WeatherClientError: Error, LocalizedError {
    case missingAPIKey
    case invalidCity
    case invalidResponse
    case httpError(statusCode: Int)
    case decodingFailed(underlying: Error)
    case network(underlying: Error)

    public var errorDescription: String? {
        switch self {
        case .missingAPIKey:
            return "The WEATHER_API_KEY environment variable is not set."
        case .invalidCity:
            return "The city name is empty or could not be encoded into a request."
        case .invalidResponse:
            return "The server returned a response that was not a valid HTTP response."
        case .httpError(let statusCode):
            return "The weather service returned HTTP status \(statusCode)."
        case .decodingFailed(let underlying):
            return "Failed to decode the weather response: \(underlying.localizedDescription)"
        case .network(let underlying):
            return "Network request failed: \(underlying.localizedDescription)"
        }
    }
}

/// Fetches current weather conditions from a JSON HTTP weather API.
///
/// Expects an endpoint compatible with weatherapi.com's `/v1/current.json`
/// response shape (`current.temp_c`, `current.condition.text`, `current.wind_kph`).
public struct WeatherClient {
    private let baseURL: URL
    private let apiKey: String
    private let session: URLSession

    private struct APIResponse: Decodable {
        struct Current: Decodable {
            struct Condition: Decodable {
                let text: String
            }
            let temp_c: Double
            let wind_kph: Double
            let condition: Condition
        }
        let current: Current
    }

    public init(
        baseURL: URL = URL(string: "https://api.weatherapi.com/v1/current.json")!,
        session: URLSession = .shared
    ) throws {
        guard let apiKey = ProcessInfo.processInfo.environment["WEATHER_API_KEY"], !apiKey.isEmpty else {
            throw WeatherClientError.missingAPIKey
        }
        self.baseURL = baseURL
        self.apiKey = apiKey
        self.session = session
    }

    public func currentWeather(forCity city: String) async throws -> CurrentWeather {
        guard !city.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            throw WeatherClientError.invalidCity
        }

        guard var components = URLComponents(url: baseURL, resolvingAgainstBaseURL: false) else {
            throw WeatherClientError.invalidCity
        }
        components.queryItems = [
            URLQueryItem(name: "key", value: apiKey),
            URLQueryItem(name: "q", value: city),
        ]
        guard let url = components.url else {
            throw WeatherClientError.invalidCity
        }

        let data: Data
        let response: URLResponse
        do {
            (data, response) = try await session.data(from: url)
        } catch {
            throw WeatherClientError.network(underlying: error)
        }

        guard let httpResponse = response as? HTTPURLResponse else {
            throw WeatherClientError.invalidResponse
        }
        guard (200...299).contains(httpResponse.statusCode) else {
            throw WeatherClientError.httpError(statusCode: httpResponse.statusCode)
        }

        do {
            let decoded = try JSONDecoder().decode(APIResponse.self, from: data)
            return CurrentWeather(
                temperatureCelsius: decoded.current.temp_c,
                condition: decoded.current.condition.text,
                windSpeedKph: decoded.current.wind_kph
            )
        } catch {
            throw WeatherClientError.decodingFailed(underlying: error)
        }
    }
}

export interface Transaction {
  date: string;
  description: string;
  category: string;
  amount: number;
}

export interface FlaggedTransaction extends Transaction {
  effectiveAmount: number;
}

export interface CategoryMonthTotal {
  month: string;
  category: string;
  total: number;
}

export interface Report {
  totals: CategoryMonthTotal[];
  flagged: FlaggedTransaction[];
}

const RETAIL_TAX_RATE = 0.0825;
const REVIEW_THRESHOLD = 10000;

function parseCsvLine(line: string): string[] {
  const fields: string[] = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    if (inQuotes) {
      if (char === '"') {
        if (line[i + 1] === '"') {
          current += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        current += char;
      }
    } else if (char === '"') {
      inQuotes = true;
    } else if (char === ',') {
      fields.push(current);
      current = '';
    } else {
      current += char;
    }
  }
  fields.push(current);
  return fields;
}

export function parseTransactions(csv: string): Transaction[] {
  const lines = csv.split(/\r\n|\n|\r/).filter((line) => line.trim().length > 0);
  const transactions: Transaction[] = [];

  for (const line of lines) {
    const fields = parseCsvLine(line);
    if (fields.length < 4) continue;

    const [date, description, category, amountRaw] = fields;
    const amount = Number(amountRaw);
    if (Number.isNaN(amount)) continue; // skips a header row, if present

    transactions.push({ date, description, category, amount });
  }

  return transactions;
}

function getMonthKey(dateStr: string): string {
  const isoMatch = dateStr.match(/^(\d{4})-(\d{2})/);
  if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}`;

  const parsed = new Date(dateStr);
  const year = parsed.getUTCFullYear();
  const month = String(parsed.getUTCMonth() + 1).padStart(2, '0');
  return `${year}-${month}`;
}

function effectiveAmount(transaction: Transaction): number {
  const isRetail = transaction.category.trim().toLowerCase() === 'retail';
  return isRetail ? transaction.amount * (1 + RETAIL_TAX_RATE) : transaction.amount;
}

export function generateReport(csv: string): Report {
  const transactions = parseTransactions(csv);
  const totalsByMonth = new Map<string, Map<string, number>>();
  const flagged: FlaggedTransaction[] = [];

  for (const transaction of transactions) {
    const amount = effectiveAmount(transaction);
    const month = getMonthKey(transaction.date);

    const categoryTotals = totalsByMonth.get(month) ?? new Map<string, number>();
    categoryTotals.set(transaction.category, (categoryTotals.get(transaction.category) ?? 0) + amount);
    totalsByMonth.set(month, categoryTotals);

    if (amount > REVIEW_THRESHOLD) {
      flagged.push({ ...transaction, effectiveAmount: amount });
    }
  }

  const totals: CategoryMonthTotal[] = [];
  for (const [month, categoryTotals] of totalsByMonth) {
    for (const [category, total] of categoryTotals) {
      totals.push({ month, category, total });
    }
  }
  totals.sort((a, b) => (a.month === b.month ? a.category.localeCompare(b.category) : a.month.localeCompare(b.month)));
  flagged.sort((a, b) => b.effectiveAmount - a.effectiveAmount);

  return { totals, flagged };
}

function formatCurrency(amount: number): string {
  return amount.toFixed(2);
}

function buildTable(headers: string[], rows: string[][]): string[] {
  const widths = headers.map((header, i) => rows.reduce((max, row) => Math.max(max, row[i].length), header.length));
  const formatRow = (cols: string[]) => cols.map((col, i) => col.padEnd(widths[i])).join('  ');

  const lines = [formatRow(headers), widths.map((w) => '-'.repeat(w)).join('  ')];
  for (const row of rows) lines.push(formatRow(row));
  return lines;
}

export function formatReport(report: Report): string {
  const lines: string[] = [];

  const totalsRows = report.totals.map((t) => [t.month, t.category, formatCurrency(t.total)]);
  lines.push(...buildTable(['Month', 'Category', 'Total'], totalsRows));

  if (report.flagged.length > 0) {
    lines.push('');
    lines.push(`Flagged for review (over $${formatCurrency(REVIEW_THRESHOLD)}):`);
    const flaggedRows = report.flagged.map((f) => [f.date, f.description, f.category, formatCurrency(f.effectiveAmount)]);
    lines.push(...buildTable(['Date', 'Description', 'Category', 'Amount'], flaggedRows));
  }

  return lines.join('\n');
}

import Foundation

/// The current weather conditions for a city.
struct CurrentWeather: Decodable {
    let temperatureCelsius: Double
    let condition: String
    let windSpeed: Double
}

enum WeatherClientError: Error, LocalizedError {
    case missingAPIKey
    case invalidCityName
    case invalidURL
    case invalidResponse
    case httpError(statusCode: Int)
    case decodingFailed(underlying: Error)
    case requestFailed(underlying: Error)

    var errorDescription: String? {
        switch self {
        case .missingAPIKey:
            return "The WEATHER_API_KEY environment variable is not set."
        case .invalidCityName:
            return "The city name is empty or could not be encoded into a URL."
        case .invalidURL:
            return "Failed to construct a valid URL for the weather request."
        case .invalidResponse:
            return "The server returned a response that was not a valid HTTP response."
        case .httpError(let statusCode):
            return "The weather service returned HTTP status code \(statusCode)."
        case .decodingFailed(let underlying):
            return "Failed to decode the weather response: \(underlying.localizedDescription)"
        case .requestFailed(let underlying):
            return "The weather request failed: \(underlying.localizedDescription)"
        }
    }
}

/// Fetches current weather conditions from a JSON HTTP API (OpenWeatherMap-compatible).
struct WeatherClient {
    private let baseURL: URL
    private let apiKey: String
    private let session: URLSession

    private struct Response: Decodable {
        struct Main: Decodable {
            let temp: Double
        }
        struct Weather: Decodable {
            let main: String
        }
        struct Wind: Decodable {
            let speed: Double
        }
        let main: Main
        let weather: [Weather]
        let wind: Wind
    }

    static let defaultBaseURL = "https://api.openweathermap.org/data/2.5/weather"

    init(
        baseURL: URL? = nil,
        session: URLSession = .shared
    ) throws {
        guard let apiKey = ProcessInfo.processInfo.environment["WEATHER_API_KEY"], !apiKey.isEmpty else {
            throw WeatherClientError.missingAPIKey
        }
        guard let resolvedBaseURL = baseURL ?? URL(string: Self.defaultBaseURL) else {
            throw WeatherClientError.invalidURL
        }
        self.baseURL = resolvedBaseURL
        self.apiKey = apiKey
        self.session = session
    }

    func currentWeather(forCity city: String) async throws -> CurrentWeather {
        guard !city.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            throw WeatherClientError.invalidCityName
        }

        guard var components = URLComponents(url: baseURL, resolvingAgainstBaseURL: false) else {
            throw WeatherClientError.invalidURL
        }
        components.queryItems = [
            URLQueryItem(name: "q", value: city),
            URLQueryItem(name: "appid", value: apiKey),
            URLQueryItem(name: "units", value: "metric"),
        ]
        guard let url = components.url else {
            throw WeatherClientError.invalidURL
        }

        let data: Data
        let response: URLResponse
        do {
            (data, response) = try await session.data(from: url)
        } catch {
            throw WeatherClientError.requestFailed(underlying: error)
        }

        guard let httpResponse = response as? HTTPURLResponse else {
            throw WeatherClientError.invalidResponse
        }
        guard (200...299).contains(httpResponse.statusCode) else {
            throw WeatherClientError.httpError(statusCode: httpResponse.statusCode)
        }

        do {
            let decoded = try JSONDecoder().decode(Response.self, from: data)
            return CurrentWeather(
                temperatureCelsius: decoded.main.temp,
                condition: decoded.weather.first?.main ?? "Unknown",
                windSpeed: decoded.wind.speed
            )
        } catch {
            throw WeatherClientError.decodingFailed(underlying: error)
        }
    }
}

import Foundation

/// Current weather conditions for a city.
public struct CurrentWeather: Codable, Equatable {
    public let temperatureCelsius: Double
    public let condition: String
    public let windSpeedKph: Double
}

public enum WeatherClientError: Error, LocalizedError {
    case missingAPIKey
    case invalidCity(String)
    case invalidURL
    case invalidResponse
    case httpError(statusCode: Int)
    case decodingFailed(underlying: Error)
    case transportError(underlying: Error)

    public var errorDescription: String? {
        switch self {
        case .missingAPIKey:
            return "The WEATHER_API_KEY environment variable is not set."
        case .invalidCity(let city):
            return "\"\(city)\" is not a valid city name."
        case .invalidURL:
            return "Failed to construct a valid weather API URL."
        case .invalidResponse:
            return "The weather API returned an unexpected response."
        case .httpError(let statusCode):
            return "The weather API returned HTTP status \(statusCode)."
        case .decodingFailed(let underlying):
            return "Failed to decode the weather API response: \(underlying.localizedDescription)"
        case .transportError(let underlying):
            return "Failed to reach the weather API: \(underlying.localizedDescription)"
        }
    }
}

/// Fetches current weather conditions from a JSON HTTP weather API.
public struct WeatherClient {
    private let apiKey: String
    private let baseURL: URL
    private let session: URLSession

    public static let defaultBaseURL = URL(string: "https://api.weatherapi.com/v1") ?? URL(fileURLWithPath: "/")

    public init(
        apiKey: String? = ProcessInfo.processInfo.environment["WEATHER_API_KEY"],
        baseURL: URL = WeatherClient.defaultBaseURL,
        session: URLSession = .shared
    ) throws {
        guard let apiKey, !apiKey.isEmpty else {
            throw WeatherClientError.missingAPIKey
        }
        self.apiKey = apiKey
        self.baseURL = baseURL
        self.session = session
    }

    public func fetchCurrentWeather(city: String) async throws -> CurrentWeather {
        guard !city.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            throw WeatherClientError.invalidCity(city)
        }

        guard var components = URLComponents(url: baseURL.appendingPathComponent("current.json"), resolvingAgainstBaseURL: false) else {
            throw WeatherClientError.invalidURL
        }
        components.queryItems = [
            URLQueryItem(name: "key", value: apiKey),
            URLQueryItem(name: "q", value: city),
        ]
        guard let url = components.url else {
            throw WeatherClientError.invalidURL
        }

        let data: Data
        let response: URLResponse
        do {
            (data, response) = try await session.data(from: url)
        } catch {
            throw WeatherClientError.transportError(underlying: error)
        }

        guard let httpResponse = response as? HTTPURLResponse else {
            throw WeatherClientError.invalidResponse
        }
        guard (200...299).contains(httpResponse.statusCode) else {
            throw WeatherClientError.httpError(statusCode: httpResponse.statusCode)
        }

        do {
            let decoded = try JSONDecoder().decode(WeatherAPIResponse.self, from: data)
            return CurrentWeather(
                temperatureCelsius: decoded.current.tempC,
                condition: decoded.current.condition.text,
                windSpeedKph: decoded.current.windKph
            )
        } catch {
            throw WeatherClientError.decodingFailed(underlying: error)
        }
    }
}

private struct WeatherAPIResponse: Decodable {
    let current: Current

    struct Current: Decodable {
        let tempC: Double
        let windKph: Double
        let condition: Condition

        enum CodingKeys: String, CodingKey {
            case tempC = "temp_c"
            case windKph = "wind_kph"
            case condition
        }

        struct Condition: Decodable {
            let text: String
        }
    }
}

export interface WsMessageBase {
  type: string;
}

export type WsHandlers<TMessage extends WsMessageBase> = {
  [K in TMessage["type"]]?: (message: Extract<TMessage, { type: K }>) => void;
};

export interface WsClientOptions<TMessage extends WsMessageBase> {
  url: string;
  protocols?: string | string[];
  handlers: WsHandlers<TMessage>;
  /** Interval between heartbeat pings while connected. Defaults to 30s. */
  heartbeatIntervalMs?: number;
  /** Message sent as a heartbeat. Defaults to `{ type: "ping" }`. */
  heartbeatMessage?: unknown;
  /** Initial delay before the first reconnect attempt. Defaults to 500ms. */
  minReconnectDelayMs?: number;
  /** Upper bound for the exponential backoff delay. Defaults to 30s. */
  maxReconnectDelayMs?: number;
  onOpen?: () => void;
  onClose?: (event: CloseEvent) => void;
  onError?: (event: Event) => void;
  /** Called whenever a message is received that fails to parse or has no known handler. */
  onUnhandledMessage?: (data: unknown) => void;
}

/**
 * WebSocket wrapper that auto-reconnects with exponential backoff after
 * unexpected closes, sends periodic heartbeats, queues outgoing messages
 * while disconnected, and dispatches parsed JSON messages to handlers
 * keyed by the message's `type` field.
 */
export class WsClient<TMessage extends WsMessageBase> {
  private readonly url: string;
  private readonly protocols?: string | string[];
  private readonly handlers: WsHandlers<TMessage>;
  private readonly heartbeatIntervalMs: number;
  private readonly heartbeatMessage: unknown;
  private readonly minReconnectDelayMs: number;
  private readonly maxReconnectDelayMs: number;
  private readonly onOpen?: () => void;
  private readonly onClose?: (event: CloseEvent) => void;
  private readonly onError?: (event: Event) => void;
  private readonly onUnhandledMessage?: (data: unknown) => void;

  private ws: WebSocket | null = null;
  private outgoingQueue: string[] = [];
  private reconnectAttempts = 0;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private heartbeatTimer: ReturnType<typeof setInterval> | null = null;
  private destroyed = false;
  private manualClose = false;

  constructor(options: WsClientOptions<TMessage>) {
    this.url = options.url;
    this.protocols = options.protocols;
    this.handlers = options.handlers;
    this.heartbeatIntervalMs = options.heartbeatIntervalMs ?? 30_000;
    this.heartbeatMessage = options.heartbeatMessage ?? { type: "ping" };
    this.minReconnectDelayMs = options.minReconnectDelayMs ?? 500;
    this.maxReconnectDelayMs = options.maxReconnectDelayMs ?? 30_000;
    this.onOpen = options.onOpen;
    this.onClose = options.onClose;
    this.onError = options.onError;
    this.onUnhandledMessage = options.onUnhandledMessage;
  }

  connect(): void {
    if (this.destroyed || this.ws) {
      return;
    }
    this.manualClose = false;
    this.openSocket();
  }

  /** Sends a message immediately if connected, otherwise queues it for delivery once reconnected. */
  send(message: unknown): void {
    const payload = JSON.stringify(message);
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(payload);
    } else {
      this.outgoingQueue.push(payload);
    }
  }

  /** Closes the connection and stops reconnecting until `connect()` is called again. */
  close(code?: number, reason?: string): void {
    this.manualClose = true;
    this.clearReconnectTimer();
    this.stopHeartbeat();
    this.ws?.close(code, reason);
  }

  /** Permanently tears down the client; it cannot be reused after this. */
  destroy(): void {
    this.destroyed = true;
    this.close();
    this.outgoingQueue = [];
  }

  private openSocket(): void {
    const ws = new WebSocket(this.url, this.protocols);
    this.ws = ws;

    ws.onopen = () => {
      this.reconnectAttempts = 0;
      this.flushQueue();
      this.startHeartbeat();
      this.onOpen?.();
    };

    ws.onmessage = (event: MessageEvent) => {
      this.handleMessage(event.data);
    };

    ws.onerror = (event: Event) => {
      this.onError?.(event);
    };

    ws.onclose = (event: CloseEvent) => {
      this.ws = null;
      this.stopHeartbeat();
      this.onClose?.(event);
      if (!this.manualClose && !this.destroyed) {
        this.scheduleReconnect();
      }
    };
  }

  private handleMessage(data: unknown): void {
    if (typeof data !== "string") {
      this.onUnhandledMessage?.(data);
      return;
    }

    let parsed: unknown;
    try {
      parsed = JSON.parse(data);
    } catch {
      this.onUnhandledMessage?.(data);
      return;
    }

    if (
      typeof parsed !== "object" ||
      parsed === null ||
      typeof (parsed as { type?: unknown }).type !== "string"
    ) {
      this.onUnhandledMessage?.(parsed);
      return;
    }

    const message = parsed as TMessage;
    const handler = this.handlers[message.type as TMessage["type"]] as
      | ((message: TMessage) => void)
      | undefined;

    if (handler) {
      handler(message);
    } else {
      this.onUnhandledMessage?.(message);
    }
  }

  private flushQueue(): void {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) {
      return;
    }
    const pending = this.outgoingQueue;
    this.outgoingQueue = [];
    for (const payload of pending) {
      this.ws.send(payload);
    }
  }

  private scheduleReconnect(): void {
    this.clearReconnectTimer();
    const delay = Math.min(
      this.maxReconnectDelayMs,
      this.minReconnectDelayMs * 2 ** this.reconnectAttempts,
    );
    this.reconnectAttempts += 1;
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null;
      if (!this.destroyed && !this.manualClose) {
        this.openSocket();
      }
    }, delay);
  }

  private clearReconnectTimer(): void {
    if (this.reconnectTimer !== null) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
  }

  private startHeartbeat(): void {
    this.stopHeartbeat();
    this.heartbeatTimer = setInterval(() => {
      this.send(this.heartbeatMessage);
    }, this.heartbeatIntervalMs);
  }

  private stopHeartbeat(): void {
    if (this.heartbeatTimer !== null) {
      clearInterval(this.heartbeatTimer);
      this.heartbeatTimer = null;
    }
  }
}

import Foundation

struct User: Identifiable, Decodable, Hashable {
    let id: Int
    let name: String
    let email: String
}

final class UserListViewModel: ObservableObject {
    @Published var users: [User] = []
    @Published var isLoading = false
    @Published var errorMessage: String?
    @Published var searchText = ""

    var filteredUsers: [User] {
        guard !searchText.isEmpty else { return users }
        return users.filter {
            $0.name.localizedCaseInsensitiveContains(searchText) ||
            $0.email.localizedCaseInsensitiveContains(searchText)
        }
    }

    private let endpoint: URL
    private let session: URLSession
    private var task: URLSessionDataTask?

    init(endpoint: URL = URL(string: "https://jsonplaceholder.typicode.com/users")!,
         session: URLSession = .shared) {
        self.endpoint = endpoint
        self.session = session
    }

    func load() {
        fetch { }
    }

    @MainActor
    func refresh() async {
        await withCheckedContinuation { continuation in
            fetch { continuation.resume() }
        }
    }

    private func fetch(completion: @escaping () -> Void) {
        task?.cancel()
        isLoading = true
        errorMessage = nil

        let request = session.dataTask(with: endpoint) { [weak self] data, _, error in
            DispatchQueue.main.async {
                defer { completion() }
                guard let self else { return }
                self.isLoading = false

                if let error {
                    if (error as NSError).code == NSURLErrorCancelled { return }
                    self.errorMessage = error.localizedDescription
                    return
                }
                guard let data else {
                    self.errorMessage = "No data received."
                    return
                }
                do {
                    self.users = try JSONDecoder().decode([User].self, from: data)
                } catch {
                    self.errorMessage = "Failed to parse users: \(error.localizedDescription)"
                }
            }
        }
        task = request
        request.resume()
    }
}

