import Foundation

/// A generic disk cache that stores `Codable` values as JSON files under the
/// system caches directory, with per-entry expiration and a total size cap
/// enforced by evicting the oldest entries first.
final class DiskCache<Value: Codable> {
    private let directory: URL
    private let maxTotalSize: Int
    private let fileManager: FileManager
    private let queue: DispatchQueue
    private let encoder = JSONEncoder()
    private let decoder = JSONDecoder()

    /// - Parameters:
    ///   - name: A unique name for this cache, used as its subdirectory under the caches directory.
    ///   - maxTotalSize: The maximum total size in bytes the cache may occupy on disk. When exceeded,
    ///     the oldest entries (by modification date) are evicted until the cache fits within the limit.
    ///   - fileManager: The file manager used for all disk operations.
    init(
        name: String,
        maxTotalSize: Int,
        fileManager: FileManager = .default
    ) {
        self.maxTotalSize = maxTotalSize
        self.fileManager = fileManager
        self.queue = DispatchQueue(label: "com.app.diskcache.\(name)")

        let cachesDirectory = fileManager.urls(for: .cachesDirectory, in: .userDomainMask)[0]
        self.directory = cachesDirectory.appendingPathComponent(name, isDirectory: true)

        try? fileManager.createDirectory(at: directory, withIntermediateDirectories: true)
    }

    /// Stores `value` for `key`, expiring after `ttl` seconds (if provided), then enforces the size cap.
    func set(_ value: Value, forKey key: String, ttl: TimeInterval? = nil) throws {
        try queue.sync {
            let entry = Entry(value: value, expiresAt: ttl.map { Date().addingTimeInterval($0) })
            let data = try encoder.encode(entry)
            try data.write(to: fileURL(forKey: key), options: .atomic)
            try enforceSizeLimit()
        }
    }

    /// Returns the cached value for `key`, or `nil` if missing, expired, or unreadable.
    /// Expired entries are removed from disk as a side effect.
    func value(forKey key: String) -> Value? {
        queue.sync {
            let url = fileURL(forKey: key)
            guard let data = try? Data(contentsOf: url),
                  let entry = try? decoder.decode(Entry.self, from: data) else {
                return nil
            }
            if let expiresAt = entry.expiresAt, expiresAt <= Date() {
                try? fileManager.removeItem(at: url)
                return nil
            }
            return entry.value
        }
    }

    /// Removes the cached value for `key`, if any.
    func removeValue(forKey key: String) {
        queue.sync {
            try? fileManager.removeItem(at: fileURL(forKey: key))
        }
    }

    /// Removes all cached values.
    func removeAll() {
        queue.sync {
            let urls = (try? fileManager.contentsOfDirectory(at: directory, includingPropertiesForKeys: nil)) ?? []
            for url in urls {
                try? fileManager.removeItem(at: url)
            }
        }
    }

    private struct Entry: Codable {
        let value: Value
        let expiresAt: Date?
    }

    private func fileURL(forKey key: String) -> URL {
        let fileName = key.addingPercentEncoding(withAllowedCharacters: .alphanumerics) ?? key
        return directory.appendingPathComponent(fileName).appendingPathExtension("json")
    }

    /// Removes expired entries, then evicts oldest-first (by modification date) until the
    /// total size on disk is within `maxTotalSize`. Must be called while already on `queue`.
    private func enforceSizeLimit() throws {
        let keys: Set<URLResourceKey> = [.contentModificationDateKey, .fileSizeKey]
        guard let urls = try? fileManager.contentsOfDirectory(
            at: directory,
            includingPropertiesForKeys: Array(keys)
        ) else {
            return
        }

        var entries: [(url: URL, date: Date, size: Int)] = []
        for url in urls {
            let values = try? url.resourceValues(forKeys: keys)
            let date = values?.contentModificationDate ?? .distantPast
            let size = values?.fileSize ?? 0

            if let data = try? Data(contentsOf: url),
               let entry = try? decoder.decode(Entry.self, from: data),
               let expiresAt = entry.expiresAt,
               expiresAt <= Date() {
                try? fileManager.removeItem(at: url)
                continue
            }

            entries.append((url, date, size))
        }

        var totalSize = entries.reduce(0) { $0 + $1.size }
        guard totalSize > maxTotalSize else { return }

        let oldestFirst = entries.sorted { $0.date < $1.date }
        for entry in oldestFirst {
            guard totalSize > maxTotalSize else { break }
            try? fileManager.removeItem(at: entry.url)
            totalSize -= entry.size
        }
    }
}

import Foundation
import Combine

struct User: Identifiable, Codable, Hashable {
    let id: Int
    let name: String
    let email: String
}

private let defaultUsersEndpoint = URL(string: "https://jsonplaceholder.typicode.com/users")
    ?? URL(fileURLWithPath: "/dev/null")

@MainActor
final class UserListViewModel: ObservableObject {
    @Published private(set) var users: [User] = []
    @Published private(set) var isLoading = false
    @Published var errorMessage: String?
    @Published var searchText: String = ""

    var filteredUsers: [User] {
        guard !searchText.isEmpty else { return users }
        return users.filter {
            $0.name.localizedCaseInsensitiveContains(searchText) ||
            $0.email.localizedCaseInsensitiveContains(searchText)
        }
    }

    private let endpoint: URL
    private let session: URLSession
    private var currentTask: URLSessionDataTask?

    init(endpoint: URL = defaultUsersEndpoint,
         session: URLSession = .shared) {
        self.endpoint = endpoint
        self.session = session
    }

    func load() {
        currentTask?.cancel()
        isLoading = true
        errorMessage = nil

        let task = session.dataTask(with: endpoint) { [weak self] data, response, error in
            guard let self else { return }
            Task { @MainActor in
                self.isLoading = false

                if let error {
                    if (error as NSError).code != NSURLErrorCancelled {
                        self.errorMessage = error.localizedDescription
                    }
                    return
                }

                guard let data else {
                    self.errorMessage = "No data received."
                    return
                }

                do {
                    let decoded = try JSONDecoder().decode([User].self, from: data)
                    self.users = decoded
                } catch {
                    self.errorMessage = "Failed to parse users: \(error.localizedDescription)"
                }
            }
        }
        currentTask = task
        task.resume()
    }

    func refresh() async {
        await withCheckedContinuation { continuation in
            let previousTask = currentTask
            previousTask?.cancel()
            isLoading = true
            errorMessage = nil

            let task = session.dataTask(with: endpoint) { [weak self] data, response, error in
                guard let self else {
                    continuation.resume()
                    return
                }
                Task { @MainActor in
                    self.isLoading = false

                    if let error {
                        if (error as NSError).code != NSURLErrorCancelled {
                            self.errorMessage = error.localizedDescription
                        }
                        continuation.resume()
                        return
                    }

                    guard let data else {
                        self.errorMessage = "No data received."
                        continuation.resume()
                        return
                    }

                    do {
                        let decoded = try JSONDecoder().decode([User].self, from: data)
                        self.users = decoded
                    } catch {
                        self.errorMessage = "Failed to parse users: \(error.localizedDescription)"
                    }
                    continuation.resume()
                }
            }
            currentTask = task
            task.resume()
        }
    }
}

