import Foundation

/// Application configuration loaded from a JSON file, with defaults,
/// range validation, and overrides from `APP_`-prefixed environment variables.
public struct AppConfig: Equatable {
    public static let defaultBaseURL = "https://example.com"
    public static let defaultTimeout = 30
    public static let defaultMaxConnections = 8

    public static let timeoutRange = 1...120
    public static let maxConnectionsRange = 1...64

    public var baseURL: String
    public var timeout: Int
    public var maxConnections: Int

    public init(
        baseURL: String = AppConfig.defaultBaseURL,
        timeout: Int = AppConfig.defaultTimeout,
        maxConnections: Int = AppConfig.defaultMaxConnections
    ) {
        self.baseURL = baseURL
        self.timeout = timeout
        self.maxConnections = maxConnections
    }

    public enum ConfigError: Error, CustomStringConvertible {
        case fileNotFound(String)
        case invalidJSON(String)
        case invalidBaseURL(String)
        case timeoutOutOfRange(Int)
        case maxConnectionsOutOfRange(Int)
        case invalidEnvironmentValue(key: String, value: String)

        public var description: String {
            switch self {
            case .fileNotFound(let path):
                return "Configuration file not found at path: \(path)"
            case .invalidJSON(let reason):
                return "Configuration file is not valid JSON: \(reason)"
            case .invalidBaseURL(let value):
                return "baseURL must be a valid https URL, got: \(value)"
            case .timeoutOutOfRange(let value):
                return "timeout must be between \(AppConfig.timeoutRange.lowerBound) and " +
                    "\(AppConfig.timeoutRange.upperBound) seconds, got: \(value)"
            case .maxConnectionsOutOfRange(let value):
                return "maxConnections must be between \(AppConfig.maxConnectionsRange.lowerBound) and " +
                    "\(AppConfig.maxConnectionsRange.upperBound), got: \(value)"
            case .invalidEnvironmentValue(let key, let value):
                return "Environment variable \(key) has an invalid value: \(value)"
            }
        }
    }

    private struct RawConfig: Decodable {
        var baseURL: String?
        var timeout: Int?
        var maxConnections: Int?
    }

    /// Loads configuration from a JSON file at `path`, applying defaults for any
    /// missing fields, then merges overrides from `APP_`-prefixed environment
    /// variables (e.g. `APP_BASE_URL`, `APP_TIMEOUT`, `APP_MAX_CONNECTIONS`),
    /// and finally validates the resulting values.
    public static func load(
        path: String,
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) throws -> AppConfig {
        guard FileManager.default.fileExists(atPath: path) else {
            throw ConfigError.fileNotFound(path)
        }
        let data = try Data(contentsOf: URL(fileURLWithPath: path))

        let raw: RawConfig
        do {
            raw = try JSONDecoder().decode(RawConfig.self, from: data)
        } catch {
            throw ConfigError.invalidJSON(String(describing: error))
        }

        var config = AppConfig(
            baseURL: raw.baseURL ?? AppConfig.defaultBaseURL,
            timeout: raw.timeout ?? AppConfig.defaultTimeout,
            maxConnections: raw.maxConnections ?? AppConfig.defaultMaxConnections
        )

        try config.applyEnvironmentOverrides(environment)
        try config.validate()
        return config
    }

    private mutating func applyEnvironmentOverrides(_ environment: [String: String]) throws {
        if let value = environment["APP_BASE_URL"] {
            baseURL = value
        }
        if let raw = environment["APP_TIMEOUT"] {
            guard let value = Int(raw) else {
                throw ConfigError.invalidEnvironmentValue(key: "APP_TIMEOUT", value: raw)
            }
            timeout = value
        }
        if let raw = environment["APP_MAX_CONNECTIONS"] {
            guard let value = Int(raw) else {
                throw ConfigError.invalidEnvironmentValue(key: "APP_MAX_CONNECTIONS", value: raw)
            }
            maxConnections = value
        }
    }

    public func validate() throws {
        guard let url = URL(string: baseURL), url.scheme == "https", url.host != nil else {
            throw ConfigError.invalidBaseURL(baseURL)
        }
        guard AppConfig.timeoutRange.contains(timeout) else {
            throw ConfigError.timeoutOutOfRange(timeout)
        }
        guard AppConfig.maxConnectionsRange.contains(maxConnections) else {
            throw ConfigError.maxConnectionsOutOfRange(maxConnections)
        }
    }
}

import Foundation

/// A generic disk-backed cache that persists `Codable` values as JSON files
/// under the user's caches directory, with per-entry expiration and a
/// max-total-size budget enforced via oldest-first eviction.
final class DiskCache<Value: Codable> {
    private struct Envelope: Codable {
        let value: Value
        let storedAt: Date
        let expiresAt: Date?
    }

    private struct FileEntry {
        let url: URL
        let size: Int
        let modifiedAt: Date
    }

    private let directoryURL: URL
    private let maxTotalSize: Int
    private let defaultExpiration: TimeInterval?
    private let fileManager = FileManager.default
    private let queue = DispatchQueue(label: "DiskCache.\(Value.self)", attributes: .concurrent)
    private let encoder = JSONEncoder()
    private let decoder = JSONDecoder()

    /// - Parameters:
    ///   - namespace: Subdirectory name under the caches directory used to isolate entries.
    ///   - maxTotalSize: Maximum combined size in bytes of all cached files. Oldest entries
    ///     are evicted first once this is exceeded.
    ///   - defaultExpiration: Default time-to-live applied to entries that don't specify one.
    ///     `nil` means entries never expire unless a per-entry expiration is given.
    init(namespace: String, maxTotalSize: Int, defaultExpiration: TimeInterval? = nil) {
        let cachesURL = fileManager.urls(for: .cachesDirectory, in: .userDomainMask)[0]
        self.directoryURL = cachesURL.appendingPathComponent(namespace, isDirectory: true)
        self.maxTotalSize = maxTotalSize
        self.defaultExpiration = defaultExpiration

        encoder.dateEncodingStrategy = .secondsSince1970
        decoder.dateDecodingStrategy = .secondsSince1970

        try? fileManager.createDirectory(at: directoryURL, withIntermediateDirectories: true)
    }

    /// Stores `value` for `key`, replacing any existing entry.
    /// - Parameter expiration: Time-to-live for this entry. If `nil`, falls back to the
    ///   cache's `defaultExpiration`.
    func set(_ value: Value, forKey key: String, expiration: TimeInterval? = nil) {
        let ttl = expiration ?? defaultExpiration
        let expiresAt = ttl.map { Date().addingTimeInterval($0) }
        let envelope = Envelope(value: value, storedAt: Date(), expiresAt: expiresAt)

        guard let data = try? encoder.encode(envelope) else { return }

        queue.sync(flags: .barrier) {
            let url = fileURL(forKey: key)
            try? data.write(to: url, options: .atomic)
            enforceSizeLimitLocked()
        }
    }

    /// Returns the cached value for `key`, or `nil` if it's missing, expired, or unreadable.
    /// Expired entries are removed as a side effect.
    func value(forKey key: String) -> Value? {
        queue.sync {
            let url = fileURL(forKey: key)
            guard let data = try? Data(contentsOf: url),
                  let envelope = try? decoder.decode(Envelope.self, from: data) else {
                return nil
            }

            if let expiresAt = envelope.expiresAt, expiresAt <= Date() {
                queue.async(flags: .barrier) { [fileManager] in
                    try? fileManager.removeItem(at: url)
                }
                return nil
            }

            return envelope.value
        }
    }

    /// Removes the entry for `key`, if present.
    func removeValue(forKey key: String) {
        queue.sync(flags: .barrier) {
            try? fileManager.removeItem(at: fileURL(forKey: key))
        }
    }

    /// Removes all entries from the cache.
    func removeAll() {
        queue.sync(flags: .barrier) {
            guard let urls = try? fileManager.contentsOfDirectory(
                at: directoryURL, includingPropertiesForKeys: nil
            ) else { return }
            for url in urls {
                try? fileManager.removeItem(at: url)
            }
        }
    }

    // MARK: - Private

    private func fileURL(forKey key: String) -> URL {
        let safeName = key.addingPercentEncoding(withAllowedCharacters: .alphanumerics) ?? key
        return directoryURL.appendingPathComponent(safeName).appendingPathExtension("json")
    }

    /// Evicts the oldest entries (by stored date) until the cache's total size
    /// is within `maxTotalSize`. Must be called while holding the barrier queue.
    private func enforceSizeLimitLocked() {
        guard let urls = try? fileManager.contentsOfDirectory(
            at: directoryURL,
            includingPropertiesForKeys: [.fileSizeKey, .contentModificationDateKey]
        ) else { return }

        var entries: [FileEntry] = []
        var totalSize = 0
        for url in urls {
            guard let resourceValues = try? url.resourceValues(
                forKeys: [.fileSizeKey, .contentModificationDateKey]
            ) else { continue }
            let size = resourceValues.fileSize ?? 0
            let modifiedAt = resourceValues.contentModificationDate ?? .distantPast
            entries.append(FileEntry(url: url, size: size, modifiedAt: modifiedAt))
            totalSize += size
        }

        guard totalSize > maxTotalSize else { return }

        let oldestFirst = entries.sorted { $0.modifiedAt < $1.modifiedAt }
        for entry in oldestFirst {
            guard totalSize > maxTotalSize else { break }
            try? fileManager.removeItem(at: entry.url)
            totalSize -= entry.size
        }
    }
}

import Foundation

/// A generic on-disk cache that persists `Codable` values as JSON files.
///
/// Entries can carry an optional expiration date, and the cache enforces a
/// maximum total size on disk by evicting the oldest entries first.
public final class DiskCache<Value: Codable> {
    public enum DiskCacheError: Error {
        case cachesDirectoryUnavailable
    }

    private struct Entry: Codable {
        let value: Value
        let storedAt: Date
        let expiresAt: Date?
    }

    private let directoryURL: URL
    private let maxTotalSizeInBytes: Int
    private let fileManager: FileManager
    private let queue: DispatchQueue
    private let encoder = JSONEncoder()
    private let decoder = JSONDecoder()

    /// - Parameters:
    ///   - name: A unique name for this cache; used as the subdirectory under the caches directory.
    ///   - maxTotalSizeInBytes: The maximum combined size of all cached files before oldest entries are evicted.
    public init(
        name: String,
        maxTotalSizeInBytes: Int = 50 * 1024 * 1024,
        fileManager: FileManager = .default
    ) throws {
        guard let cachesURL = fileManager.urls(for: .cachesDirectory, in: .userDomainMask).first else {
            throw DiskCacheError.cachesDirectoryUnavailable
        }
        self.fileManager = fileManager
        self.maxTotalSizeInBytes = maxTotalSizeInBytes
        self.directoryURL = cachesURL.appendingPathComponent(name, isDirectory: true)
        self.queue = DispatchQueue(label: "com.diskcache.\(name)")

        try fileManager.createDirectory(at: directoryURL, withIntermediateDirectories: true)
    }

    /// Stores `value` for `key`, optionally expiring after `expiresIn` seconds.
    public func set(_ value: Value, forKey key: String, expiresIn: TimeInterval? = nil) throws {
        try queue.sync {
            let expiresAt = expiresIn.map { Date().addingTimeInterval($0) }
            let entry = Entry(value: value, storedAt: Date(), expiresAt: expiresAt)
            let data = try encoder.encode(entry)
            try data.write(to: fileURL(forKey: key), options: .atomic)
            enforceSizeLimit()
        }
    }

    /// Returns the cached value for `key`, or `nil` if it is missing, unreadable, or expired.
    public func value(forKey key: String) -> Value? {
        queue.sync {
            let url = fileURL(forKey: key)
            guard let data = try? Data(contentsOf: url) else { return nil }

            guard let entry = try? decoder.decode(Entry.self, from: data) else {
                try? fileManager.removeItem(at: url)
                return nil
            }

            if let expiresAt = entry.expiresAt, expiresAt <= Date() {
                try? fileManager.removeItem(at: url)
                return nil
            }

            return entry.value
        }
    }

    /// Removes the cached value for `key`, if any.
    public func removeValue(forKey key: String) {
        queue.sync {
            try? fileManager.removeItem(at: fileURL(forKey: key))
        }
    }

    /// Removes every cached value.
    public func removeAll() {
        queue.sync {
            guard let contents = try? fileManager.contentsOfDirectory(
                at: directoryURL,
                includingPropertiesForKeys: nil
            ) else { return }
            for url in contents {
                try? fileManager.removeItem(at: url)
            }
        }
    }

    private func fileURL(forKey key: String) -> URL {
        let fileName = Data(key.utf8).base64EncodedString()
            .replacingOccurrences(of: "/", with: "_")
        return directoryURL.appendingPathComponent(fileName).appendingPathExtension("json")
    }

    /// Must be called while already on `queue`.
    private func enforceSizeLimit() {
        guard let contents = try? fileManager.contentsOfDirectory(
            at: directoryURL,
            includingPropertiesForKeys: [.contentModificationDateKey, .fileSizeKey]
        ) else { return }

        var items: [(url: URL, modifiedAt: Date, size: Int)] = []
        var totalSize = 0

        for url in contents {
            let resourceValues = try? url.resourceValues(forKeys: [.contentModificationDateKey, .fileSizeKey])
            let size = resourceValues?.fileSize ?? 0
            let modifiedAt = resourceValues?.contentModificationDate ?? Date.distantPast
            items.append((url, modifiedAt, size))
            totalSize += size
        }

        guard totalSize > maxTotalSizeInBytes else { return }

        for item in items.sorted(by: { $0.modifiedAt < $1.modifiedAt }) {
            guard totalSize > maxTotalSizeInBytes else { break }
            try? fileManager.removeItem(at: item.url)
            totalSize -= item.size
        }
    }
}

import Foundation
import SwiftUI

struct User: Identifiable, Decodable {
    let id: Int
    let name: String
    let email: String
}

@MainActor
final class UserListViewModel: ObservableObject {
    @Published var users: [User] = []
    @Published var isLoading = false
    @Published var errorMessage: String?
    @Published var searchText = ""

    nonisolated static let defaultEndpoint: URL = {
        guard let url = URL(string: "https://jsonplaceholder.typicode.com/users") else {
            fatalError("Invalid default users endpoint URL.")
        }
        return url
    }()

    private let endpoint: URL
    private let session: URLSession

    var filteredUsers: [User] {
        guard !searchText.isEmpty else { return users }
        return users.filter {
            $0.name.localizedCaseInsensitiveContains(searchText)
                || $0.email.localizedCaseInsensitiveContains(searchText)
        }
    }

    nonisolated init(
        endpoint: URL = UserListViewModel.defaultEndpoint,
        session: URLSession = .shared
    ) {
        self.endpoint = endpoint
        self.session = session
    }

    func loadUsers() {
        isLoading = true
        errorMessage = nil

        session.dataTask(with: endpoint) { [weak self] data, response, error in
            DispatchQueue.main.async {
                guard let self else { return }
                self.isLoading = false

                if let error {
                    self.errorMessage = error.localizedDescription
                    return
                }

                guard let data else {
                    self.errorMessage = "No data received."
                    return
                }

                do {
                    self.users = try JSONDecoder().decode([User].self, from: data)
                } catch {
                    self.errorMessage = "Failed to parse users: \(error.localizedDescription)"
                }
            }
        }.resume()
    }
}

struct UserListView: View {
    @StateObject private var viewModel: UserListViewModel

    init(viewModel: UserListViewModel = UserListViewModel()) {
        _viewModel = StateObject(wrappedValue: viewModel)
    }

    var body: some View {
        NavigationStack {
            List {
                if let errorMessage = viewModel.errorMessage {
                    Text(errorMessage)
                        .foregroundColor(.red)
                }
                ForEach(viewModel.filteredUsers) { user in
                    VStack(alignment: .leading) {
                        Text(user.name).font(.headline)
                        Text(user.email).font(.subheadline).foregroundColor(.secondary)
                    }
                }
            }
            .navigationTitle("Users")
            .searchable(text: $viewModel.searchText)
            .refreshable {
                viewModel.loadUsers()
            }
            .overlay {
                if viewModel.isLoading && viewModel.users.isEmpty {
                    ProgressView()
                }
            }
            .task {
                if viewModel.users.isEmpty {
                    viewModel.loadUsers()
                }
            }
        }
    }
}

import Foundation

/// Application configuration loaded from a JSON file, with defaults and
/// `APP_`-prefixed environment variable overrides applied on top.
public struct AppConfig: Equatable {
    public var timeout: Int
    public var maxConnections: Int
    public var baseURL: URL

    public static let defaultTimeout = 30
    public static let defaultMaxConnections = 10
    public static let defaultBaseURL = "https://api.example.com"

    public static let timeoutRange = 1...120
    public static let maxConnectionsRange = 1...64

    public init(timeout: Int, maxConnections: Int, baseURL: URL) {
        self.timeout = timeout
        self.maxConnections = maxConnections
        self.baseURL = baseURL
    }
}

public enum AppConfigError: Error, CustomStringConvertible {
    case fileNotFound(path: String)
    case invalidJSON(underlying: Error)
    case invalidBaseURL(String)
    case timeoutOutOfRange(Int)
    case maxConnectionsOutOfRange(Int)

    public var description: String {
        switch self {
        case .fileNotFound(let path):
            return "Configuration file not found at path: \(path)"
        case .invalidJSON(let underlying):
            return "Configuration file is not valid JSON: \(underlying)"
        case .invalidBaseURL(let value):
            return "baseURL must be a valid https URL, got: \(value)"
        case .timeoutOutOfRange(let value):
            return "timeout must be between \(AppConfig.timeoutRange.lowerBound) and \(AppConfig.timeoutRange.upperBound) seconds, got: \(value)"
        case .maxConnectionsOutOfRange(let value):
            return "maxConnections must be between \(AppConfig.maxConnectionsRange.lowerBound) and \(AppConfig.maxConnectionsRange.upperBound), got: \(value)"
        }
    }
}

/// Raw representation of the on-disk JSON config, where every field is optional
/// so that missing keys can fall back to defaults.
private struct RawAppConfig: Decodable {
    var timeout: Int?
    var maxConnections: Int?
    var baseURL: String?
}

extension AppConfig {
    /// Loads configuration from the JSON file at `path`, filling in defaults for
    /// missing fields, applying `APP_`-prefixed environment variable overrides,
    /// and validating the final result.
    public static func load(
        path: String,
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) throws -> AppConfig {
        let fileManager = FileManager.default
        guard fileManager.fileExists(atPath: path) else {
            throw AppConfigError.fileNotFound(path: path)
        }
        let data = try Data(contentsOf: URL(fileURLWithPath: path))

        let raw: RawAppConfig
        do {
            raw = try JSONDecoder().decode(RawAppConfig.self, from: data)
        } catch {
            throw AppConfigError.invalidJSON(underlying: error)
        }

        var timeout = raw.timeout ?? defaultTimeout
        var maxConnections = raw.maxConnections ?? defaultMaxConnections
        var baseURLString = raw.baseURL ?? defaultBaseURL

        if let override = environment["APP_TIMEOUT"], let value = Int(override) {
            timeout = value
        }
        if let override = environment["APP_MAX_CONNECTIONS"], let value = Int(override) {
            maxConnections = value
        }
        if let override = environment["APP_BASE_URL"] {
            baseURLString = override
        }

        guard timeoutRange.contains(timeout) else {
            throw AppConfigError.timeoutOutOfRange(timeout)
        }
        guard maxConnectionsRange.contains(maxConnections) else {
            throw AppConfigError.maxConnectionsOutOfRange(maxConnections)
        }
        guard let baseURL = URL(string: baseURLString), baseURL.scheme == "https", baseURL.host != nil else {
            throw AppConfigError.invalidBaseURL(baseURLString)
        }

        return AppConfig(timeout: timeout, maxConnections: maxConnections, baseURL: baseURL)
    }
}

import Foundation

public struct AppConfig: Equatable {
    public var timeout: Double
    public var maxConnections: Int
    public var baseURL: URL

    public static let defaultTimeout: Double = 30
    public static let defaultMaxConnections: Int = 8
    public static let defaultBaseURLString = "https://api.example.com"

    public static let timeoutRange: ClosedRange<Double> = 1...120
    public static let maxConnectionsRange: ClosedRange<Int> = 1...64
}

public enum AppConfigError: Error, CustomStringConvertible {
    case fileNotFound(String)
    case unreadable(path: String, underlying: Error)
    case invalidJSON(path: String, underlying: Error)
    case invalidValue(field: String, reason: String)

    public var description: String {
        switch self {
        case .fileNotFound(let path):
            return "Configuration file not found at \(path)"
        case .unreadable(let path, let underlying):
            return "Could not read configuration file at \(path): \(underlying.localizedDescription)"
        case .invalidJSON(let path, let underlying):
            return "Invalid JSON in configuration file at \(path): \(underlying.localizedDescription)"
        case .invalidValue(let field, let reason):
            return "Invalid value for '\(field)': \(reason)"
        }
    }
}

private struct RawAppConfig: Decodable {
    var timeout: Double?
    var maxConnections: Int?
    var baseURL: String?
}

public enum AppConfigLoader {
    /// Loads config from `path`, applies defaults for missing fields, then lets
    /// `APP_`-prefixed environment variables override the file before validating ranges.
    public static func load(
        path: String,
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) throws -> AppConfig {
        guard FileManager.default.fileExists(atPath: path) else {
            throw AppConfigError.fileNotFound(path)
        }

        let data: Data
        do {
            data = try Data(contentsOf: URL(fileURLWithPath: path))
        } catch {
            throw AppConfigError.unreadable(path: path, underlying: error)
        }

        let raw: RawAppConfig
        do {
            raw = try JSONDecoder().decode(RawAppConfig.self, from: data)
        } catch {
            throw AppConfigError.invalidJSON(path: path, underlying: error)
        }

        var timeout = raw.timeout ?? AppConfig.defaultTimeout
        var maxConnections = raw.maxConnections ?? AppConfig.defaultMaxConnections
        var baseURLString = raw.baseURL ?? AppConfig.defaultBaseURLString

        if let override = environment["APP_TIMEOUT"] {
            guard let value = Double(override) else {
                throw AppConfigError.invalidValue(field: "APP_TIMEOUT", reason: "'\(override)' is not a number")
            }
            timeout = value
        }

        if let override = environment["APP_MAX_CONNECTIONS"] {
            guard let value = Int(override) else {
                throw AppConfigError.invalidValue(field: "APP_MAX_CONNECTIONS", reason: "'\(override)' is not an integer")
            }
            maxConnections = value
        }

        if let override = environment["APP_BASE_URL"] {
            baseURLString = override
        }

        guard AppConfig.timeoutRange.contains(timeout) else {
            throw AppConfigError.invalidValue(
                field: "timeout",
                reason: "must be between \(AppConfig.timeoutRange.lowerBound) and \(AppConfig.timeoutRange.upperBound) seconds, got \(timeout)"
            )
        }

        guard AppConfig.maxConnectionsRange.contains(maxConnections) else {
            throw AppConfigError.invalidValue(
                field: "maxConnections",
                reason: "must be between \(AppConfig.maxConnectionsRange.lowerBound) and \(AppConfig.maxConnectionsRange.upperBound), got \(maxConnections)"
            )
        }

        guard let baseURL = URL(string: baseURLString),
              let scheme = baseURL.scheme?.lowercased(), scheme == "https",
              let host = baseURL.host, !host.isEmpty
        else {
            throw AppConfigError.invalidValue(field: "baseURL", reason: "must be a valid https URL, got '\(baseURLString)'")
        }

        return AppConfig(timeout: timeout, maxConnections: maxConnections, baseURL: baseURL)
    }
}

import Foundation
import CryptoKit
#if canImport(AppKit)
import AppKit
#endif

enum ImageLoaderError: Error {
    case invalidImageData
    case httpError(statusCode: Int)
}

actor ImageLoader {
    static let shared = ImageLoader()

    private let session: URLSession
    private let memoryCache = NSCache<NSString, NSImage>()
    private let diskCacheURL: URL
    private let fileManager = FileManager.default
    private let maxRetries: Int
    private let baseBackoff: TimeInterval

    private var inFlightTasks: [URL: Task<NSImage, Error>] = [:]

    init(
        session: URLSession = .shared,
        diskCacheURL: URL? = nil,
        maxRetries: Int = 3,
        baseBackoff: TimeInterval = 0.5
    ) {
        self.session = session
        self.maxRetries = maxRetries
        self.baseBackoff = baseBackoff

        if let diskCacheURL {
            self.diskCacheURL = diskCacheURL
        } else {
            let caches = FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask).first
                ?? FileManager.default.temporaryDirectory
            self.diskCacheURL = caches.appendingPathComponent("ImageLoaderCache", isDirectory: true)
        }

        try? fileManager.createDirectory(at: self.diskCacheURL, withIntermediateDirectories: true)
    }

    func image(for url: URL) async throws -> NSImage {
        let cacheKey = url.absoluteString as NSString

        if let cached = memoryCache.object(forKey: cacheKey) {
            return cached
        }

        if let existing = inFlightTasks[url] {
            return try await existing.value
        }

        let task = Task<NSImage, Error> {
            defer { inFlightTasks[url] = nil }
            return try await self.loadImage(for: url)
        }
        inFlightTasks[url] = task

        return try await task.value
    }

    private func loadImage(for url: URL) async throws -> NSImage {
        let cacheKey = url.absoluteString as NSString

        if let diskData = diskCacheData(for: url), let image = NSImage(data: diskData) {
            memoryCache.setObject(image, forKey: cacheKey, cost: diskData.count)
            return image
        }

        let data = try await downloadWithRetry(url: url)

        guard let image = NSImage(data: data) else {
            throw ImageLoaderError.invalidImageData
        }

        memoryCache.setObject(image, forKey: cacheKey, cost: data.count)
        writeDiskCacheData(data, for: url)

        return image
    }

    private func downloadWithRetry(url: URL) async throws -> Data {
        var attempt = 0
        var lastError: Error?

        while attempt <= maxRetries {
            do {
                let (data, response) = try await session.data(from: url)

                if let httpResponse = response as? HTTPURLResponse {
                    if httpResponse.statusCode == 200 {
                        return data
                    }
                    if isTransientStatusCode(httpResponse.statusCode), attempt < maxRetries {
                        lastError = ImageLoaderError.httpError(statusCode: httpResponse.statusCode)
                        try await Task.sleep(nanoseconds: backoffNanoseconds(forAttempt: attempt))
                        attempt += 1
                        continue
                    }
                    throw ImageLoaderError.httpError(statusCode: httpResponse.statusCode)
                }

                return data
            } catch {
                if isTransientError(error), attempt < maxRetries {
                    lastError = error
                    try await Task.sleep(nanoseconds: backoffNanoseconds(forAttempt: attempt))
                    attempt += 1
                    continue
                }
                throw error
            }
        }

        throw lastError ?? URLError(.unknown)
    }

    private func backoffNanoseconds(forAttempt attempt: Int) -> UInt64 {
        let delay = baseBackoff * pow(2, Double(attempt))
        return UInt64(delay * 1_000_000_000)
    }

    private func isTransientError(_ error: Error) -> Bool {
        let urlError = error as? URLError
        guard let urlError else { return false }
        switch urlError.code {
        case .timedOut, .networkConnectionLost, .notConnectedToInternet,
             .dnsLookupFailed, .cannotConnectToHost, .cannotFindHost,
             .resourceUnavailable, .badServerResponse:
            return true
        default:
            return false
        }
    }

    private func isTransientStatusCode(_ statusCode: Int) -> Bool {
        statusCode == 408 || statusCode == 429 || (500...599).contains(statusCode)
    }

    private func diskCachePath(for url: URL) -> URL {
        let fileName = sha256Hex(url.absoluteString)
        return diskCacheURL.appendingPathComponent(fileName)
    }

    private func diskCacheData(for url: URL) -> Data? {
        let path = diskCachePath(for: url)
        return try? Data(contentsOf: path)
    }

    private func writeDiskCacheData(_ data: Data, for url: URL) {
        let path = diskCachePath(for: url)
        try? data.write(to: path, options: .atomic)
    }

    private func sha256Hex(_ string: String) -> String {
        let digest = SHA256.hash(data: Data(string.utf8))
        return digest.map { String(format: "%02x", $0) }.joined()
    }
}

