import Foundation
import AppKit
import CryptoKit

/// Downloads images by URL with async/await, caching decoded images in memory and on disk.
/// Concurrent requests for the same URL are coalesced into a single download.
actor ImageLoader {

    enum LoaderError: Error {
        case invalidImageData
        case transportFailure(Error)
    }

    private static let nanosecondsPerSecond: Double = 1_000_000_000
    private static let backoffMultiplier: Double = 2
    private static let tooManyRequestsStatus = 429
    private static let serverErrorStatusRange = 500...599

    static let shared = ImageLoader()

    private let session: URLSession
    private let memoryCache = NSCache<NSString, NSImage>()
    private let fileManager = FileManager.default
    private let diskCacheURL: URL
    private let maxRetries: Int
    private let initialBackoff: TimeInterval

    /// In-flight downloads keyed by URL, so concurrent callers share one task.
    private var inFlightTasks: [URL: Task<NSImage, Error>] = [:]

    init(
        session: URLSession = .shared,
        cacheDirectoryName: String = "ImageLoaderCache",
        maxRetries: Int = 3,
        initialBackoff: TimeInterval = 0.5
    ) {
        self.session = session
        self.maxRetries = maxRetries
        self.initialBackoff = initialBackoff

        let fm = FileManager.default
        let base = (try? fm.url(
            for: .cachesDirectory,
            in: .userDomainMask,
            appropriateFor: nil,
            create: true
        )) ?? fm.temporaryDirectory
        self.diskCacheURL = base.appendingPathComponent(cacheDirectoryName, isDirectory: true)
        try? fm.createDirectory(at: diskCacheURL, withIntermediateDirectories: true)
    }

    /// Returns the image for `url`, using memory/disk caches when available and
    /// coalescing concurrent requests for the same URL.
    func image(for url: URL) async throws -> NSImage {
        let cacheKey = url.absoluteString as NSString

        if let cached = memoryCache.object(forKey: cacheKey) {
            return cached
        }

        if let existing = inFlightTasks[url] {
            return try await existing.value
        }

        let task = Task<NSImage, Error> { [weak self] in
            guard let self else { throw LoaderError.invalidImageData }
            return try await self.loadImage(for: url, cacheKey: cacheKey)
        }
        inFlightTasks[url] = task

        defer { inFlightTasks[url] = nil }

        return try await task.value
    }

    private func loadImage(for url: URL, cacheKey: NSString) async throws -> NSImage {
        if let diskImage = loadFromDisk(url: url) {
            memoryCache.setObject(diskImage, forKey: cacheKey)
            return diskImage
        }

        let data = try await downloadWithRetry(url: url)
        guard let image = NSImage(data: data) else {
            throw LoaderError.invalidImageData
        }

        memoryCache.setObject(image, forKey: cacheKey)
        saveToDisk(data: data, url: url)
        return image
    }

    private func downloadWithRetry(url: URL) async throws -> Data {
        var attempt = 0
        var backoff = initialBackoff

        while true {
            do {
                let (data, response) = try await session.data(from: url)
                if let http = response as? HTTPURLResponse, Self.isTransientStatus(http.statusCode) {
                    throw LoaderError.transportFailure(
                        URLError(.badServerResponse, userInfo: [NSURLErrorFailingURLErrorKey: url])
                    )
                }
                return data
            } catch {
                attempt += 1
                guard attempt <= maxRetries, Self.isTransient(error) else {
                    throw error
                }
                try await Task.sleep(nanoseconds: UInt64(backoff * Self.nanosecondsPerSecond))
                backoff *= Self.backoffMultiplier
            }
        }
    }

    private static func isTransient(_ error: Error) -> Bool {
        if let urlError = error as? URLError {
            switch urlError.code {
            case .timedOut, .networkConnectionLost, .notConnectedToInternet,
                 .cannotFindHost, .dnsLookupFailed, .cannotConnectToHost,
                 .badServerResponse, .resourceUnavailable, .internationalRoamingOff,
                 .callIsActive, .dataNotAllowed:
                return true
            default:
                return false
            }
        }
        return false
    }

    private static func isTransientStatus(_ statusCode: Int) -> Bool {
        statusCode == tooManyRequestsStatus || serverErrorStatusRange.contains(statusCode)
    }

    private func diskPath(for url: URL) -> URL {
        let digest = SHA256.hash(data: Data(url.absoluteString.utf8))
        let hex = digest.map { String(format: "%02x", $0) }.joined()
        return diskCacheURL.appendingPathComponent(hex)
    }

    private func loadFromDisk(url: URL) -> NSImage? {
        let path = diskPath(for: url)
        guard let data = try? Data(contentsOf: path) else { return nil }
        return NSImage(data: data)
    }

    private func saveToDisk(data: Data, url: URL) {
        let path = diskPath(for: url)
        try? data.write(to: path, options: .atomic)
    }
}

import Foundation
import AppKit

/// Downloads images by URL, caching decoded results in memory and on disk.
/// Concurrent requests for the same URL share a single in-flight download.
actor ImageLoader {
    enum LoaderError: Error {
        case invalidImageData
        case transportFailure(Error)
    }

    static let shared = ImageLoader()

    private let session: URLSession
    private let memoryCache = NSCache<NSString, NSImage>()
    private let diskCacheDirectory: URL
    private let maxRetries: Int
    private let fileManager = FileManager.default

    /// Tasks for URLs currently being fetched, so concurrent callers await the same work.
    private var inFlightTasks: [URL: Task<NSImage, Error>] = [:]

    init(
        session: URLSession = .shared,
        diskCacheDirectory: URL? = nil,
        memoryCacheLimit: Int = 100,
        maxRetries: Int = 3
    ) {
        self.session = session
        self.maxRetries = maxRetries
        self.memoryCache.countLimit = memoryCacheLimit

        let resolvedDirectory: URL
        if let diskCacheDirectory {
            resolvedDirectory = diskCacheDirectory
        } else {
            let caches = FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask).first
                ?? FileManager.default.temporaryDirectory
            resolvedDirectory = caches.appendingPathComponent("ImageLoaderCache", isDirectory: true)
        }
        self.diskCacheDirectory = resolvedDirectory

        try? FileManager.default.createDirectory(at: resolvedDirectory, withIntermediateDirectories: true)
    }

    /// Returns the image for `url`, using the memory cache, disk cache, or network in that order.
    func image(for url: URL) async throws -> NSImage {
        let cacheKey = url.absoluteString as NSString

        if let cached = memoryCache.object(forKey: cacheKey) {
            return cached
        }

        if let existing = inFlightTasks[url] {
            return try await existing.value
        }

        let task = Task<NSImage, Error> {
            defer { inFlightTasks[url] = nil }
            if let onDisk = loadFromDisk(url: url) {
                memoryCache.setObject(onDisk, forKey: cacheKey)
                return onDisk
            }
            let image = try await downloadWithRetry(url: url)
            memoryCache.setObject(image, forKey: cacheKey)
            saveToDisk(url: url, image: image)
            return image
        }
        inFlightTasks[url] = task

        do {
            return try await task.value
        } catch {
            inFlightTasks[url] = nil
            throw error
        }
    }

    private func downloadWithRetry(url: URL) async throws -> NSImage {
        var attempt = 0
        var lastError: Error?

        while attempt < maxRetries {
            do {
                let (data, response) = try await session.data(from: url)
                if let http = response as? HTTPURLResponse, !(200...299).contains(http.statusCode) {
                    if isTransient(statusCode: http.statusCode), attempt < maxRetries - 1 {
                        attempt += 1
                        try await Task.sleep(nanoseconds: backoffDelay(attempt: attempt))
                        continue
                    }
                    throw URLError(.badServerResponse)
                }
                guard let image = NSImage(data: data) else {
                    throw LoaderError.invalidImageData
                }
                return image
            } catch {
                lastError = error
                if isTransient(error: error), attempt < maxRetries - 1 {
                    attempt += 1
                    try await Task.sleep(nanoseconds: backoffDelay(attempt: attempt))
                    continue
                }
                throw LoaderError.transportFailure(error)
            }
        }

        throw LoaderError.transportFailure(lastError ?? URLError(.unknown))
    }

    private func backoffDelay(attempt: Int) -> UInt64 {
        let seconds = pow(2.0, Double(attempt - 1))
        return UInt64(seconds * 1_000_000_000)
    }

    private func isTransient(error: Error) -> Bool {
        let nsError = error as NSError
        guard nsError.domain == NSURLErrorDomain else { return false }
        switch nsError.code {
        case URLError.timedOut.rawValue,
             URLError.networkConnectionLost.rawValue,
             URLError.dnsLookupFailed.rawValue,
             URLError.notConnectedToInternet.rawValue,
             URLError.cannotConnectToHost.rawValue,
             URLError.cannotFindHost.rawValue:
            return true
        default:
            return false
        }
    }

    private func isTransient(statusCode: Int) -> Bool {
        statusCode == 429 || (500...599).contains(statusCode)
    }

    private func diskCacheURL(for url: URL) -> URL {
        let hashed = url.absoluteString.data(using: .utf8)?.base64EncodedString()
            .replacingOccurrences(of: "/", with: "_") ?? UUID().uuidString
        return diskCacheDirectory.appendingPathComponent(hashed)
    }

    private func loadFromDisk(url: URL) -> NSImage? {
        let path = diskCacheURL(for: url)
        guard let data = try? Data(contentsOf: path) else { return nil }
        return NSImage(data: data)
    }

    private func saveToDisk(url: URL, image: NSImage) {
        guard let tiff = image.tiffRepresentation,
              let bitmap = NSBitmapImageRep(data: tiff),
              let data = bitmap.representation(using: .png, properties: [:]) else {
            return
        }
        let path = diskCacheURL(for: url)
        try? data.write(to: path, options: .atomic)
    }
}

