export interface RetryOptions {
  /** Maximum number of attempts, including the first call. */
  attempts?: number;
  /** Base delay in milliseconds used for exponential backoff. */
  baseDelayMs?: number;
  /** Upper bound for any single delay, in milliseconds. */
  maxDelayMs?: number;
  /** Randomization factor in [0, 1] applied to each delay. */
  jitter?: number;
  /** Called before each retry with the error and the attempt number that failed. */
  onRetry?: (error: unknown, attempt: number) => void;
}

const DEFAULT_OPTIONS: Required<Omit<RetryOptions, "onRetry">> = {
  attempts: 5,
  baseDelayMs: 200,
  maxDelayMs: 10_000,
  jitter: 0.5,
};

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function computeDelay(
  attempt: number,
  baseDelayMs: number,
  maxDelayMs: number,
  jitter: number,
): number {
  const exponential = Math.min(baseDelayMs * 2 ** (attempt - 1), maxDelayMs);
  const jitterRange = exponential * jitter;
  const jitteredDelay = exponential - jitterRange + Math.random() * jitterRange * 2;
  return Math.max(0, Math.min(jitteredDelay, maxDelayMs));
}

/**
 * Runs `fn`, retrying with exponential backoff and jitter if it throws or
 * its returned promise rejects. Rethrows the last error once attempts are exhausted.
 */
export async function retryWithBackoff<T>(
  fn: () => Promise<T>,
  options: RetryOptions = {},
): Promise<T> {
  const attempts = options.attempts ?? DEFAULT_OPTIONS.attempts;
  const baseDelayMs = options.baseDelayMs ?? DEFAULT_OPTIONS.baseDelayMs;
  const maxDelayMs = options.maxDelayMs ?? DEFAULT_OPTIONS.maxDelayMs;
  const jitter = options.jitter ?? DEFAULT_OPTIONS.jitter;

  let lastError: unknown;

  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      if (attempt === attempts) {
        break;
      }
      options.onRetry?.(error, attempt);
      await sleep(computeDelay(attempt, baseDelayMs, maxDelayMs, jitter));
    }
  }

  throw lastError;
}

