const BATCH_SIZE = 50;

export interface SyncResult {
  totalBatches: number;
  succeededBatches: number;
  failedBatches: FailedBatch[];
}

export interface FailedBatch {
  batchIndex: number;
  recordCount: number;
  error: unknown;
}

function chunk<T>(items: T[], size: number): T[][] {
  const chunks: T[][] = [];
  for (let i = 0; i < items.length; i += size) {
    chunks.push(items.slice(i, i + size));
  }
  return chunks;
}

function getEndpointConfig(): { url: string; token: string } {
  const url = process.env.SYNC_ENDPOINT_URL;
  const token = process.env.SYNC_AUTH_TOKEN;

  if (!url) {
    throw new Error("Missing required environment variable: SYNC_ENDPOINT_URL");
  }
  if (!token) {
    throw new Error("Missing required environment variable: SYNC_AUTH_TOKEN");
  }

  return { url, token };
}

async function uploadBatch(url: string, token: string, batch: unknown[]): Promise<void> {
  const response = await fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({ records: batch }),
  });

  if (!response.ok) {
    throw new Error(`Upload failed with status ${response.status}: ${response.statusText}`);
  }
}

/**
 * Uploads `records` to the configured endpoint in batches, retrying each
 * batch with exponential backoff. Batches that still fail after retries are
 * collected and returned rather than aborting the whole sync.
 */
export async function syncRecords(records: unknown[]): Promise<SyncResult> {
  const { url, token } = getEndpointConfig();
  const batches = chunk(records, BATCH_SIZE);
  const failedBatches: FailedBatch[] = [];

  for (const [batchIndex, batch] of batches.entries()) {
    try {
      await retryWithBackoff(() => uploadBatch(url, token, batch));
    } catch (error) {
      failedBatches.push({ batchIndex, recordCount: batch.length, error });
    }
  }

  return {
    totalBatches: batches.length,
    succeededBatches: batches.length - failedBatches.length,
    failedBatches,
  };
}

function reportResult(result: SyncResult): void {
  console.log(
    `Sync complete: ${result.succeededBatches}/${result.totalBatches} batches succeeded.`,
  );

  if (result.failedBatches.length > 0) {
    console.error(`${result.failedBatches.length} batch(es) failed:`);
    for (const failure of result.failedBatches) {
      console.error(
        `  batch ${failure.batchIndex} (${failure.recordCount} records): ${
          failure.error instanceof Error ? failure.error.message : String(failure.error)
        }`,
      );
    }
  }
}

async function main(): Promise<void> {
  const records: unknown[] = [];
  const result = await syncRecords(records);
  reportResult(result);

  if (result.failedBatches.length > 0) {
    process.exitCode = 1;
  }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch((error) => {
    console.error("Sync failed:", error);
    process.exitCode = 1;
  });
}

export interface RetryOptions {
  /** Maximum number of attempts, including the first one. */
  attempts?: number;
  /** Base delay in milliseconds used for exponential backoff. */
  baseDelayMs?: number;
  /** Upper bound for any computed delay, in milliseconds. */
  maxDelayMs?: number;
  /** Randomization factor in [0, 1] applied to each delay to avoid thundering herds. */
  jitter?: number;
  /** Called after a failed attempt, before waiting to retry. */
  onRetry?: (error: unknown, attempt: number, delayMs: number) => void;
}

const DEFAULT_OPTIONS: Required<Omit<RetryOptions, "onRetry">> = {
  attempts: 5,
  baseDelayMs: 200,
  maxDelayMs: 10_000,
  jitter: 0.5,
};

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function computeDelay(attempt: number, baseDelayMs: number, maxDelayMs: number, jitter: number): number {
  const exponential = Math.min(baseDelayMs * 2 ** (attempt - 1), maxDelayMs);
  const jitterRange = exponential * jitter;
  const jitteredDelay = exponential - jitterRange + Math.random() * jitterRange * 2;
  return Math.max(0, Math.min(jitteredDelay, maxDelayMs));
}

/**
 * Runs `fn`, retrying with exponential backoff (plus jitter) on failure.
 * Rethrows the last error once `attempts` is exhausted.
 */
export async function retryWithBackoff<T>(fn: () => Promise<T>, options: RetryOptions = {}): Promise<T> {
  const attempts = options.attempts ?? DEFAULT_OPTIONS.attempts;
  const baseDelayMs = options.baseDelayMs ?? DEFAULT_OPTIONS.baseDelayMs;
  const maxDelayMs = options.maxDelayMs ?? DEFAULT_OPTIONS.maxDelayMs;
  const jitter = options.jitter ?? DEFAULT_OPTIONS.jitter;

  let lastError: unknown;

  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;

      if (attempt === attempts) {
        break;
      }

      const delayMs = computeDelay(attempt, baseDelayMs, maxDelayMs, jitter);
      options.onRetry?.(error, attempt, delayMs);
      await sleep(delayMs);
    }
  }

  throw lastError;
}

