import { RateLimiter, type RateLimiterOptions } from "./rateLimiter.js";

/** Minimal subset of Express's Request that this middleware relies on. */
export interface MinimalRequest {
  ip?: string;
  socket: { remoteAddress?: string };
  headers: Record<string, string | string[] | undefined>;
}

/** Minimal subset of Express's Response that this middleware relies on. */
export interface MinimalResponse {
  setHeader(name: string, value: string | number): void;
  status(code: number): this;
  end(chunk?: string): void;
}

export type NextFunction = (err?: unknown) => void;

export type RateLimitMiddleware = (req: MinimalRequest, res: MinimalResponse, next: NextFunction) => void;

export interface RateLimitMiddlewareOptions extends RateLimiterOptions {
  /** How often to sweep stale buckets, in ms. Defaults to `staleAfterMs` (or 10 minutes if unset). */
  cleanupIntervalMs?: number;
}

function clientIp(req: MinimalRequest): string {
  if (req.ip) {
    return req.ip;
  }
  const forwardedFor = req.headers["x-forwarded-for"];
  const forwarded = Array.isArray(forwardedFor) ? forwardedFor[0] : forwardedFor;
  if (forwarded) {
    return forwarded.split(",")[0].trim();
  }
  return req.socket.remoteAddress ?? "unknown";
}

/** Creates an Express-style middleware that rate limits requests per client IP using a token bucket. */
export function createRateLimitMiddleware(options: RateLimitMiddlewareOptions): RateLimitMiddleware {
  const limiter = new RateLimiter(options);
  const cleanupIntervalMs = options.cleanupIntervalMs ?? options.staleAfterMs ?? 10 * 60 * 1000;

  setInterval(() => limiter.cleanup(), cleanupIntervalMs);

  return function rateLimitMiddleware(req: MinimalRequest, res: MinimalResponse, next: NextFunction): void {
    const key = clientIp(req);
    const result = limiter.consume(key);

    if (!result.allowed) {
      res.setHeader("Retry-After", result.retryAfterSeconds);
      res.status(429).end("Too Many Requests");
      return;
    }

    next();
  };
}

export interface RateLimiterOptions {
  /** Maximum number of tokens a bucket can hold. */
  capacity: number;
  /** Tokens added back to a bucket per second. */
  refillPerSecond: number;
  /** How long a bucket may sit idle (full and untouched) before it is swept, in ms. Defaults to 10 minutes. */
  staleAfterMs?: number;
}

export interface ConsumeResult {
  allowed: boolean;
  /** Tokens remaining in the bucket after this attempt. */
  remaining: number;
  /** Seconds the caller should wait before the next token becomes available. Only meaningful when `allowed` is false. */
  retryAfterSeconds: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

export class RateLimiter {
  private readonly capacity: number;
  private readonly refillPerSecond: number;
  private readonly staleAfterMs: number;
  private readonly buckets = new Map<string, Bucket>();

  constructor(options: RateLimiterOptions) {
    if (options.capacity <= 0) {
      throw new Error("capacity must be positive");
    }
    if (options.refillPerSecond <= 0) {
      throw new Error("refillPerSecond must be positive");
    }
    this.capacity = options.capacity;
    this.refillPerSecond = options.refillPerSecond;
    this.staleAfterMs = options.staleAfterMs ?? 10 * 60 * 1000;
  }

  /** Attempt to consume `cost` tokens (default 1) from the bucket for `key`. */
  consume(key: string, cost = 1, now = Date.now()): ConsumeResult {
    const bucket = this.getOrCreateBucket(key, now);
    this.refill(bucket, now);

    if (bucket.tokens >= cost) {
      bucket.tokens -= cost;
      return { allowed: true, remaining: bucket.tokens, retryAfterSeconds: 0 };
    }

    const deficit = cost - bucket.tokens;
    const retryAfterSeconds = Math.ceil(deficit / this.refillPerSecond);
    return { allowed: false, remaining: bucket.tokens, retryAfterSeconds };
  }

  /** Removes buckets that have been full and untouched for longer than `staleAfterMs`. */
  cleanup(now = Date.now()): number {
    let removed = 0;
    for (const [key, bucket] of this.buckets) {
      this.refill(bucket, now);
      const idleMs = now - bucket.lastRefill;
      if (bucket.tokens >= this.capacity && idleMs >= this.staleAfterMs) {
        this.buckets.delete(key);
        removed++;
      }
    }
    return removed;
  }

  size(): number {
    return this.buckets.size;
  }

  private getOrCreateBucket(key: string, now: number): Bucket {
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.capacity, lastRefill: now };
      this.buckets.set(key, bucket);
    }
    return bucket;
  }

  private refill(bucket: Bucket, now: number): void {
    const elapsedSeconds = Math.max(0, (now - bucket.lastRefill) / 1000);
    if (elapsedSeconds === 0) {
      return;
    }
    bucket.tokens = Math.min(this.capacity, bucket.tokens + elapsedSeconds * this.refillPerSecond);
    bucket.lastRefill = now;
  }
}

import { RateLimiter, RateLimiterOptions } from "./rateLimiter.js";

/** Minimal subset of Express's Request used by this middleware. */
export interface MinimalRequest {
  ip?: string;
  socket?: { remoteAddress?: string };
  headers: Record<string, string | string[] | undefined>;
}

/** Minimal subset of Express's Response used by this middleware. */
export interface MinimalResponse {
  status(code: number): this;
  setHeader(name: string, value: string): this;
  end(chunk?: string): void;
}

export type NextFunction = (err?: unknown) => void;

export type Middleware = (
  req: MinimalRequest,
  res: MinimalResponse,
  next: NextFunction
) => void;

export interface RateLimitMiddlewareOptions extends RateLimiterOptions {
  /** Derives the rate-limit key from a request. Defaults to the client IP. */
  keyGenerator?: (req: MinimalRequest) => string;
}

function defaultKeyGenerator(req: MinimalRequest): string {
  if (req.ip) {
    return req.ip;
  }
  if (req.socket?.remoteAddress) {
    return req.socket.remoteAddress;
  }
  const forwardedFor = req.headers["x-forwarded-for"];
  if (typeof forwardedFor === "string" && forwardedFor.length > 0) {
    return forwardedFor.split(",")[0].trim();
  }
  if (Array.isArray(forwardedFor) && forwardedFor.length > 0) {
    return forwardedFor[0];
  }
  return "unknown";
}

/** Creates an Express-style middleware that rate limits requests per client IP. */
export function createRateLimitMiddleware(
  options: RateLimitMiddlewareOptions
): Middleware {
  const limiter = new RateLimiter(options);
  const keyGenerator = options.keyGenerator ?? defaultKeyGenerator;

  return function rateLimitMiddleware(req, res, next) {
    const key = keyGenerator(req);
    const result = limiter.consume(key);

    if (!result.allowed) {
      const retryAfterSeconds = Math.max(1, Math.ceil(result.retryAfterSeconds));
      res
        .status(429)
        .setHeader("Retry-After", String(retryAfterSeconds))
        .end("Too Many Requests");
      return;
    }

    next();
  };
}

export interface RateLimiterOptions {
  /** Maximum number of tokens a bucket can hold. */
  capacity: number;
  /** Tokens added back to a bucket per second. */
  refillPerSecond: number;
  /**
   * How long a key's bucket may sit untouched before it's dropped from
   * memory. Defaults to the time it takes an empty bucket to fully refill.
   */
  staleAfterMs?: number;
}

interface Bucket {
  tokens: number;
  lastRefillMs: number;
}

export interface ConsumeResult {
  allowed: boolean;
  /** Tokens remaining in the bucket after this attempt. */
  remaining: number;
  /** Seconds to wait before the next token becomes available, when denied. */
  retryAfterSeconds: number;
}

export class RateLimiter {
  private readonly capacity: number;
  private readonly refillPerSecond: number;
  private readonly staleAfterMs: number;
  private readonly buckets = new Map<string, Bucket>();

  constructor(options: RateLimiterOptions) {
    if (options.capacity <= 0) {
      throw new Error("capacity must be greater than 0");
    }
    if (options.refillPerSecond <= 0) {
      throw new Error("refillPerSecond must be greater than 0");
    }
    this.capacity = options.capacity;
    this.refillPerSecond = options.refillPerSecond;
    this.staleAfterMs =
      options.staleAfterMs ?? (this.capacity / this.refillPerSecond) * 1000;
  }

  /** Attempts to consume one token for `key`, refilling first based on elapsed time. */
  consume(key: string, now: number = Date.now()): ConsumeResult {
    this.evictStale(now);

    const bucket = this.getOrCreateBucket(key, now);
    this.refill(bucket, now);

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens, retryAfterSeconds: 0 };
    }

    const deficit = 1 - bucket.tokens;
    const retryAfterSeconds = deficit / this.refillPerSecond;
    return { allowed: false, remaining: bucket.tokens, retryAfterSeconds };
  }

  /** Number of buckets currently tracked, mostly useful for tests/diagnostics. */
  size(): number {
    return this.buckets.size;
  }

  private getOrCreateBucket(key: string, now: number): Bucket {
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.capacity, lastRefillMs: now };
      this.buckets.set(key, bucket);
    }
    return bucket;
  }

  private refill(bucket: Bucket, now: number): void {
    const elapsedMs = now - bucket.lastRefillMs;
    if (elapsedMs <= 0) {
      return;
    }
    const refillAmount = (elapsedMs / 1000) * this.refillPerSecond;
    bucket.tokens = Math.min(this.capacity, bucket.tokens + refillAmount);
    bucket.lastRefillMs = now;
  }

  private evictStale(now: number): void {
    for (const [key, bucket] of this.buckets) {
      if (now - bucket.lastRefillMs > this.staleAfterMs) {
        this.buckets.delete(key);
      }
    }
  }
}

const RETAIL_SALES_TAX_RATE = 0.0825;
const LARGE_TRANSACTION_THRESHOLD = 10_000;
const RETAIL_CATEGORY = "retail";

export interface Transaction {
  date: string;
  description: string;
  category: string;
  amount: number;
}

export interface FlaggedTransaction extends Transaction {
  taxedAmount: number;
}

export interface MonthlyReport {
  totalsByMonth: Map<string, Map<string, number>>;
  flagged: FlaggedTransaction[];
}

function parseCsvLine(line: string): string[] {
  const fields: string[] = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (inQuotes) {
      if (char === '"') {
        if (line[i + 1] === '"') {
          current += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        current += char;
      }
    } else if (char === '"') {
      inQuotes = true;
    } else if (char === ",") {
      fields.push(current);
      current = "";
    } else {
      current += char;
    }
  }
  fields.push(current);

  return fields;
}

function monthKeyFromDate(date: string): string {
  const match = /^(\d{4}-\d{2})/.exec(date.trim());
  if (!match) {
    throw new Error(`Invalid date: ${date}`);
  }
  return match[1];
}

export function parseTransactions(csv: string): Transaction[] {
  const lines = csv.split(/\r\n|\n|\r/).filter((line) => line.trim().length > 0);
  if (lines.length === 0) {
    return [];
  }

  const [header, ...rows] = lines;
  const headerFields = parseCsvLine(header).map((field) => field.trim().toLowerCase());
  const isHeader =
    headerFields.length === 4 &&
    headerFields[0] === "date" &&
    headerFields[1] === "description" &&
    headerFields[2] === "category" &&
    headerFields[3] === "amount";
  const dataRows = isHeader ? rows : lines;

  return dataRows.map((row) => {
    const [date, description, category, amount] = parseCsvLine(row);
    return {
      date: date.trim(),
      description: description.trim(),
      category: category.trim(),
      amount: Number.parseFloat(amount.trim()),
    };
  });
}

function effectiveAmount(transaction: Transaction): number {
  const isRetail = transaction.category.trim().toLowerCase() === RETAIL_CATEGORY;
  return isRetail ? transaction.amount * (1 + RETAIL_SALES_TAX_RATE) : transaction.amount;
}

export function buildMonthlyReport(transactions: Transaction[]): MonthlyReport {
  const totalsByMonth = new Map<string, Map<string, number>>();
  const flagged: FlaggedTransaction[] = [];

  for (const transaction of transactions) {
    const taxedAmount = effectiveAmount(transaction);
    const monthKey = monthKeyFromDate(transaction.date);

    let categoryTotals = totalsByMonth.get(monthKey);
    if (!categoryTotals) {
      categoryTotals = new Map<string, number>();
      totalsByMonth.set(monthKey, categoryTotals);
    }
    categoryTotals.set(
      transaction.category,
      (categoryTotals.get(transaction.category) ?? 0) + taxedAmount,
    );

    if (taxedAmount > LARGE_TRANSACTION_THRESHOLD) {
      flagged.push({ ...transaction, taxedAmount });
    }
  }

  return { totalsByMonth, flagged };
}

export function parseAndBuildReport(csv: string): MonthlyReport {
  return buildMonthlyReport(parseTransactions(csv));
}

function formatCurrency(amount: number): string {
  return amount.toFixed(2);
}

function padRight(value: string, width: number): string {
  return value.length >= width ? value : value + " ".repeat(width - value.length);
}

function padLeft(value: string, width: number): string {
  return value.length >= width ? value : " ".repeat(width - value.length) + value;
}

export function formatReportAsText(report: MonthlyReport): string {
  const lines: string[] = [];
  const months = [...report.totalsByMonth.keys()].sort();

  const monthWidth = Math.max(5, ...months.map((m) => m.length));
  const categoryWidth = Math.max(
    8,
    ...months.flatMap((m) => [...(report.totalsByMonth.get(m)?.keys() ?? [])].map((c) => c.length)),
  );
  const amountWidth = 12;

  lines.push(
    `${padRight("Month", monthWidth)}  ${padRight("Category", categoryWidth)}  ${padLeft("Amount", amountWidth)}`,
  );
  lines.push("-".repeat(monthWidth + categoryWidth + amountWidth + 4));

  for (const month of months) {
    const categoryTotals = report.totalsByMonth.get(month);
    if (!categoryTotals) continue;
    const categories = [...categoryTotals.keys()].sort();
    for (const category of categories) {
      const total = categoryTotals.get(category) ?? 0;
      lines.push(
        `${padRight(month, monthWidth)}  ${padRight(category, categoryWidth)}  ${padLeft(
          formatCurrency(total),
          amountWidth,
        )}`,
      );
    }
  }

  if (report.flagged.length > 0) {
    lines.push("");
    lines.push("FLAGGED TRANSACTIONS (over $10,000):");
    for (const transaction of report.flagged) {
      lines.push(
        `  ${transaction.date}  ${transaction.description}  [${transaction.category}]  ${formatCurrency(
          transaction.taxedAmount,
        )}`,
      );
    }
  }

  return lines.join("\n");
}

import { TokenBucketRateLimiter, type TokenBucketOptions } from "./rateLimiter.js";

/** Minimal subset of Express/Node's IncomingMessage we depend on. */
export interface MinimalRequest {
  headers: Record<string, string | string[] | undefined>;
  socket?: { remoteAddress?: string };
  /** Express sets this when `trust proxy` is configured; used if present. */
  ip?: string;
}

/** Minimal subset of Express/Node's ServerResponse we depend on. */
export interface MinimalResponse {
  statusCode: number;
  setHeader(name: string, value: string | number): void;
  end(chunk?: string): void;
}

export type NextFunction = (err?: unknown) => void;

export interface RateLimitMiddlewareOptions extends TokenBucketOptions {
  /** Number of tokens each request consumes. Defaults to 1. */
  cost?: number;
}

const HTTP_TOO_MANY_REQUESTS = 429;
const MS_PER_SECOND = 1000;
const MIN_RETRY_AFTER_SECONDS = 1;

function firstForwardedAddress(value: string | string[]): string | undefined {
  const raw = Array.isArray(value) ? value[0] : value.split(",")[0];
  const trimmed = raw?.trim();
  return trimmed ? trimmed : undefined;
}

function getClientIp(req: MinimalRequest): string {
  if (req.ip) {
    return req.ip;
  }

  const forwardedFor = req.headers["x-forwarded-for"];
  if (forwardedFor) {
    const address = firstForwardedAddress(forwardedFor);
    if (address) {
      return address;
    }
  }

  return req.socket?.remoteAddress ?? "unknown";
}

/** Creates Express-style rate-limiting middleware keyed by client IP. */
export function createRateLimitMiddleware(
  options: RateLimitMiddlewareOptions,
): (req: MinimalRequest, res: MinimalResponse, next: NextFunction) => void {
  const limiter = new TokenBucketRateLimiter(options);
  const cost = options.cost ?? 1;

  return function rateLimitMiddleware(req: MinimalRequest, res: MinimalResponse, next: NextFunction): void {
    const key = getClientIp(req);
    const result = limiter.consume(key, cost);

    if (!result.allowed) {
      const retryAfterSeconds = Math.max(MIN_RETRY_AFTER_SECONDS, Math.ceil(result.retryAfterMs / MS_PER_SECOND));
      res.setHeader("Retry-After", retryAfterSeconds);
      res.statusCode = HTTP_TOO_MANY_REQUESTS;
      res.end("Too Many Requests");
      return;
    }

    next();
  };
}

export interface TokenBucketOptions {
  /** Maximum number of tokens a bucket can hold. */
  capacity: number;
  /** How many tokens are added per `refillIntervalMs`. */
  refillTokensPerInterval: number;
  /** Interval (ms) over which `refillTokensPerInterval` tokens are added. */
  refillIntervalMs: number;
  /** How long (ms) a bucket may sit idle before it's swept as stale. Defaults to a generous multiple of the refill interval. */
  staleAfterMs?: number;
  /** Minimum time (ms) between sweep passes. Defaults to `staleAfterMs`. */
  sweepIntervalMs?: number;
}

export interface RateLimitResult {
  allowed: boolean;
  /** Tokens remaining in the bucket after this attempt (floored). */
  remaining: number;
  /** If denied, how long (ms) until enough tokens will be available. */
  retryAfterMs: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
  lastAccess: number;
}

/** Default multiple of the refill interval a bucket may idle before it's considered stale. */
const DEFAULT_STALE_INTERVAL_MULTIPLE = 10;

export class TokenBucketRateLimiter {
  private readonly capacity: number;
  private readonly refillRatePerMs: number;
  private readonly staleAfterMs: number;
  private readonly sweepIntervalMs: number;
  private readonly buckets = new Map<string, Bucket>();
  private lastSweep: number;

  constructor(options: TokenBucketOptions) {
    if (options.capacity <= 0) {
      throw new Error("capacity must be > 0");
    }
    if (options.refillTokensPerInterval <= 0 || options.refillIntervalMs <= 0) {
      throw new Error("refill rate must be > 0");
    }

    this.capacity = options.capacity;
    this.refillRatePerMs = options.refillTokensPerInterval / options.refillIntervalMs;
    this.staleAfterMs =
      options.staleAfterMs ?? options.refillIntervalMs * options.capacity * DEFAULT_STALE_INTERVAL_MULTIPLE;
    this.sweepIntervalMs = options.sweepIntervalMs ?? this.staleAfterMs;
    this.lastSweep = Date.now();
  }

  /** Attempts to consume `cost` tokens for `key`. */
  consume(key: string, cost = 1, now: number = Date.now()): RateLimitResult {
    this.sweep(now);

    const bucket = this.getOrCreateBucket(key, now);
    this.refill(bucket, now);
    bucket.lastAccess = now;

    if (bucket.tokens >= cost) {
      bucket.tokens -= cost;
      return { allowed: true, remaining: Math.floor(bucket.tokens), retryAfterMs: 0 };
    }

    const deficit = cost - bucket.tokens;
    const retryAfterMs = Math.ceil(deficit / this.refillRatePerMs);
    return { allowed: false, remaining: Math.floor(bucket.tokens), retryAfterMs };
  }

  /** Number of buckets currently tracked (mainly for tests/inspection). */
  get bucketCount(): number {
    return this.buckets.size;
  }

  private getOrCreateBucket(key: string, now: number): Bucket {
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.capacity, lastRefill: now, lastAccess: now };
      this.buckets.set(key, bucket);
    }
    return bucket;
  }

  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) {
      return;
    }
    bucket.tokens = Math.min(this.capacity, bucket.tokens + elapsed * this.refillRatePerMs);
    bucket.lastRefill = now;
  }

  private sweep(now: number): void {
    if (now - this.lastSweep < this.sweepIntervalMs) {
      return;
    }
    this.lastSweep = now;

    for (const [key, bucket] of this.buckets) {
      if (now - bucket.lastAccess > this.staleAfterMs) {
        this.buckets.delete(key);
      }
    }
  }
}

interface Entry<V> {
  value: V;
  expiresAt: number;
}

export interface LRUCacheOptions {
  maxSize: number;
  ttlMs: number;
}

export class LRUCache<K, V> {
  private readonly maxSize: number;
  private readonly ttlMs: number;
  private readonly map = new Map<K, Entry<V>>();

  constructor(options: LRUCacheOptions) {
    if (options.maxSize <= 0) {
      throw new Error("maxSize must be greater than 0");
    }
    this.maxSize = options.maxSize;
    this.ttlMs = options.ttlMs;
  }

  get size(): number {
    return this.map.size;
  }

  get(key: K): V | undefined {
    const entry = this.map.get(key);
    if (!entry) {
      return undefined;
    }
    if (entry.expiresAt <= Date.now()) {
      this.map.delete(key);
      return undefined;
    }
    // refresh recency
    this.map.delete(key);
    this.map.set(key, entry);
    return entry.value;
  }

  has(key: K): boolean {
    return this.get(key) !== undefined;
  }

  set(key: K, value: V, ttlMs: number = this.ttlMs): void {
    if (this.map.has(key)) {
      this.map.delete(key);
    } else if (this.map.size >= this.maxSize) {
      const oldestKey = this.map.keys().next().value;
      if (oldestKey !== undefined) {
        this.map.delete(oldestKey);
      }
    }
    this.map.set(key, { value, expiresAt: Date.now() + ttlMs });
  }

  delete(key: K): boolean {
    return this.map.delete(key);
  }

  clear(): void {
    this.map.clear();
  }
}

import { LRUCache } from "./cache.js";

export type FetchUser<T> = (id: string) => Promise<T>;

export interface UserServiceOptions {
  maxSize?: number;
  ttlMs?: number;
}

const DEFAULT_MAX_SIZE = 500;
const DEFAULT_TTL_MS = 5 * 60 * 1000;

export class UserService<T> {
  private readonly fetchUser: FetchUser<T>;
  private readonly cache: LRUCache<string, T>;
  private readonly inFlight = new Map<string, Promise<T>>();

  constructor(fetchUser: FetchUser<T>, options: UserServiceOptions = {}) {
    this.fetchUser = fetchUser;
    this.cache = new LRUCache<string, T>({
      maxSize: options.maxSize ?? DEFAULT_MAX_SIZE,
      ttlMs: options.ttlMs ?? DEFAULT_TTL_MS,
    });
  }

  async getUser(id: string): Promise<T> {
    const cached = this.cache.get(id);
    if (cached !== undefined) {
      return cached;
    }

    const pending = this.inFlight.get(id);
    if (pending) {
      return pending;
    }

    const promise = this.fetchUser(id)
      .then((user) => {
        this.cache.set(id, user);
        return user;
      })
      .finally(() => {
        this.inFlight.delete(id);
      });

    this.inFlight.set(id, promise);
    return promise;
  }

  invalidate(id: string): void {
    this.cache.delete(id);
  }

  prefetch(ids: string[]): void {
    for (const id of ids) {
      if (this.cache.has(id) || this.inFlight.has(id)) {
        continue;
      }
      void this.getUser(id).catch(() => {
        // Errors from background prefetch are not surfaced; a later
        // getUser call for the same id will retry and can report them.
      });
    }
  }
}

const RETAIL_SALES_TAX_RATE = 0.0825;
const REVIEW_THRESHOLD = 10_000;

export interface Transaction {
  date: string;
  description: string;
  category: string;
  amount: number;
}

export interface MonthlyCategoryTotal {
  month: string;
  category: string;
  total: number;
}

export interface TransactionReport {
  totals: MonthlyCategoryTotal[];
  flagged: Transaction[];
}

function parseCSVLine(line: string): string[] {
  const fields: string[] = [];
  let field = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (inQuotes) {
      if (char === '"') {
        if (line[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += char;
      }
    } else if (char === '"') {
      inQuotes = true;
    } else if (char === ",") {
      fields.push(field);
      field = "";
    } else {
      field += char;
    }
  }

  fields.push(field);
  return fields;
}

export function parseTransactions(csv: string): Transaction[] {
  const lines = csv
    .split(/\r\n|\n/)
    .map((line) => line.trim())
    .filter((line) => line.length > 0);

  if (lines.length === 0) {
    return [];
  }

  const [, ...rows] = lines;

  return rows.map((line) => {
    const [date, description, category, amount] = parseCSVLine(line);
    return {
      date: date ?? "",
      description: description ?? "",
      category: category ?? "",
      amount: Number(amount),
    };
  });
}

function monthOf(date: string): string {
  return date.slice(0, 7);
}

function amountWithTax(transaction: Transaction): number {
  return transaction.category.toLowerCase() === "retail"
    ? transaction.amount * (1 + RETAIL_SALES_TAX_RATE)
    : transaction.amount;
}

export function buildReport(csv: string): TransactionReport {
  const transactions = parseTransactions(csv);
  const totalsByKey = new Map<string, MonthlyCategoryTotal>();
  const flagged: Transaction[] = [];

  for (const transaction of transactions) {
    const taxedAmount = amountWithTax(transaction);
    const month = monthOf(transaction.date);
    const key = `${month}|${transaction.category}`;

    const existing = totalsByKey.get(key);
    if (existing) {
      existing.total += taxedAmount;
    } else {
      totalsByKey.set(key, { month, category: transaction.category, total: taxedAmount });
    }

    if (taxedAmount > REVIEW_THRESHOLD) {
      flagged.push({ ...transaction, amount: taxedAmount });
    }
  }

  const totals = [...totalsByKey.values()].sort((a, b) =>
    a.month === b.month ? a.category.localeCompare(b.category) : a.month.localeCompare(b.month),
  );

  return { totals, flagged };
}

function formatCurrency(amount: number): string {
  return amount.toFixed(2);
}

export function formatReport(report: TransactionReport): string {
  const lines: string[] = [];

  lines.push("Month      Category             Total");
  lines.push("-".repeat(45));
  for (const { month, category, total } of report.totals) {
    lines.push(`${month.padEnd(11)}${category.padEnd(21)}${formatCurrency(total).padStart(10)}`);
  }

  lines.push("");
  lines.push("Flagged for review (over $10,000):");
  lines.push("-".repeat(45));
  if (report.flagged.length === 0) {
    lines.push("(none)");
  } else {
    for (const transaction of report.flagged) {
      lines.push(
        `${transaction.date}  ${transaction.description}  [${transaction.category}]  ${formatCurrency(transaction.amount)}`,
      );
    }
  }

  return lines.join("\n");
}

export function generateReport(csv: string): string {
  return formatReport(buildReport(csv));
}

interface CacheEntry<V> {
  value: V;
  expiresAt: number;
}

export interface LruCacheOptions {
  maxSize: number;
  ttlMs: number;
}

export class LruCache<K, V> {
  private readonly maxSize: number;
  private readonly ttlMs: number;
  private readonly entries = new Map<K, CacheEntry<V>>();

  constructor(options: LruCacheOptions) {
    if (options.maxSize <= 0) {
      throw new Error("maxSize must be greater than 0");
    }
    this.maxSize = options.maxSize;
    this.ttlMs = options.ttlMs;
  }

  get(key: K): V | undefined {
    const entry = this.entries.get(key);
    if (!entry) {
      return undefined;
    }
    if (Date.now() >= entry.expiresAt) {
      this.entries.delete(key);
      return undefined;
    }
    // Refresh recency by reinserting.
    this.entries.delete(key);
    this.entries.set(key, entry);
    return entry.value;
  }

  has(key: K): boolean {
    return this.get(key) !== undefined;
  }

  set(key: K, value: V, ttlMs = this.ttlMs): void {
    this.entries.delete(key);
    this.entries.set(key, { value, expiresAt: Date.now() + ttlMs });
    if (this.entries.size > this.maxSize) {
      const oldestKey = this.entries.keys().next().value as K;
      this.entries.delete(oldestKey);
    }
  }

  delete(key: K): void {
    this.entries.delete(key);
  }

  clear(): void {
    this.entries.clear();
  }

  get size(): number {
    return this.entries.size;
  }
}

import { LruCache } from "./cache.js";

export type FetchUser<T> = (id: string) => Promise<T>;

export interface UserServiceOptions {
  maxSize?: number;
  ttlMs?: number;
}

const DEFAULT_MAX_SIZE = 500;
const DEFAULT_TTL_MS = 5 * 60 * 1000;

export class UserService<T> {
  private readonly cache: LruCache<string, T>;
  private readonly fetchUser: FetchUser<T>;
  private readonly inFlight = new Map<string, Promise<T>>();

  constructor(fetchUser: FetchUser<T>, options: UserServiceOptions = {}) {
    this.fetchUser = fetchUser;
    this.cache = new LruCache<string, T>({
      maxSize: options.maxSize ?? DEFAULT_MAX_SIZE,
      ttlMs: options.ttlMs ?? DEFAULT_TTL_MS,
    });
  }

  async getUser(id: string): Promise<T> {
    const cached = this.cache.get(id);
    if (cached !== undefined) {
      return cached;
    }

    const pending = this.inFlight.get(id);
    if (pending) {
      return pending;
    }

    const promise = this.fetchUser(id)
      .then((user) => {
        this.cache.set(id, user);
        return user;
      })
      .finally(() => {
        this.inFlight.delete(id);
      });

    this.inFlight.set(id, promise);
    return promise;
  }

  invalidate(id: string): void {
    this.cache.delete(id);
  }

  prefetch(ids: string[]): void {
    for (const id of ids) {
      void this.getUser(id).catch((error: unknown) => {
        console.error(`prefetch failed for id "${id}":`, error);
      });
    }
  }
}

interface CacheEntry<V> {
  value: V;
  expiresAt: number;
}

export interface LRUCacheOptions {
  /** Maximum number of entries to retain. */
  maxSize: number;
  /** Time-to-live for each entry, in milliseconds. */
  ttlMs: number;
}

export class LRUCache<K, V> {
  private readonly maxSize: number;
  private readonly ttlMs: number;
  private readonly entries = new Map<K, CacheEntry<V>>();

  constructor(options: LRUCacheOptions) {
    if (options.maxSize <= 0) {
      throw new Error("maxSize must be greater than 0");
    }
    this.maxSize = options.maxSize;
    this.ttlMs = options.ttlMs;
  }

  get(key: K): V | undefined {
    const entry = this.entries.get(key);
    if (!entry) {
      return undefined;
    }
    if (entry.expiresAt <= Date.now()) {
      this.entries.delete(key);
      return undefined;
    }
    // Refresh recency by reinserting at the end of iteration order.
    this.entries.delete(key);
    this.entries.set(key, entry);
    return entry.value;
  }

  has(key: K): boolean {
    return this.get(key) !== undefined;
  }

  set(key: K, value: V): void {
    this.entries.delete(key);
    this.entries.set(key, { value, expiresAt: Date.now() + this.ttlMs });
    if (this.entries.size > this.maxSize) {
      const oldestKey = this.entries.keys().next().value as K;
      this.entries.delete(oldestKey);
    }
  }

  delete(key: K): boolean {
    return this.entries.delete(key);
  }

  clear(): void {
    this.entries.clear();
  }

  get size(): number {
    return this.entries.size;
  }
}

import { LRUCache } from "./cache.js";

export type FetchUser<Id, User> = (id: Id) => Promise<User>;

export interface UserServiceOptions {
  /** Maximum number of users to keep cached at once. */
  maxSize?: number;
  /** How long a cached user stays valid, in milliseconds. */
  ttlMs?: number;
}

const DEFAULT_MAX_SIZE = 500;
const DEFAULT_TTL_MS = 5 * 60 * 1000;

export class UserService<Id, User> {
  private readonly fetchUser: FetchUser<Id, User>;
  private readonly cache: LRUCache<Id, User>;
  private readonly inFlight = new Map<Id, Promise<User>>();

  constructor(fetchUser: FetchUser<Id, User>, options: UserServiceOptions = {}) {
    this.fetchUser = fetchUser;
    this.cache = new LRUCache<Id, User>({
      maxSize: options.maxSize ?? DEFAULT_MAX_SIZE,
      ttlMs: options.ttlMs ?? DEFAULT_TTL_MS,
    });
  }

  async getUser(id: Id): Promise<User> {
    const cached = this.cache.get(id);
    if (cached !== undefined) {
      return cached;
    }

    const pending = this.inFlight.get(id);
    if (pending) {
      return pending;
    }

    const promise = this.fetchUser(id)
      .then((user) => {
        this.cache.set(id, user);
        return user;
      })
      .finally(() => {
        this.inFlight.delete(id);
      });

    this.inFlight.set(id, promise);
    return promise;
  }

  invalidate(id: Id): void {
    this.cache.delete(id);
  }

  /** Kicks off background loads for the given ids without waiting for them to finish. */
  prefetch(ids: Id[]): void {
    for (const id of ids) {
      void this.getUser(id).catch((error: unknown) => {
        console.error(`prefetch failed for id ${String(id)}:`, error);
      });
    }
  }
}

export interface WsClientOptions {
  url: string;
  /** Interval between heartbeat pings, in ms. Defaults to 30000. */
  heartbeatIntervalMs?: number;
  /** Base delay for reconnect backoff, in ms. Defaults to 1000. */
  reconnectBaseDelayMs?: number;
  /** Maximum reconnect backoff delay, in ms. Defaults to 30000. */
  reconnectMaxDelayMs?: number;
}

export type MessageHandler<T = unknown> = (message: T) => void;

interface TypedMessage {
  type: string;
  [key: string]: unknown;
}

function isTypedMessage(value: unknown): value is TypedMessage {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as { type?: unknown }).type === "string"
  );
}

export class WsClient {
  private readonly url: string;
  private readonly heartbeatIntervalMs: number;
  private readonly reconnectBaseDelayMs: number;
  private readonly reconnectMaxDelayMs: number;

  private socket: WebSocket | null = null;
  private handlers = new Map<string, Set<MessageHandler>>();
  private outgoingQueue: string[] = [];
  private heartbeatTimer: ReturnType<typeof setInterval> | null = null;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private reconnectAttempts = 0;
  private closedByUser = false;

  constructor(options: WsClientOptions) {
    this.url = options.url;
    this.heartbeatIntervalMs = options.heartbeatIntervalMs ?? 30000;
    this.reconnectBaseDelayMs = options.reconnectBaseDelayMs ?? 1000;
    this.reconnectMaxDelayMs = options.reconnectMaxDelayMs ?? 30000;
  }

  connect(): void {
    this.closedByUser = false;
    this.openSocket();
  }

  close(): void {
    this.closedByUser = true;
    this.clearHeartbeat();
    this.clearReconnectTimer();
    if (this.socket) {
      this.socket.close();
      this.socket = null;
    }
  }

  on<T = unknown>(type: string, handler: MessageHandler<T>): () => void {
    let set = this.handlers.get(type);
    if (!set) {
      set = new Set();
      this.handlers.set(type, set);
    }
    set.add(handler as MessageHandler);
    return () => {
      set!.delete(handler as MessageHandler);
    };
  }

  off(type: string, handler: MessageHandler): void {
    this.handlers.get(type)?.delete(handler);
  }

  send(message: unknown): void {
    const payload = JSON.stringify(message);
    if (this.socket && this.socket.readyState === WebSocket.OPEN) {
      this.socket.send(payload);
    } else {
      this.outgoingQueue.push(payload);
    }
  }

  private openSocket(): void {
    this.clearReconnectTimer();
    const socket = new WebSocket(this.url);
    this.socket = socket;

    socket.addEventListener("open", () => {
      this.reconnectAttempts = 0;
      this.flushQueue();
      this.startHeartbeat();
    });

    socket.addEventListener("message", (event: MessageEvent) => {
      this.handleMessage(event.data);
    });

    socket.addEventListener("close", () => {
      this.clearHeartbeat();
      this.socket = null;
      if (!this.closedByUser) {
        this.scheduleReconnect();
      }
    });

    socket.addEventListener("error", () => {
      socket.close();
    });
  }

  private handleMessage(data: unknown): void {
    if (typeof data !== "string") {
      return;
    }
    let parsed: unknown;
    try {
      parsed = JSON.parse(data);
    } catch {
      return;
    }
    if (!isTypedMessage(parsed)) {
      return;
    }
    const set = this.handlers.get(parsed.type);
    if (!set) {
      return;
    }
    for (const handler of set) {
      handler(parsed);
    }
  }

  private flushQueue(): void {
    if (!this.socket || this.socket.readyState !== WebSocket.OPEN) {
      return;
    }
    const pending = this.outgoingQueue;
    this.outgoingQueue = [];
    for (const payload of pending) {
      this.socket.send(payload);
    }
  }

  private startHeartbeat(): void {
    this.clearHeartbeat();
    this.heartbeatTimer = setInterval(() => {
      if (this.socket && this.socket.readyState === WebSocket.OPEN) {
        this.socket.send(JSON.stringify({ type: "heartbeat" }));
      }
    }, this.heartbeatIntervalMs);
  }

  private clearHeartbeat(): void {
    if (this.heartbeatTimer !== null) {
      clearInterval(this.heartbeatTimer);
      this.heartbeatTimer = null;
    }
  }

  private scheduleReconnect(): void {
    this.clearReconnectTimer();
    const delay = Math.min(
      this.reconnectBaseDelayMs * 2 ** this.reconnectAttempts,
      this.reconnectMaxDelayMs,
    );
    this.reconnectAttempts += 1;
    this.reconnectTimer = setTimeout(() => {
      this.openSocket();
    }, delay);
  }

  private clearReconnectTimer(): void {
    if (this.reconnectTimer !== null) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
  }
}

