    this.closedByUser = false;
    this.openSocket();
  }

  close(): void {
    this.closedByUser = true;
    this.clearHeartbeat();
    this.clearReconnectTimer();
    this.ws?.close();
    this.ws = null;
  }

  on<T = unknown>(type: string, handler: Handler<T>): () => void {
    let set = this.handlers.get(type);
    if (!set) {
      set = new Set();
      this.handlers.set(type, set);
    }
    set.add(handler as Handler);
    return () => {
      set?.delete(handler as Handler);
    };
  }

  off(type: string, handler: Handler): void {
    this.handlers.get(type)?.delete(handler);
  }

  send(message: unknown): void {
    const payload = JSON.stringify(message);
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(payload);
    } else {
      this.outgoingQueue.push(payload);
    }
  }

  private openSocket(): void {
    const ws = new WebSocket(this.url, this.protocols);
    this.ws = ws;

    ws.addEventListener('open', () => {
      this.reconnectAttempts = 0;
      this.flushQueue();
      this.startHeartbeat();
    });

    ws.addEventListener('message', (event: MessageEvent) => {
      this.handleMessage(event.data);
    });

    ws.addEventListener('close', () => {
      this.clearHeartbeat();
      if (!this.closedByUser) {
        this.scheduleReconnect();
      }
    });

    ws.addEventListener('error', () => {
      ws.close();
    });
  }

  private handleMessage(data: unknown): void {
    if (typeof data !== 'string') {
      return;
    }
    let parsed: TypedMessage;
    try {
      parsed = JSON.parse(data) as TypedMessage;
    } catch (parseError) {
      console.warn('WsClient: received malformed JSON message', parseError);
      return;
    }
    if (!parsed || typeof parsed.type !== 'string') {
      return;
    }
    const handlerSet = this.handlers.get(parsed.type);
    if (!handlerSet) {
      return;
    }
    for (const handler of handlerSet) {
      handler(parsed);
    }
  }

  private flushQueue(): void {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) {
      return;
    }
    const queue = this.outgoingQueue;
    this.outgoingQueue = [];
    for (const payload of queue) {
      this.ws.send(payload);
    }
  }

  private startHeartbeat(): void {
    this.clearHeartbeat();
    this.heartbeatTimer = setInterval(() => {
      this.send(this.heartbeatMessage);
    }, this.heartbeatIntervalMs);
  }

  private clearHeartbeat(): void {
    if (this.heartbeatTimer !== null) {
      clearInterval(this.heartbeatTimer);
      this.heartbeatTimer = null;
    }
  }

  private scheduleReconnect(): void {
    this.clearReconnectTimer();
    const delay = Math.min(
      this.minReconnectDelayMs * 2 ** this.reconnectAttempts,
      this.maxReconnectDelayMs,
    );
    this.reconnectAttempts += 1;
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null;
      this.openSocket();
    }, delay);
  }

  private clearReconnectTimer(): void {
    if (this.reconnectTimer !== null) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
  }
}

const RETAIL_SALES_TAX_RATE = 0.0825;
const REVIEW_THRESHOLD = 10_000;

export interface Transaction {
  date: string;
  description: string;
  category: string;
  amount: number;
}

export interface ProcessedTransaction extends Transaction {
  /** Amount actually charged, including sales tax for Retail transactions. */
  finalAmount: number;
  flagged: boolean;
}

export interface MonthlyReport {
  /** monthKey ("YYYY-MM") -> category -> total finalAmount */
  monthlyTotals: Map<string, Map<string, number>>;
  flagged: ProcessedTransaction[];
}

function parseCsvLine(line: string): string[] {
  const fields: string[] = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (inQuotes) {
      if (char === '"') {
        if (line[i + 1] === '"') {
          current += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        current += char;
      }
    } else if (char === '"') {
      inQuotes = true;
    } else if (char === ",") {
      fields.push(current);
      current = "";
    } else {
      current += char;
    }
  }

  fields.push(current);
  return fields;
}

function parseAmount(raw: string, lineNumber: number): number {
  const cleaned = raw.trim().replace(/^\$/, "").replace(/,/g, "");
  const amount = Number(cleaned);
  if (!Number.isFinite(amount)) {
    throw new Error(`Invalid amount "${raw}" on line ${lineNumber}`);
  }
  return amount;
}

function monthKey(date: string, lineNumber: number): string {
  const match = /^(\d{4}-\d{2})-\d{2}$/.exec(date.trim());
  if (!match) {
    throw new Error(`Invalid date "${date}" on line ${lineNumber}`);
  }
  return match[1];
}

export function parseTransactionsCsv(csv: string): Transaction[] {
  const lines = csv.split(/\r\n|\r|\n/).filter((line) => line.trim().length > 0);
  if (lines.length === 0) {
    return [];
  }

  const firstFields = parseCsvLine(lines[0]);
  const hasHeader = !Number.isFinite(Number(firstFields[3]?.trim().replace(/^\$/, "").replace(/,/g, "")));
  const dataLines = hasHeader ? lines.slice(1) : lines;
  const lineOffset = hasHeader ? 2 : 1;

  return dataLines.map((line, index) => {
    const lineNumber = index + lineOffset;
    const fields = parseCsvLine(line);
    if (fields.length !== 4) {
      throw new Error(`Expected 4 fields but found ${fields.length} on line ${lineNumber}`);
    }
    const [date, description, category, rawAmount] = fields;
    return {
      date: date.trim(),
      description: description.trim(),
      category: category.trim(),
      amount: parseAmount(rawAmount, lineNumber),
    };
  });
}

function processTransaction(transaction: Transaction, lineNumber: number): ProcessedTransaction {
  const isRetail = transaction.category.toLowerCase() === "retail";
  const finalAmount = isRetail ? transaction.amount * (1 + RETAIL_SALES_TAX_RATE) : transaction.amount;
  void monthKey(transaction.date, lineNumber);
  return {
    ...transaction,
    finalAmount,
    flagged: finalAmount > REVIEW_THRESHOLD,
  };
}

export function buildMonthlyReport(transactions: Transaction[]): MonthlyReport {
  const monthlyTotals = new Map<string, Map<string, number>>();
  const flagged: ProcessedTransaction[] = [];

  transactions.forEach((transaction, index) => {
    const lineNumber = index + 1;
    const processed = processTransaction(transaction, lineNumber);
    const month = monthKey(transaction.date, lineNumber);

    let categoryTotals = monthlyTotals.get(month);
    if (!categoryTotals) {
      categoryTotals = new Map<string, number>();
      monthlyTotals.set(month, categoryTotals);
    }
    categoryTotals.set(
      processed.category,
      (categoryTotals.get(processed.category) ?? 0) + processed.finalAmount,
    );

    if (processed.flagged) {
      flagged.push(processed);
    }
  });

  return { monthlyTotals, flagged };
}

export function generateReport(csv: string): MonthlyReport {
  return buildMonthlyReport(parseTransactionsCsv(csv));
}

function formatCurrency(amount: number): string {
  return amount.toLocaleString("en-US", {
    style: "currency",
    currency: "USD",
  });
}

export function formatReportAsTable(report: MonthlyReport): string {
  const lines: string[] = [];
  const months = [...report.monthlyTotals.keys()].sort();

  for (const month of months) {
    const categoryTotals = report.monthlyTotals.get(month);
    if (!categoryTotals) {
      continue;
    }
    const categories = [...categoryTotals.keys()].sort();
    let monthTotal = 0;

    lines.push(month);
    lines.push("-".repeat(month.length));
    for (const category of categories) {
      const total = categoryTotals.get(category) ?? 0;
      monthTotal += total;
      lines.push(`  ${category.padEnd(20)} ${formatCurrency(total).padStart(15)}`);
    }
    lines.push(`  ${"Total".padEnd(20)} ${formatCurrency(monthTotal).padStart(15)}`);
    lines.push("");
  }

  if (report.flagged.length > 0) {
    lines.push("Flagged for review (over $10,000):");
    for (const transaction of report.flagged) {
      lines.push(
        `  ${transaction.date}  ${transaction.category.padEnd(15)} ${formatCurrency(transaction.finalAmount).padStart(15)}  ${transaction.description}`,
      );
    }
    lines.push("");
  }

  return lines.join("\n").trimEnd();
}

import Foundation

public struct CurrentWeather: Codable, Equatable {
    public let temperatureCelsius: Double
    public let condition: String
    public let windSpeedKph: Double
}

public enum WeatherClientError: Error, Equatable {
    case missingAPIKey
    case invalidURL
    case requestFailed(statusCode: Int)
    case decodingFailed
    case transportError(String)
}

public final class WeatherClient {
    private let session: URLSession
    private let baseURL: URL
    private let apiKeyProvider: () -> String?

    public init(
        session: URLSession = .shared,
        baseURL: URL = URL(string: "https://api.weatherapi.com/v1/current.json")!,
        apiKeyProvider: @escaping () -> String? = { ProcessInfo.processInfo.environment["WEATHER_API_KEY"] }
    ) {
        self.session = session
        self.baseURL = baseURL
        self.apiKeyProvider = apiKeyProvider
    }

    public func currentWeather(forCity city: String) async throws -> CurrentWeather {
        guard let apiKey = apiKeyProvider(), !apiKey.isEmpty else {
            throw WeatherClientError.missingAPIKey
        }

        guard var components = URLComponents(url: baseURL, resolvingAgainstBaseURL: false) else {
            throw WeatherClientError.invalidURL
        }
        components.queryItems = [
            URLQueryItem(name: "key", value: apiKey),
            URLQueryItem(name: "q", value: city),
        ]
        guard let url = components.url else {
            throw WeatherClientError.invalidURL
        }

        let data: Data
        let response: URLResponse
        do {
            (data, response) = try await session.data(from: url)
        } catch {
            throw WeatherClientError.transportError(error.localizedDescription)
        }

        guard let httpResponse = response as? HTTPURLResponse else {
            throw WeatherClientError.transportError("No HTTP response received")
        }
        guard (200...299).contains(httpResponse.statusCode) else {
            throw WeatherClientError.requestFailed(statusCode: httpResponse.statusCode)
        }

        do {
            let decoded = try JSONDecoder().decode(WeatherAPIResponse.self, from: data)
            return CurrentWeather(
                temperatureCelsius: decoded.current.tempC,
                condition: decoded.current.condition.text,
                windSpeedKph: decoded.current.windKph
            )
        } catch {
            throw WeatherClientError.decodingFailed
        }
    }
}

private struct WeatherAPIResponse: Codable {
    let current: Current

    struct Current: Codable {
        let tempC: Double
        let windKph: Double
        let condition: Condition

        enum CodingKeys: String, CodingKey {
            case tempC = "temp_c"
            case windKph = "wind_kph"
            case condition
        }
    }

    struct Condition: Codable {
        let text: String
    }
}

