import Foundation

/// Current weather conditions for a city.
public struct CurrentWeather: Codable, Equatable {
    /// Temperature in degrees Celsius.
    public let temperatureCelsius: Double
    /// Short human-readable condition, e.g. "Clear", "Rain".
    public let condition: String
    /// Wind speed in meters per second.
    public let windSpeed: Double
}

public enum WeatherClientError: Error, LocalizedError {
    case missingAPIKey
    case invalidURL
    case invalidResponse
    case httpError(statusCode: Int)
    case decodingFailed(underlying: Error)
    case requestFailed(underlying: Error)

    public var errorDescription: String? {
        switch self {
        case .missingAPIKey:
            return "The WEATHER_API_KEY environment variable is not set."
        case .invalidURL:
            return "Could not construct a valid URL for the weather request."
        case .invalidResponse:
            return "The weather service returned an unexpected response."
        case .httpError(let statusCode):
            return "The weather service returned HTTP status \(statusCode)."
        case .decodingFailed(let underlying):
            return "Failed to decode the weather response: \(underlying.localizedDescription)"
        case .requestFailed(let underlying):
            return "The weather request failed: \(underlying.localizedDescription)"
        }
    }
}

/// Fetches current weather conditions from a JSON HTTP weather API (OpenWeatherMap-compatible).
public struct WeatherClient {
    private let baseURL: URL
    private let apiKey: String
    private let urlSession: URLSession

    private static let defaultBaseURLString = "https://api.openweathermap.org/data/2.5/weather"

    /// - Parameters:
    ///   - baseURL: Base endpoint for the weather API's "current weather" resource. Defaults to the OpenWeatherMap current-weather endpoint.
    ///   - apiKey: API key used to authenticate requests. Defaults to the `WEATHER_API_KEY` environment variable.
    ///   - urlSession: Session used to perform requests. Defaults to `.shared`.
    public init(
        baseURL: URL? = nil,
        apiKey: String? = ProcessInfo.processInfo.environment["WEATHER_API_KEY"],
        urlSession: URLSession = .shared
    ) throws {
        guard let apiKey, !apiKey.isEmpty else {
            throw WeatherClientError.missingAPIKey
        }
        guard let resolvedBaseURL = baseURL ?? URL(string: Self.defaultBaseURLString) else {
            throw WeatherClientError.invalidURL
        }
        self.baseURL = resolvedBaseURL
        self.apiKey = apiKey
        self.urlSession = urlSession
    }

    /// Fetches the current weather for the given city name.
    public func currentWeather(forCity city: String) async throws -> CurrentWeather {
        guard var components = URLComponents(url: baseURL, resolvingAgainstBaseURL: false) else {
            throw WeatherClientError.invalidURL
        }
        components.queryItems = [
            URLQueryItem(name: "q", value: city),
            URLQueryItem(name: "units", value: "metric"),
            URLQueryItem(name: "appid", value: apiKey),
        ]
        guard let url = components.url else {
            throw WeatherClientError.invalidURL
        }

        let data: Data
        let response: URLResponse
        do {
            (data, response) = try await urlSession.data(from: url)
        } catch {
            throw WeatherClientError.requestFailed(underlying: error)
        }

        guard let httpResponse = response as? HTTPURLResponse else {
            throw WeatherClientError.invalidResponse
        }
        guard (200..<300).contains(httpResponse.statusCode) else {
            throw WeatherClientError.httpError(statusCode: httpResponse.statusCode)
        }

        do {
            let decoded = try JSONDecoder().decode(WeatherAPIResponse.self, from: data)
            return decoded.currentWeather
        } catch {
            throw WeatherClientError.decodingFailed(underlying: error)
        }
    }
}

/// Raw response shape returned by the weather API.
private struct WeatherAPIResponse: Decodable {
    struct Weather: Decodable {
        let main: String
    }
    struct Main: Decodable {
        let temp: Double
    }
    struct Wind: Decodable {
        let speed: Double
    }

    let weather: [Weather]
    let main: Main
    let wind: Wind

    var currentWeather: CurrentWeather {
        CurrentWeather(
            temperatureCelsius: main.temp,
            condition: weather.first?.main ?? "Unknown",
