/// Current weather conditions for a city.
public struct CurrentWeather: Codable, Equatable {
    public let temperatureCelsius: Double
    public let condition: String
    public let windSpeedKph: Double
}

public enum WeatherClientError: Error, Equatable {
    case missingAPIKey
    case invalidCityName
    case invalidURL
    case invalidResponse
    case httpError(statusCode: Int)
    case decodingFailed
    case requestFailed(String)
}

/// Fetches current weather conditions from the WeatherAPI.com JSON HTTP API.
public struct WeatherClient {
    private let baseURL: URL
    private let apiKey: String
    private let session: URLSession

    private static let defaultBaseURLString = "https://api.weatherapi.com/v1/current.json"

    /// Creates a client using the API key from the `WEATHER_API_KEY` environment variable.
    public init(
        session: URLSession = .shared,
        baseURL: URL? = nil,
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) throws {
        guard let apiKey = environment["WEATHER_API_KEY"], !apiKey.isEmpty else {
            throw WeatherClientError.missingAPIKey
        }
        guard let resolvedBaseURL = baseURL ?? URL(string: Self.defaultBaseURLString) else {
            throw WeatherClientError.invalidURL
        }
        self.apiKey = apiKey
        self.baseURL = resolvedBaseURL
        self.session = session
    }

    /// Fetches the current weather for the given city.
    public func currentWeather(forCity city: String) async throws -> CurrentWeather {
        guard !city.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            throw WeatherClientError.invalidCityName
        }

        guard var components = URLComponents(url: baseURL, resolvingAgainstBaseURL: false) else {
            throw WeatherClientError.invalidURL
        }
        components.queryItems = [
            URLQueryItem(name: "key", value: apiKey),
            URLQueryItem(name: "q", value: city),
        ]
        guard let url = components.url else {
            throw WeatherClientError.invalidURL
        }

        let data: Data
        let response: URLResponse
        do {
            (data, response) = try await session.data(from: url)
        } catch {
            throw WeatherClientError.requestFailed(error.localizedDescription)
        }

        guard let httpResponse = response as? HTTPURLResponse else {
            throw WeatherClientError.invalidResponse
        }
        guard (200..<300).contains(httpResponse.statusCode) else {
            throw WeatherClientError.httpError(statusCode: httpResponse.statusCode)
        }

        do {
            let decoded = try JSONDecoder().decode(WeatherAPIResponse.self, from: data)
            return CurrentWeather(
                temperatureCelsius: decoded.current.tempC,
                condition: decoded.current.condition.text,
                windSpeedKph: decoded.current.windKph
            )
        } catch {
            throw WeatherClientError.decodingFailed
        }
    }
}

/// Raw response shape for WeatherAPI.com's `/v1/current.json` endpoint.
private struct WeatherAPIResponse: Codable {
    let current: Current

    struct Current: Codable {
        let tempC: Double
        let condition: Condition
        let windKph: Double

        enum CodingKeys: String, CodingKey {
            case tempC = "temp_c"
            case condition
            case windKph = "wind_kph"
        }
    }

    struct Condition: Codable {
        let text: String
    }
}

