@MainActor
final class UserListViewModel: ObservableObject {
    @Published var users: [User] = []
    @Published var isLoading: Bool = false
    @Published var errorMessage: String?
    @Published var searchText: String = ""

    var filteredUsers: [User] {
        guard !searchText.isEmpty else { return users }
        return users.filter {
            $0.name.localizedCaseInsensitiveContains(searchText) ||
            $0.email.localizedCaseInsensitiveContains(searchText)
        }
    }

    private let endpoint: URL
    private let session: URLSession
    private var currentTask: URLSessionDataTask?

    init(endpoint: URL, session: URLSession = .shared) {
        self.endpoint = endpoint
        self.session = session
    }

    func load() {
        startRequest(onComplete: nil)
    }

    func refresh() async {
        await withCheckedContinuation { continuation in
            startRequest(onComplete: { continuation.resume() })
        }
    }

    private func startRequest(onComplete: (() -> Void)?) {
        currentTask?.cancel()
        isLoading = true
        errorMessage = nil

        let task = session.dataTask(with: endpoint) { [weak self] data, response, error in
            DispatchQueue.main.async {
                self?.handleResponse(data: data, response: response, error: error)
                onComplete?()
            }
        }
        currentTask = task
        task.resume()
    }

    private func handleResponse(data: Data?, response: URLResponse?, error: Error?) {
        isLoading = false

        if let error {
            if (error as NSError).code == NSURLErrorCancelled { return }
            errorMessage = error.localizedDescription
            return
        }

        guard let http = response as? HTTPURLResponse, (200..<300).contains(http.statusCode) else {
            errorMessage = "Unexpected server response."
            return
        }

        guard let data else {
            errorMessage = "No data received."
            return
        }

        do {
            users = try JSONDecoder().decode([User].self, from: data)
        } catch {
            errorMessage = "Failed to parse users: \(error.localizedDescription)"
        }
    }
}

