/// A generic on-disk cache that persists `Codable` values as JSON files under the
/// system caches directory, with per-entry expiration and size-bounded eviction.
public final class DiskCache<Value: Codable> {
    private struct Entry: Codable {
        let value: Value
        let createdAt: Date
        let expiresAt: Date?
    }

    private let directoryURL: URL
    private let fileManager: FileManager
    private let maxSize: UInt64?
    private let defaultExpiration: TimeInterval?
    private let queue = DispatchQueue(label: "DiskCache", attributes: .concurrent)
    private let encoder = JSONEncoder()
    private let decoder = JSONDecoder()

    /// - Parameters:
    ///   - name: Subdirectory of the caches directory used to store this cache's files.
    ///   - maxSize: Maximum total size in bytes of all cached files. When exceeded, the
    ///     oldest entries are evicted first until the cache fits within the limit.
    ///   - defaultExpiration: Default time-to-live applied to entries that don't specify
    ///     their own expiration in `set(_:forKey:expiration:)`.
    public init(
        name: String,
        maxSize: UInt64? = nil,
        defaultExpiration: TimeInterval? = nil,
        fileManager: FileManager = .default
    ) throws {
        self.fileManager = fileManager
        self.maxSize = maxSize
        self.defaultExpiration = defaultExpiration
        let cachesURL = try fileManager.url(
            for: .cachesDirectory, in: .userDomainMask, appropriateFor: nil, create: true
        )
        self.directoryURL = cachesURL.appendingPathComponent(name, isDirectory: true)
        try fileManager.createDirectory(at: directoryURL, withIntermediateDirectories: true)
    }

    public func set(_ value: Value, forKey key: String, expiration: TimeInterval? = nil) throws {
        let ttl = expiration ?? defaultExpiration
        let entry = Entry(
            value: value,
            createdAt: Date(),
            expiresAt: ttl.map { Date().addingTimeInterval($0) }
        )
        let data = try encoder.encode(entry)
        try queue.sync(flags: .barrier) {
            try data.write(to: fileURL(forKey: key), options: .atomic)
            evictIfNeeded()
        }
    }

    public func value(forKey key: String) -> Value? {
        queue.sync {
            let url = fileURL(forKey: key)
            guard let data = try? Data(contentsOf: url),
                let entry = try? decoder.decode(Entry.self, from: data)
            else {
                return nil
            }
            if let expiresAt = entry.expiresAt, expiresAt <= Date() {
                try? fileManager.removeItem(at: url)
                return nil
            }
            return entry.value
        }
    }

    public func removeValue(forKey key: String) {
        queue.sync(flags: .barrier) {
            try? fileManager.removeItem(at: fileURL(forKey: key))
        }
    }

    public func removeAll() {
        queue.sync(flags: .barrier) {
            guard let urls = try? fileManager.contentsOfDirectory(at: directoryURL, includingPropertiesForKeys: nil)
            else { return }
            for url in urls {
                try? fileManager.removeItem(at: url)
            }
        }
    }

    private func fileURL(forKey key: String) -> URL {
        directoryURL.appendingPathComponent(Self.hash(key)).appendingPathExtension("json")
    }

    private static func hash(_ key: String) -> String {
        let digest = SHA256.hash(data: Data(key.utf8))
        return digest.map { String(format: "%02x", $0) }.joined()
    }

    /// Must be called while holding a barrier on `queue`.
    private func evictIfNeeded() {
        guard let maxSize else { return }
        guard
            let urls = try? fileManager.contentsOfDirectory(
                at: directoryURL,
                includingPropertiesForKeys: [.fileSizeKey, .contentModificationDateKey]
            )
        else { return }

        var files: [(url: URL, size: UInt64, modifiedAt: Date)] = []
        var totalSize: UInt64 = 0
        for url in urls {
            let values = try? url.resourceValues(forKeys: [.fileSizeKey, .contentModificationDateKey])
            let size = UInt64(values?.fileSize ?? 0)
            let modifiedAt = values?.contentModificationDate ?? .distantPast
            files.append((url, size, modifiedAt))
            totalSize += size
        }

        guard totalSize > maxSize else { return }
        for file in files.sorted(by: { $0.modifiedAt < $1.modifiedAt }) {
            guard totalSize > maxSize else { break }
            try? fileManager.removeItem(at: file.url)
            totalSize -= file.size
        }
    }
}

