/// A thread-safe disk cache that persists `Codable` values as JSON files under the
/// system caches directory, with per-entry expiration and oldest-first eviction
/// once a total size budget is exceeded.
public final class DiskCache<Value: Codable> {
    private struct Entry: Codable {
        let value: Value
        let expiresAt: Date?
    }

    private let directoryURL: URL
    private let maxTotalSize: Int?
    private let fileManager = FileManager.default
    private let encoder: JSONEncoder
    private let decoder: JSONDecoder
    private let queue = DispatchQueue(label: "DiskCache", attributes: .concurrent)

    /// - Parameters:
    ///   - name: Subdirectory name under the caches directory used to namespace this cache.
    ///   - maxTotalSize: Maximum total size in bytes of all cached files. When exceeded,
    ///     the oldest entries (by modification date) are evicted until the cache fits.
    ///     Pass `nil` to disable size-based eviction.
    public init(
        name: String,
        maxTotalSize: Int? = nil,
        encoder: JSONEncoder = JSONEncoder(),
        decoder: JSONDecoder = JSONDecoder()
    ) {
        let cachesURL = fileManager.urls(for: .cachesDirectory, in: .userDomainMask).first
            ?? fileManager.temporaryDirectory
        self.directoryURL = cachesURL.appendingPathComponent(name, isDirectory: true)
        self.maxTotalSize = maxTotalSize
        self.encoder = encoder
        self.decoder = decoder
        try? fileManager.createDirectory(at: directoryURL, withIntermediateDirectories: true)
    }

    /// Stores `value` for `key`, optionally expiring after `ttl` seconds.
    public func setValue(_ value: Value, forKey key: String, ttl: TimeInterval? = nil) {
        queue.sync(flags: .barrier) {
            let expiresAt = ttl.map { Date().addingTimeInterval($0) }
            let entry = Entry(value: value, expiresAt: expiresAt)
            guard let data = try? encoder.encode(entry) else { return }
            try? data.write(to: fileURL(forKey: key), options: .atomic)
            enforceMaxSizeLocked()
        }
    }

    /// Returns the cached value for `key`, or `nil` if missing or expired.
    /// Expired entries are removed from disk as a side effect.
    public func value(forKey key: String) -> Value? {
        queue.sync {
            let url = fileURL(forKey: key)
            guard let data = try? Data(contentsOf: url),
                  let entry = try? decoder.decode(Entry.self, from: data) else {
                return nil
            }
            if let expiresAt = entry.expiresAt, expiresAt <= Date() {
                queue.async(flags: .barrier) { [fileManager] in
                    try? fileManager.removeItem(at: url)
                }
                return nil
            }
            return entry.value
        }
    }

    public func removeValue(forKey key: String) {
        queue.sync(flags: .barrier) {
            try? self.fileManager.removeItem(at: self.fileURL(forKey: key))
        }
    }

    public func removeAll() {
        queue.sync(flags: .barrier) {
            guard let contents = try? self.fileManager.contentsOfDirectory(
                at: self.directoryURL,
                includingPropertiesForKeys: nil
            ) else { return }
            for url in contents {
                try? self.fileManager.removeItem(at: url)
            }
        }
    }

    private func fileURL(forKey key: String) -> URL {
        directoryURL
            .appendingPathComponent(Self.fileName(forKey: key))
            .appendingPathExtension("json")
    }

    /// Maps arbitrary cache keys to a stable, filesystem-safe file name via FNV-1a.
    private static func fileName(forKey key: String) -> String {
        var hash: UInt64 = 14_695_981_039_346_656_037
        for byte in key.utf8 {
            hash ^= UInt64(byte)
            hash = hash &* 1_099_511_628_211
        }
        return String(format: "%016llx", hash)
    }

    /// Must be called while holding the barrier. Evicts the oldest entries
    /// (by modification date) until the directory's total size is within budget.
    private func enforceMaxSizeLocked() {
        guard let maxTotalSize else { return }
        guard let contents = try? fileManager.contentsOfDirectory(
            at: directoryURL,
            includingPropertiesForKeys: [.contentModificationDateKey, .fileSizeKey]
        ) else { return }

        var entries: [(url: URL, modifiedAt: Date, size: Int)] = contents.compactMap { url in
            guard let values = try? url.resourceValues(forKeys: [.contentModificationDateKey, .fileSizeKey]),
                  let modifiedAt = values.contentModificationDate,
                  let size = values.fileSize else {
                return nil
            }
            return (url, modifiedAt, size)
        }

        var totalSize = entries.reduce(0) { $0 + $1.size }
        guard totalSize > maxTotalSize else { return }

        entries.sort { $0.modifiedAt < $1.modifiedAt }
        for entry in entries {
            guard totalSize > maxTotalSize else { break }
            try? fileManager.removeItem(at: entry.url)
            totalSize -= entry.size
        }
    }
}

import Foundation

/// A generic on-disk cache that stores `Codable` values as JSON files in the
/// user's caches directory, with per-entry expiration and a total size limit
/// enforced via oldest-first eviction.
public final class DiskCache<Value: Codable> {
    private let directory: URL
    private let maxTotalSize: Int
    private let defaultExpiration: TimeInterval?
    private let fileManager: FileManager
    private let queue = DispatchQueue(label: "com.app.diskcache", attributes: .concurrent)

    private struct Entry: Codable {
        let value: Value
        let expiresAt: Date?
    }

    /// - Parameters:
    ///   - name: A subdirectory name (under the caches directory) unique to this cache.
    ///   - maxTotalSize: Maximum combined size in bytes of all cached files before eviction kicks in.
    ///   - defaultExpiration: Fallback time-to-live applied to entries that don't specify their own.
    public init(
        name: String,
        maxTotalSize: Int = 50 * 1024 * 1024,
        defaultExpiration: TimeInterval? = nil,
        fileManager: FileManager = .default
    ) throws {
        self.fileManager = fileManager
        self.maxTotalSize = maxTotalSize
        self.defaultExpiration = defaultExpiration
        let cachesURL = try fileManager.url(
            for: .cachesDirectory, in: .userDomainMask, appropriateFor: nil, create: true
        )
        self.directory = cachesURL.appendingPathComponent(name, isDirectory: true)
        try fileManager.createDirectory(at: directory, withIntermediateDirectories: true)
    }

    /// Stores `value` for `key`, replacing any existing entry.
    /// - Parameter expiration: Time-to-live for this entry; falls back to `defaultExpiration`, or never expires if both are nil.
    public func setValue(_ value: Value, forKey key: String, expiration: TimeInterval? = nil) throws {
        try queue.sync(flags: .barrier) {
            let ttl = expiration ?? defaultExpiration
            let expiresAt = ttl.map { Date().addingTimeInterval($0) }
            let entry = Entry(value: value, expiresAt: expiresAt)
            let data = try JSONEncoder().encode(entry)
            try data.write(to: fileURL(forKey: key), options: .atomic)
            enforceMaxSize()
        }
    }

    /// Returns the cached value for `key`, or nil if missing, unreadable, or expired.
    /// Expired entries are removed from disk as a side effect.
    public func value(forKey key: String) -> Value? {
        queue.sync {
            let url = fileURL(forKey: key)
            guard let data = try? Data(contentsOf: url),
                  let entry = try? JSONDecoder().decode(Entry.self, from: data)
            else {
                return nil
            }
            if let expiresAt = entry.expiresAt, expiresAt <= Date() {
                try? fileManager.removeItem(at: url)
                return nil
            }
            return entry.value
        }
    }

    public func removeValue(forKey key: String) {
        queue.sync(flags: .barrier) {
            try? fileManager.removeItem(at: fileURL(forKey: key))
        }
    }

    public func removeAll() {
        queue.sync(flags: .barrier) {
            guard let contents = try? fileManager.contentsOfDirectory(at: directory, includingPropertiesForKeys: nil)
            else { return }
            for url in contents {
                try? fileManager.removeItem(at: url)
            }
        }
    }

    private func fileURL(forKey key: String) -> URL {
        let safeCharacters = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "-_"))
        let filename = key.addingPercentEncoding(withAllowedCharacters: safeCharacters) ?? key
        return directory.appendingPathComponent(filename).appendingPathExtension("json")
    }

    /// Must be called while holding the barrier queue.
    private func enforceMaxSize() {
        guard let contents = try? fileManager.contentsOfDirectory(
            at: directory, includingPropertiesForKeys: [.contentModificationDateKey, .fileSizeKey]
        ) else {
            return
        }

        var files: [(url: URL, modifiedAt: Date, size: Int)] = []
        var totalSize = 0
        for url in contents {
            let values = try? url.resourceValues(forKeys: [.contentModificationDateKey, .fileSizeKey])
            let size = values?.fileSize ?? 0
            let modifiedAt = values?.contentModificationDate ?? Date.distantPast
            totalSize += size
            files.append((url, modifiedAt, size))
        }

        guard totalSize > maxTotalSize else { return }

        for file in files.sorted(by: { $0.modifiedAt < $1.modifiedAt }) {
            guard totalSize > maxTotalSize else { break }
            try? fileManager.removeItem(at: file.url)
            totalSize -= file.size
        }
    }
}

import Foundation

/// Application configuration, loaded from a JSON file with defaults and
/// environment variable overrides (prefixed `APP_`).
public struct AppConfig: Equatable {
    public var baseURL: URL
    public var timeout: Double
    public var maxConnections: Int

    public static let defaultBaseURL = URL(string: "https://api.example.com")!
    public static let defaultTimeout: Double = 30
    public static let defaultMaxConnections: Int = 8

    public static let timeoutRange: ClosedRange<Double> = 1...120
    public static let maxConnectionsRange: ClosedRange<Int> = 1...64

    public init(
        baseURL: URL = AppConfig.defaultBaseURL,
        timeout: Double = AppConfig.defaultTimeout,
        maxConnections: Int = AppConfig.defaultMaxConnections
    ) {
        self.baseURL = baseURL
        self.timeout = timeout
        self.maxConnections = maxConnections
    }
}

public enum AppConfigError: Error, CustomStringConvertible {
    case fileNotReadable(path: String, underlying: Error)
    case invalidJSON(underlying: Error)
    case invalidBaseURL(String)
    case timeoutOutOfRange(Double)
    case maxConnectionsOutOfRange(Int)
    case invalidEnvironmentValue(key: String, value: String)

    public var description: String {
        switch self {
        case .fileNotReadable(let path, let underlying):
            return "Could not read config file at \(path): \(underlying)"
        case .invalidJSON(let underlying):
            return "Config file is not valid JSON: \(underlying)"
        case .invalidBaseURL(let value):
            return "baseURL must be a valid https URL, got: \(value)"
        case .timeoutOutOfRange(let value):
            return "timeout must be between \(AppConfig.timeoutRange.lowerBound) and \(AppConfig.timeoutRange.upperBound) seconds, got: \(value)"
        case .maxConnectionsOutOfRange(let value):
            return "maxConnections must be between \(AppConfig.maxConnectionsRange.lowerBound) and \(AppConfig.maxConnectionsRange.upperBound), got: \(value)"
        case .invalidEnvironmentValue(let key, let value):
            return "Environment variable \(key) has invalid value: \(value)"
        }
    }
}

extension AppConfig {
    /// Fields as they appear in the JSON config file; all optional so that
    /// missing fields fall back to defaults.
    private struct FileFields: Decodable {
        var baseURL: String?
        var timeout: Double?
        var maxConnections: Int?
    }

    /// Loads configuration from a JSON file at `path`, applying defaults for
    /// missing fields, then overriding with any `APP_`-prefixed environment
    /// variables in `environment`, and finally validating the result.
    public static func load(
        fromFile path: String,
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) throws -> AppConfig {
        let data: Data
        do {
            data = try Data(contentsOf: URL(fileURLWithPath: path))
        } catch {
            throw AppConfigError.fileNotReadable(path: path, underlying: error)
        }

        let fields: FileFields
        do {
            fields = try JSONDecoder().decode(FileFields.self, from: data)
        } catch {
            throw AppConfigError.invalidJSON(underlying: error)
        }

        var config = AppConfig()
        if let baseURL = fields.baseURL {
            config.baseURL = try parseBaseURL(baseURL)
        }
        if let timeout = fields.timeout {
            config.timeout = timeout
        }
        if let maxConnections = fields.maxConnections {
            config.maxConnections = maxConnections
        }

        try config.applyEnvironmentOverrides(environment)
        try config.validate()
        return config
    }

    private mutating func applyEnvironmentOverrides(_ environment: [String: String]) throws {
        if let value = environment["APP_BASE_URL"] {
            baseURL = try AppConfig.parseBaseURL(value)
        }
        if let value = environment["APP_TIMEOUT"] {
            guard let parsed = Double(value) else {
                throw AppConfigError.invalidEnvironmentValue(key: "APP_TIMEOUT", value: value)
            }
            timeout = parsed
        }
        if let value = environment["APP_MAX_CONNECTIONS"] {
            guard let parsed = Int(value) else {
                throw AppConfigError.invalidEnvironmentValue(key: "APP_MAX_CONNECTIONS", value: value)
            }
            maxConnections = parsed
        }
    }

    private static func parseBaseURL(_ value: String) throws -> URL {
        guard let url = URL(string: value), url.scheme?.lowercased() == "https", url.host != nil else {
            throw AppConfigError.invalidBaseURL(value)
        }
        return url
    }

    private func validate() throws {
        guard baseURL.scheme?.lowercased() == "https", baseURL.host != nil else {
            throw AppConfigError.invalidBaseURL(baseURL.absoluteString)
        }
        guard AppConfig.timeoutRange.contains(timeout) else {
            throw AppConfigError.timeoutOutOfRange(timeout)
        }
        guard AppConfig.maxConnectionsRange.contains(maxConnections) else {
            throw AppConfigError.maxConnectionsOutOfRange(maxConnections)
        }
    }
}

import Foundation

enum AppConfigError: Error, CustomStringConvertible {
    case invalidJSON(String)
    case invalidEnvironmentValue(String)
    case invalidTimeout(Double)
    case invalidMaxConnections(Int)
    case invalidBaseURL(String)

    var description: String {
        switch self {
        case .invalidJSON(let message):
            return "Invalid configuration JSON: \(message)"
        case .invalidEnvironmentValue(let message):
            return message
        case .invalidTimeout(let value):
            return "timeout must be between \(AppConfig.timeoutRange.lowerBound) and \(AppConfig.timeoutRange.upperBound) seconds, got \(value)"
        case .invalidMaxConnections(let value):
            return "maxConnections must be between \(AppConfig.maxConnectionsRange.lowerBound) and \(AppConfig.maxConnectionsRange.upperBound), got \(value)"
        case .invalidBaseURL(let value):
            return "baseURL must be a valid https URL, got \"\(value)\""
        }
    }
}

struct AppConfig: Equatable {
    static let defaultBaseURL = "https://localhost"
    static let defaultTimeout: Double = 30
    static let defaultMaxConnections: Int = 8

    static let timeoutRange: ClosedRange<Double> = 1...120
    static let maxConnectionsRange: ClosedRange<Int> = 1...64

    var baseURL: String
    var timeout: Double
    var maxConnections: Int

    /// Mirrors AppConfig's fields but leaves them optional so the JSON file
    /// may omit any subset of them and fall back to defaults.
    private struct RawConfig: Decodable {
        var baseURL: String?
        var timeout: Double?
        var maxConnections: Int?
    }

    static func load(
        fromFile path: String,
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) throws -> AppConfig {
        let data = try Data(contentsOf: URL(fileURLWithPath: path))

        let raw: RawConfig
        do {
            raw = try JSONDecoder().decode(RawConfig.self, from: data)
        } catch {
            throw AppConfigError.invalidJSON(error.localizedDescription)
        }

        var config = AppConfig(
            baseURL: raw.baseURL ?? defaultBaseURL,
            timeout: raw.timeout ?? defaultTimeout,
            maxConnections: raw.maxConnections ?? defaultMaxConnections
        )

        try config.applyEnvironmentOverrides(environment)
        try config.validate()
        return config
    }

    private mutating func applyEnvironmentOverrides(_ environment: [String: String]) throws {
        if let value = environment["APP_BASE_URL"] {
            baseURL = value
        }
        if let value = environment["APP_TIMEOUT"] {
            guard let parsed = Double(value) else {
                throw AppConfigError.invalidEnvironmentValue("APP_TIMEOUT must be a number, got \"\(value)\"")
            }
            timeout = parsed
        }
        if let value = environment["APP_MAX_CONNECTIONS"] {
            guard let parsed = Int(value) else {
                throw AppConfigError.invalidEnvironmentValue("APP_MAX_CONNECTIONS must be an integer, got \"\(value)\"")
            }
            maxConnections = parsed
        }
    }

    private func validate() throws {
        guard AppConfig.timeoutRange.contains(timeout) else {
            throw AppConfigError.invalidTimeout(timeout)
        }
        guard AppConfig.maxConnectionsRange.contains(maxConnections) else {
            throw AppConfigError.invalidMaxConnections(maxConnections)
        }
        guard let url = URL(string: baseURL), url.scheme == "https", url.host != nil, !url.host!.isEmpty else {
            throw AppConfigError.invalidBaseURL(baseURL)
        }
    }
}

import Foundation

/// Application configuration loaded from a JSON file, with defaults applied
/// for missing fields and overrides taken from `APP_`-prefixed environment variables.
public struct AppConfig: Codable, Equatable {
    public var baseURL: URL
    public var timeout: Double
    public var maxConnections: Int

    public static let defaultBaseURL = URL(string: "https://api.example.com")!
    public static let defaultTimeout: Double = 30
    public static let defaultMaxConnections = 8

    public static let timeoutRange: ClosedRange<Double> = 1...120
    public static let maxConnectionsRange: ClosedRange<Int> = 1...64

    public enum ConfigError: Error, CustomStringConvertible, Equatable {
        case fileNotFound(String)
        case invalidJSON(String)
        case invalidTimeout(Double)
        case invalidMaxConnections(Int)
        case invalidBaseURL(String)

        public var description: String {
            switch self {
            case .fileNotFound(let path):
                return "Configuration file not found at path: \(path)"
            case .invalidJSON(let message):
                return "Failed to parse configuration JSON: \(message)"
            case .invalidTimeout(let value):
                return "timeout must be between \(AppConfig.timeoutRange.lowerBound) and \(AppConfig.timeoutRange.upperBound) seconds, got \(value)"
            case .invalidMaxConnections(let value):
                return "maxConnections must be between \(AppConfig.maxConnectionsRange.lowerBound) and \(AppConfig.maxConnectionsRange.upperBound), got \(value)"
            case .invalidBaseURL(let value):
                return "baseURL must be a valid https URL, got \(value)"
            }
        }
    }

    private struct RawConfig: Decodable {
        var baseURL: String?
        var timeout: Double?
        var maxConnections: Int?
    }

    public init(
        baseURL: URL = AppConfig.defaultBaseURL,
        timeout: Double = AppConfig.defaultTimeout,
        maxConnections: Int = AppConfig.defaultMaxConnections
    ) {
        self.baseURL = baseURL
        self.timeout = timeout
        self.maxConnections = maxConnections
    }

    /// Loads configuration from the JSON file at `path`, filling in defaults for any
    /// missing fields, then applying overrides from `APP_BASE_URL`, `APP_TIMEOUT`,
    /// and `APP_MAX_CONNECTIONS` environment variables before validating ranges.
    public static func load(
        fromFile path: String,
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) throws -> AppConfig {
        guard FileManager.default.fileExists(atPath: path) else {
            throw ConfigError.fileNotFound(path)
        }

        let data = try Data(contentsOf: URL(fileURLWithPath: path))
        let raw: RawConfig
        do {
            raw = try JSONDecoder().decode(RawConfig.self, from: data)
        } catch {
            throw ConfigError.invalidJSON(error.localizedDescription)
        }

        var baseURLString = raw.baseURL ?? AppConfig.defaultBaseURL.absoluteString
        var timeout = raw.timeout ?? AppConfig.defaultTimeout
        var maxConnections = raw.maxConnections ?? AppConfig.defaultMaxConnections

        if let override = environment["APP_BASE_URL"] {
            baseURLString = override
        }
        if let override = environment["APP_TIMEOUT"], let value = Double(override) {
            timeout = value
        }
        if let override = environment["APP_MAX_CONNECTIONS"], let value = Int(override) {
            maxConnections = value
        }

        guard
            let baseURL = URL(string: baseURLString),
            baseURL.scheme?.lowercased() == "https",
            let host = baseURL.host, !host.isEmpty
        else {
            throw ConfigError.invalidBaseURL(baseURLString)
        }

        guard AppConfig.timeoutRange.contains(timeout) else {
            throw ConfigError.invalidTimeout(timeout)
        }

        guard AppConfig.maxConnectionsRange.contains(maxConnections) else {
            throw ConfigError.invalidMaxConnections(maxConnections)
        }

        return AppConfig(baseURL: baseURL, timeout: timeout, maxConnections: maxConnections)
    }
}
